INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_basic#6','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'match','auto','두 자료의 좋은 점과 아쉬운 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"match","stem":"두 자료의 좋은 점과 아쉬운 점을 알맞게 이으세요.","pairs":[{"l":"지구본의 좋은 점","r":"위치·면적·거리가 비교적 정확하다"},{"l":"지구본의 아쉬운 점","r":"한눈에 볼 수 없고 들고 다니기 불편하다"},{"l":"세계지도의 좋은 점","r":"한눈에 볼 수 있고 들고 다니기 편리하다"},{"l":"세계지도의 아쉬운 점","r":"위치·면적·거리가 실제와 다를 수 있다"}],"mis":"SO6-1-u3-X02","explanation":["공 모양은 실제에 가까워요.","평면은 한눈에 보여요.","둘 다 좋은 점과 아쉬운 점이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_basic#7','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','친구들이 말한 상황 가운데 ㉡에 더 알맞은 자료는 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"친구들이 말한 상황 가운데 ㉡에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"지구본","correct":true},{"t":"세계지도","mis":"SO6-1-u3-X05"},{"t":"국어사전","mis":"SO6-1-u3-X05"},{"t":"일기장","mis":"SO6-1-u3-X05"}],"explanation":["실제 지구의 모습이에요.","작게 줄인 모형이 있어요.","지구본이에요."],"asset":{"type":"passage","lines":["㉠ 세계를 한눈에 살펴보고 싶어.","㉡ 실제 지구의 모습을 살펴보고 싶어.","㉢ 가지고 다니기 편리한 자료면 좋겠어.","㉣ 여행 경로를 한눈에 볼 수 있게 나타내고 싶어.","㉤ 세계 여러 나라의 위치와 면적을 비교적 정확하게 보고 싶어."],"title":"친구들이 말한 다섯 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_basic#8','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','교실에서 두 자료를 견주었을 때 두 줄이 지나는 자리가 달랐던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X05','SO6-1-u3-X01','SO6-1-u3-X04']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"교실에서 두 자료를 견주었을 때 두 줄이 지나는 자리가 달랐던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평면에 펼친 세계지도와 공 모양 그대로인 지구본은 나타난 모습이 다르기 때문에","correct":true},{"t":"누군가 실수로 다른 두 자리를 이었기 때문에","mis":"SO6-1-u3-X05"},{"t":"자가 실보다 언제나 정확하기 때문에","mis":"SO6-1-u3-X01"},{"t":"두 자료를 만든 때가 서로 다르기 때문에","mis":"SO6-1-u3-X04"}],"explanation":["평면과 공 모양이에요.","펼치면 모습이 달라져요.","그래서 지나는 길이 달라요."],"asset":{"type":"passage","lines":["세계지도 — 멀리 떨어진 두 자리에 자를 대어 곧게 이었다.","지구본 — 같은 두 자리에 실을 매어 팽팽히 당겼다.","두 줄이 지나는 자리를 견주어 보니 서로 달랐다."],"title":"교실에서 두 자료 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_basic#9','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',2,'mc','auto','이야기 속 사람이 살던 곳을 찾으려 할 때 가장 먼저 도움이 될 자료는 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"이야기 속 사람이 살던 곳을 찾으려 할 때 가장 먼저 도움이 될 자료는 어느 것인가요?","options":[{"t":"세계의 모습을 나타낸 자료","correct":true},{"t":"기차 시간표만 모아 둔 책","mis":"SO6-1-u3-X05"},{"t":"어릴 적 그린 그림 한 장","mis":"SO6-1-u3-X05"},{"t":"친구에게 받은 편지","mis":"SO6-1-u3-X05"}],"explanation":["먼 곳에 내렸어요.","어디인지 찾아야 해요.","세계를 표현하는 자료가 필요해요."],"asset":{"type":"passage","lines":["어느 해, 기차에서 잠이 든 어린아이가 집에서 먼 곳에 내렸다.","어른이 된 그는 어릴 적 살던 집을 다시 찾아 나섰다.","기억에 남은 것은 크고 하얀 물탱크가 있던 기차역,","그리고 집 근처를 흐르던 강뿐이었다."],"title":"살던 곳을 다시 찾는 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_basic#10','soc',6,1,'u3','L01','g6_1_soc_u3_L01_basic','lesson_basic','SO6-1-u3-C3',3,'error','auto','두 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X01','SO6-1-u3-X05','SO6-1-u3-X03']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C3","difficulty":3,"kind":"error","stem":"두 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지구본이 세계지도보다 언제나 더 좋은 자료야.」","correct":true,"mis_target":"SO6-1-u3-X01"},{"t":"친구 가 — 「무엇을 하려는지에 따라 알맞은 자료를 골라.」","mis":"SO6-1-u3-X05"},{"t":"친구 다 — 「세계지도는 한눈에 보기 편리해.」","mis":"SO6-1-u3-X03"}],"explanation":["언제나 더 좋은 자료가 있을까요?","쓰임이 서로 달라요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#1','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',2,'sa','auto','친구들이 말한 상황 가운데 ㉢에 더 알맞은 자료의 이름을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"sa","stem":"친구들이 말한 상황 가운데 ㉢에 더 알맞은 자료의 이름을 네 글자로 쓰세요.","answer":["세계지도"],"explanation":["들고 다니기 편해야 해요.","접을 수 있어요.","세계지도예요."],"asset":{"type":"passage","lines":["㉠ 세계를 한눈에 살펴보고 싶어.","㉡ 실제 지구의 모습을 살펴보고 싶어.","㉢ 가지고 다니기 편리한 자료면 좋겠어.","㉣ 여행 경로를 한눈에 볼 수 있게 나타내고 싶어.","㉤ 세계 여러 나라의 위치와 면적을 비교적 정확하게 보고 싶어."],"title":"친구들이 말한 다섯 상황"},"mis":"SO6-1-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#2','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C2',2,'ox','auto','흔히 보는 세계지도에서 두 땅이 비슷하게 넓어 보이면 실제 넓이도 비슷해요.',ARRAY['SO6-1-u3-X03']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C2","difficulty":2,"kind":"ox","stem":"흔히 보는 세계지도에서 두 땅이 비슷하게 넓어 보이면 실제 넓이도 비슷해요.","answer":"X","reason_options":[{"t":"둥근 지구를 평면에 펼치면 넓이가 실제와 다르게 나타날 수 있기 때문에","correct":true},{"t":"세계지도는 넓이를 언제나 실제와 똑같이 나타내기 때문에","mis":"SO6-1-u3-X03"}],"mis":"SO6-1-u3-X03","explanation":["지구본과 견주어 봐요.","위쪽 땅이 훨씬 좁아요.","그래서 X예요."],"asset":{"type":"passage","lines":["흔히 보는 세계지도에서는 위쪽 땅과 아래쪽 땅이 비슷하게 넓어 보인다.","지구본에서 두 땅을 견주어 보면 위쪽 땅이 훨씬 좁다."],"title":"두 땅의 넓이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#3','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C2',3,'mc','auto','세계지도에서 위치·면적·거리가 실제와 다르게 나타날 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X04','SO6-1-u3-X06']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C2","difficulty":3,"kind":"mc","stem":"세계지도에서 위치·면적·거리가 실제와 다르게 나타날 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둥근 지구의 표면을 평면으로 펼쳐 나타냈기 때문에","correct":true},{"t":"지구본을 반으로 잘라 붙여 만들었기 때문에","mis":"SO6-1-u3-X04"},{"t":"하늘에서 찍은 사진을 그대로 썼기 때문에","mis":"SO6-1-u3-X06"},{"t":"나라마다 크기를 마음대로 정했기 때문에","mis":"SO6-1-u3-X04"}],"explanation":["지구는 둥글어요.","평면으로 펼쳐요.","그래서 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#4','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',3,'mc','auto','친구들이 말한 상황 가운데 지구본보다 세계지도가 더 알맞은 것을 모두 고른 것은 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구들이 말한 상황 가운데 지구본보다 세계지도가 더 알맞은 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉢, ㉣","correct":true},{"t":"㉡, ㉤","mis":"SO6-1-u3-X05"},{"t":"㉠, ㉡","mis":"SO6-1-u3-X05"},{"t":"㉢, ㉤","mis":"SO6-1-u3-X05"}],"explanation":["한눈에 볼 때예요.","들고 다닐 때예요.","㉠, ㉢, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 세계를 한눈에 살펴보고 싶어.","㉡ 실제 지구의 모습을 살펴보고 싶어.","㉢ 가지고 다니기 편리한 자료면 좋겠어.","㉣ 여행 경로를 한눈에 볼 수 있게 나타내고 싶어.","㉤ 세계 여러 나라의 위치와 면적을 비교적 정확하게 보고 싶어."],"title":"친구들이 말한 다섯 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#5','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C2',3,'mc','auto','사람들이 세계지도를 여러 가지 모양으로 만들기도 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X01','SO6-1-u3-X04']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C2","difficulty":3,"kind":"mc","stem":"사람들이 세계지도를 여러 가지 모양으로 만들기도 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평면에 펼치면 실제와 달라지는 부분이 생겨 목적에 맞게 나타내려고","correct":true},{"t":"지구의 모양이 해마다 바뀌기 때문에","mis":"SO6-1-u3-X03"},{"t":"모양이 많을수록 언제나 더 정확하기 때문에","mis":"SO6-1-u3-X01"},{"t":"지구본을 만들 수 없기 때문에","mis":"SO6-1-u3-X04"}],"explanation":["펼치면 달라지는 곳이 생겨요.","무엇을 보려는지가 달라요.","그래서 여러 모양으로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#6','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C1',3,'ox','auto','세계 여러 나라의 위치와 면적을 비교적 정확하게 살펴보려면 지구본이 알맞아요.',ARRAY['SO6-1-u3-X02']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C1","difficulty":3,"kind":"ox","stem":"세계 여러 나라의 위치와 면적을 비교적 정확하게 살펴보려면 지구본이 알맞아요.","answer":"O","reason_options":[{"t":"지구본은 실제 지구의 모습을 작게 줄여 만든 모형이기 때문에","correct":true},{"t":"지구본으로는 세계를 한눈에 모두 볼 수 있기 때문에","mis":"SO6-1-u3-X02"}],"mis":"SO6-1-u3-X02","explanation":["실제에 가까운 쪽이에요.","작게 줄인 모형이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#7','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C2',3,'error','auto','세계지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X02','SO6-1-u3-X04']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C2","difficulty":3,"kind":"error","stem":"세계지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세계지도는 면적과 거리가 실제와 똑같아.」","correct":true,"mis_target":"SO6-1-u3-X03"},{"t":"친구 가 — 「세계지도는 접어서 들고 다니기 편해.」","mis":"SO6-1-u3-X02"},{"t":"친구 나 — 「세계지도는 둥근 지구를 평면으로 나타낸 거야.」","mis":"SO6-1-u3-X04"}],"explanation":["평면으로 펼쳤어요.","실제와 다를 수 있어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#8','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',4,'mc','auto','두 자리를 잇는 길을 실제와 더 가깝게 알아보려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X05']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C3","difficulty":4,"kind":"mc","stem":"두 자리를 잇는 길을 실제와 더 가깝게 알아보려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"지구본에 실을 매어 이은 길을 살펴본다","correct":true},{"t":"세계지도에 자를 대어 이은 길만 믿는다","mis":"SO6-1-u3-X03"},{"t":"두 줄 가운데 더 곧게 보이는 줄을 고른다","mis":"SO6-1-u3-X03"},{"t":"두 자료 가운데 더 새것을 고른다","mis":"SO6-1-u3-X05"}],"explanation":["실제에 가까운 자료는 무엇일까요?","공 모양 그대로예요.","지구본으로 살펴봐요."],"asset":{"type":"passage","lines":["세계지도 — 멀리 떨어진 두 자리에 자를 대어 곧게 이었다.","지구본 — 같은 두 자리에 실을 매어 팽팽히 당겼다.","두 줄이 지나는 자리를 견주어 보니 서로 달랐다."],"title":"교실에서 두 자료 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#9','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',4,'mc','auto','「여러 나라의 면적을 견주고, 견준 결과를 친구들에게 한눈에 보여 주고 싶어.」에 알맞은 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X01','SO6-1-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C3","difficulty":4,"kind":"mc","stem":"「여러 나라의 면적을 견주고, 견준 결과를 친구들에게 한눈에 보여 주고 싶어.」에 알맞은 방법은 어느 것인가요?","options":[{"t":"면적은 지구본으로 견주고, 정리한 결과는 세계지도에 나타내 보여 준다","correct":true},{"t":"면적도 세계지도로만 견준다","mis":"SO6-1-u3-X03"},{"t":"지구본 하나로 모두 해결하고 세계지도는 쓰지 않는다","mis":"SO6-1-u3-X01"},{"t":"두 자료 없이 어림으로 정한다","mis":"SO6-1-u3-X05"}],"explanation":["견줄 때는 정확해야 해요.","보여 줄 때는 한눈에 보여야 해요.","두 자료를 나누어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L01_challenge#10','soc',6,1,'u3','L01','g6_1_soc_u3_L01_challenge','lesson_challenge','SO6-1-u3-C3',4,'essay','teacher','지구본과 세계지도의 좋은 점과 아쉬운 점을 하나씩 견주어 쓰고, 두 자료를 어떻게 골라 쓰면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C3","difficulty":4,"kind":"essay","stem":"지구본과 세계지도의 좋은 점과 아쉬운 점을 하나씩 견주어 쓰고, 두 자료를 어떻게 골라 쓰면 좋을지 쓰세요.","answer_guide":{"answer":"예: 지구본은 실제 지구의 모습을 작게 줄인 모형이라 위치·면적·거리가 비교적 정확하지만 한눈에 볼 수 없고 들고 다니기 불편하다. 세계지도는 둥근 지구를 평면에 펼친 것이라 한눈에 보고 들고 다니기 편리하지만 위치·면적·거리가 실제와 다를 수 있다. 두 자료는 좋고 나쁨이 아니라 쓰임이 다르므로 무엇을 하려는지에 따라 알맞은 자료를 골라 쓴다.","scoring_points":["지구본의 좋은 점과 아쉬운 점을 썼는가","세계지도의 좋은 점과 아쉬운 점을 썼는가","하려는 일에 따라 고른다고 썼는가"]},"explanation":["공 모양을 떠올려요.","평면을 떠올려요.","쓰임에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#1','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C4',1,'mc','auto','항공 사진이나 위성 영상에 장소나 지역의 이름, 경계선 등을 표시한 지도를 무엇이라고 하나요?',ARRAY['SO6-1-u3-X06']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C4","difficulty":1,"kind":"mc","stem":"항공 사진이나 위성 영상에 장소나 지역의 이름, 경계선 등을 표시한 지도를 무엇이라고 하나요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"지구본","mis":"SO6-1-u3-X06"},{"t":"종이 세계지도","mis":"SO6-1-u3-X06"},{"t":"그림 일기","mis":"SO6-1-u3-X06"}],"explanation":["사진이나 영상을 써요.","이름과 경계선을 더해요.","디지털 영상 지도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#2','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C5',1,'sa','auto','찾고 싶은 곳을 검색창에 넣어 지도에서 위치를 확인하는 기능은 무엇인가요? (    ) 검색에서 빈칸에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C5","difficulty":1,"kind":"sa","stem":"찾고 싶은 곳을 검색창에 넣어 지도에서 위치를 확인하는 기능은 무엇인가요? (    ) 검색에서 빈칸에 들어갈 두 글자를 쓰세요.","answer":["장소"],"explanation":["찾고 싶은 곳이에요.","◯◯ 검색이에요.","장소예요."],"mis":"SO6-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#3','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C6',1,'ox','auto','디지털 영상 지도는 화면을 늘리거나 줄일 수 없어요.',ARRAY['SO6-1-u3-X06']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C6","difficulty":1,"kind":"ox","stem":"디지털 영상 지도는 화면을 늘리거나 줄일 수 없어요.","answer":"X","reason_options":[{"t":"확대와 축소가 자유로워 자세히도, 넓게도 볼 수 있기 때문에","correct":true},{"t":"디지털 영상 지도는 종이에 한 번 그려 고정한 지도이기 때문에","mis":"SO6-1-u3-X06"}],"mis":"SO6-1-u3-X06","explanation":["늘렸다 줄였다 해 봐요.","확대와 축소가 자유로워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#4','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C5',1,'mc','auto','세계 여러 장소의 실제 모습을 그 자리에 서 있는 것처럼 사진으로 살펴보는 기능은 어느 것인가요?',ARRAY['SO6-1-u3-X07']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C5","difficulty":1,"kind":"mc","stem":"세계 여러 장소의 실제 모습을 그 자리에 서 있는 것처럼 사진으로 살펴보는 기능은 어느 것인가요?","options":[{"t":"거리 보기","correct":true},{"t":"거리 측정","mis":"SO6-1-u3-X07"},{"t":"지도 유형 설정","mis":"SO6-1-u3-X07"},{"t":"장소 검색","mis":"SO6-1-u3-X07"}],"explanation":["실제 모습이에요.","사진으로 봐요.","거리 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#5','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C5',2,'match','auto','기능 카드와 그 기능으로 할 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u3-C5","difficulty":2,"kind":"match","stem":"기능 카드와 그 기능으로 할 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"㉠ 장소 검색","r":"찾고 싶은 곳의 위치를 확인한다"},{"l":"㉡ 확대·축소","r":"지도를 늘리거나 줄인다"},{"l":"㉣ 거리 측정","r":"두 자리 사이의 곧은 거리를 확인한다"},{"l":"㉤ 지도 유형 설정","r":"원하는 지도로 바꾸어 본다"}],"mis":"SO6-1-u3-X07","explanation":["찾기 · 늘리고 줄이기예요.","재기예요.","바꾸어 보기예요."],"asset":{"type":"passage","lines":["㉠ 장소 검색","㉡ 확대·축소","㉢ 거리 보기","㉣ 거리 측정","㉤ 지도 유형 설정"],"title":"디지털 영상 지도의 기능 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#6','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C6',2,'mc','auto','디지털 영상 지도의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X06','SO6-1-u3-X09']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"mc","stem":"디지털 영상 지도의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"장소 간 거리나 이동 시간 같은 다양한 정보를 얻을 수 있다","correct":true},{"t":"한 번 켜면 화면을 늘리거나 줄일 수 없다","mis":"SO6-1-u3-X08"},{"t":"공 모양이라 손으로 돌려 본다","mis":"SO6-1-u3-X06"},{"t":"언제나 가장 좋은 자료라 다른 자료는 볼 필요가 없다","mis":"SO6-1-u3-X09"}],"explanation":["다양한 정보를 얻어요.","거리와 이동 시간이에요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#7','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C6',2,'blank','auto','디지털 영상 지도로 세계의 모습을 전체적으로 보려면 지도를 (    )하여 지구 모양이 나오게 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X07','SO6-1-u3-X06']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"blank","stem":"디지털 영상 지도로 세계의 모습을 전체적으로 보려면 지도를 (    )하여 지구 모양이 나오게 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"축소","correct":true},{"t":"확대","mis":"SO6-1-u3-X08"},{"t":"검색","mis":"SO6-1-u3-X07"},{"t":"인쇄","mis":"SO6-1-u3-X06"}],"explanation":["넓게 보려면요?","줄여야 해요.","축소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#8','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C6',2,'mc','auto','기록 ①과 ②를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X08']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"mc","stem":"기록 ①과 ②를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 자리도 확대·축소에 따라 한 번에 보이는 만큼이 달라진다","correct":true},{"t":"화면을 줄이면 다른 자리로 옮겨 간다","mis":"SO6-1-u3-X08"},{"t":"늘릴수록 넓은 곳이 한눈에 보인다","mis":"SO6-1-u3-X08"},{"t":"줄이면 건물과 길이 더 자세히 보인다","mis":"SO6-1-u3-X08"}],"explanation":["자리는 같아요.","줄이면 넓게, 늘리면 자세히예요.","보이는 만큼이 달라져요."],"asset":{"type":"passage","lines":["① 화면을 많이 줄이자 그 자리가 어느 쪽에 있는지 넓게 보였다.","② 화면을 늘리자 좁지만 건물과 길이 자세히 보였다.","③ 화면을 옮기자 앞에서 보이던 것은 사라졌다.","④ 수첩에 적어 둔 내용은 그대로 남아 있었다."],"title":"같은 자리를 화면을 옮기며 본 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#9','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C4',2,'mc','auto','디지털 영상 지도가 만들어지는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X04','SO6-1-u3-X06']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C4","difficulty":2,"kind":"mc","stem":"디지털 영상 지도가 만들어지는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"위에서 찍은 사진이나 영상 위에 이름과 경계선을 더한다","correct":true},{"t":"지구본의 표면을 펼쳐 빈 곳을 채운다","mis":"SO6-1-u3-X04"},{"t":"지구를 작게 줄여 공 모양으로 만든다","mis":"SO6-1-u3-X06"},{"t":"손으로 그린 그림만 모아 붙인다","mis":"SO6-1-u3-X06"}],"explanation":["위에서 찍었어요.","사진이나 영상이에요.","이름과 경계선을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_basic#10','soc',6,1,'u3','L02','g6_1_soc_u3_L02_basic','lesson_basic','SO6-1-u3-C6',3,'error','auto','디지털 영상 지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X09','SO6-1-u3-X07']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"error","stem":"디지털 영상 지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「화면으로 다 봤으니 따로 적어 두지 않아도 저절로 남아.」","correct":true,"mis_target":"SO6-1-u3-X09"},{"t":"친구 나 — 「궁금한 곳을 검색해 정보를 찾아볼 수 있어.」","mis":"SO6-1-u3-X07"},{"t":"친구 다 — 「알게 된 것으로 물음을 만들어 친구와 묻고 답해 보자.」","mis":"SO6-1-u3-X09"}],"explanation":["화면을 옮기면 어떻게 되나요?","보이던 것은 사라져요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#1','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C5',2,'sa','auto','두 자리 사이의 곧은 거리를 확인할 수 있는 기능 카드의 기호를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C5","difficulty":2,"kind":"sa","stem":"두 자리 사이의 곧은 거리를 확인할 수 있는 기능 카드의 기호를 쓰세요.","answer":["㉣"],"explanation":["재는 기능이에요.","거리 ◯◯이에요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 장소 검색","㉡ 확대·축소","㉢ 거리 보기","㉣ 거리 측정","㉤ 지도 유형 설정"],"title":"디지털 영상 지도의 기능 카드"},"mis":"SO6-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#2','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',2,'ox','auto','화면을 옮겼더니 앞에서 보이던 것이 사라졌으니, 살펴본 것은 적어 두어야 남아요.',ARRAY['SO6-1-u3-X09']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"ox","stem":"화면을 옮겼더니 앞에서 보이던 것이 사라졌으니, 살펴본 것은 적어 두어야 남아요.","answer":"O","reason_options":[{"t":"화면은 지금 보고 있는 것만 보여 주기 때문에","correct":true},{"t":"화면이 잘못 작동해서 생긴 일이기 때문에","mis":"SO6-1-u3-X09"}],"mis":"SO6-1-u3-X09","explanation":["수첩의 줄은 남았어요.","화면은 지금 것만 보여요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 화면을 많이 줄이자 그 자리가 어느 쪽에 있는지 넓게 보였다.","② 화면을 늘리자 좁지만 건물과 길이 자세히 보였다.","③ 화면을 옮기자 앞에서 보이던 것은 사라졌다.","④ 수첩에 적어 둔 내용은 그대로 남아 있었다."],"title":"같은 자리를 화면을 옮기며 본 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#3','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',3,'mc','auto','뒤섞인 살펴보기 차례를 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X08']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"mc","stem":"뒤섞인 살펴보기 차례를 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉯ → ㉰ → ㉮","correct":true},{"t":"㉮ → ㉯ → ㉰","mis":"SO6-1-u3-X08"},{"t":"㉰ → ㉮ → ㉯","mis":"SO6-1-u3-X08"},{"t":"㉯ → ㉮ → ㉰","mis":"SO6-1-u3-X08"}],"explanation":["먼저 들어가요.","줄여서 전체를 봐요.","그다음 여러 기능을 써요."],"asset":{"type":"passage","lines":["㉮ 확대·축소, 거리 보기 기능으로 세계의 모습을 살펴본다.","㉯ 인터넷으로 디지털 영상 지도 누리집에 들어간다.","㉰ 지도를 축소해 지구 모양이 나오게 한 뒤 전체 모습을 본다."],"title":"뒤섞인 살펴보기 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#4','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',3,'mc','auto','어느 장소가 세계의 어느 쪽에 있는지 먼저 알고 싶을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X07']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"mc","stem":"어느 장소가 세계의 어느 쪽에 있는지 먼저 알고 싶을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"화면을 넓게 줄여 그 자리의 둘레를 살펴본다","correct":true},{"t":"화면을 크게 늘려 건물 하나를 살펴본다","mis":"SO6-1-u3-X08"},{"t":"거리 보기로 길 한 곳의 사진만 본다","mis":"SO6-1-u3-X07"},{"t":"그 장소의 다녀온 사람 기록만 읽는다","mis":"SO6-1-u3-X07"}],"explanation":["어느 쪽인지 알려면요?","넓게 봐야 해요.","줄여서 둘레를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#5','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C5',3,'mc','auto','어느 장소를 검색했을 때 함께 살펴볼 수 있는 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X07']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C5","difficulty":3,"kind":"mc","stem":"어느 장소를 검색했을 때 함께 살펴볼 수 있는 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"그 장소에 바로 옮겨 가는 길","correct":true},{"t":"그 장소를 소개하는 글","mis":"SO6-1-u3-X07"},{"t":"그 장소로 가는 교통편","mis":"SO6-1-u3-X07"},{"t":"다녀온 사람들의 기록","mis":"SO6-1-u3-X07"}],"explanation":["검색하면 여러 정보가 나와요.","글·교통편·기록이에요.","바로 갈 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#6','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',3,'ox','auto','디지털 영상 지도가 있으면 지구본과 세계지도는 더 볼 필요가 없어요.',ARRAY['SO6-1-u3-X09']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"ox","stem":"디지털 영상 지도가 있으면 지구본과 세계지도는 더 볼 필요가 없어요.","answer":"X","reason_options":[{"t":"자료마다 쓰임이 달라 하려는 일에 따라 알맞은 자료를 고르기 때문에","correct":true},{"t":"디지털 영상 지도가 언제나 가장 좋은 자료이기 때문에","mis":"SO6-1-u3-X09"}],"mis":"SO6-1-u3-X09","explanation":["어느 자료도 언제나 낫지 않아요.","쓰임이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#7','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C5',3,'error','auto','기능을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X07']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C5","difficulty":3,"kind":"error","stem":"기능을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「거리 측정을 누르면 그 자리의 실제 모습이 사진으로 보여.」","correct":true,"mis_target":"SO6-1-u3-X07"},{"t":"친구 가 — 「지도 유형 설정으로 원하는 지도로 바꿀 수 있어.」","mis":"SO6-1-u3-X07"},{"t":"친구 다 — 「장소 검색으로 위치를 확인할 수 있어.」","mis":"SO6-1-u3-X07"}],"explanation":["실제 모습은 어느 기능일까요?","거리 보기예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#8','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',4,'mc','auto','같은 자리를 보는데 화면을 옮길 때마다 보이는 것이 달라진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X06','SO6-1-u3-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C6","difficulty":4,"kind":"mc","stem":"같은 자리를 보는데 화면을 옮길 때마다 보이는 것이 달라진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"확대와 축소에 따라 한 번에 보이는 만큼이 달라지기 때문에","correct":true},{"t":"화면을 옮길 때마다 다른 자리로 옮겨 갔기 때문에","mis":"SO6-1-u3-X08"},{"t":"화면마다 서로 다른 지도를 쓰기 때문에","mis":"SO6-1-u3-X06"},{"t":"디지털 영상 지도가 답을 감추어 두었기 때문에","mis":"SO6-1-u3-X09"}],"explanation":["자리는 처음부터 같았어요.","넓게 · 자세히 보는 차이예요.","보이는 만큼이 달라져요."],"asset":{"type":"passage","lines":["① 화면을 많이 줄이자 그 자리가 어느 쪽에 있는지 넓게 보였다.","② 화면을 늘리자 좁지만 건물과 길이 자세히 보였다.","③ 화면을 옮기자 앞에서 보이던 것은 사라졌다.","④ 수첩에 적어 둔 내용은 그대로 남아 있었다."],"title":"같은 자리를 화면을 옮기며 본 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#9','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C5',4,'mc','auto','처음 가는 장소에 가기 전에 「어떻게 가는지」와 「그곳의 실제 모습」을 알고 싶어요. 알맞은 기능을 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X07','SO6-1-u3-X08']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C5","difficulty":4,"kind":"mc","stem":"처음 가는 장소에 가기 전에 「어떻게 가는지」와 「그곳의 실제 모습」을 알고 싶어요. 알맞은 기능을 짝지은 것은 어느 것인가요?","options":[{"t":"장소 검색으로 교통편을 보고, 거리 보기로 실제 모습을 본다","correct":true},{"t":"거리 측정으로 교통편을 보고, 지도 유형 설정으로 실제 모습을 본다","mis":"SO6-1-u3-X07"},{"t":"확대·축소만 쓰면 두 가지를 모두 알 수 있다","mis":"SO6-1-u3-X08"},{"t":"지도 유형 설정만 쓰면 두 가지를 모두 알 수 있다","mis":"SO6-1-u3-X07"}],"explanation":["검색하면 교통편이 나와요.","실제 모습은 사진이에요.","검색과 거리 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L02_challenge#10','soc',6,1,'u3','L02','g6_1_soc_u3_L02_challenge','lesson_challenge','SO6-1-u3-C6',4,'essay','teacher','디지털 영상 지도의 특징 두 가지를 쓰고, 디지털 영상 지도로 살펴볼 때 지켜야 할 태도를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C6","difficulty":4,"kind":"essay","stem":"디지털 영상 지도의 특징 두 가지를 쓰고, 디지털 영상 지도로 살펴볼 때 지켜야 할 태도를 한 가지 쓰세요.","answer_guide":{"answer":"예: 디지털 영상 지도는 확대와 축소가 자유로워 특정 지역을 자세히 보거나 세계를 전체적으로 볼 수 있고, 사진이나 영상으로 실제 모습을 그대로 볼 수 있다. 화면은 지금 보이는 것만 보여 주므로 살펴본 것은 적어 두고, 언제나 가장 좋은 자료는 아니니 하려는 일에 따라 다른 자료와 함께 쓴다.","scoring_points":["특징 두 가지를 썼는가","살펴볼 때의 태도를 썼는가","태도의 까닭을 함께 썼는가"]},"explanation":["늘리고 줄이기를 떠올려요.","실제 모습을 떠올려요.","적어 두기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#1','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C7',1,'mc','auto','위도의 기준이 되는 위도 0° 선은 무엇인가요?',ARRAY['SO6-1-u3-X11']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C7","difficulty":1,"kind":"mc","stem":"위도의 기준이 되는 위도 0° 선은 무엇인가요?","options":[{"t":"적도","correct":true},{"t":"본초 자오선","mis":"SO6-1-u3-X11"},{"t":"경선","mis":"SO6-1-u3-X11"},{"t":"해안선","mis":"SO6-1-u3-X11"}],"explanation":["가로로 지나요.","위도 0°예요.","적도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#2','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C9',1,'sa','auto','경도의 기준이 되는 경도 0° 선을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C9","difficulty":1,"kind":"sa","stem":"경도의 기준이 되는 경도 0° 선을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["본초 자오선","본초자오선"],"explanation":["세로선이에요.","본초 ◯◯◯이에요.","본초 자오선이에요."],"mis":"SO6-1-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#3','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C7',1,'ox','auto','위도는 적도를 기준으로 남북으로 얼마나 떨어져 있는지 나타내요.',ARRAY['SO6-1-u3-X10']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C7","difficulty":1,"kind":"ox","stem":"위도는 적도를 기준으로 남북으로 얼마나 떨어져 있는지 나타내요.","answer":"O","reason_options":[{"t":"위도는 적도에서 북쪽과 남쪽으로 각각 90°씩 나뉘기 때문에","correct":true},{"t":"위도는 본초 자오선에서 동서로 떨어진 정도이기 때문에","mis":"SO6-1-u3-X10"}],"mis":"SO6-1-u3-X10","explanation":["기준은 적도예요.","남북이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#4','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C10',1,'mc','auto','세계 각 지역의 시간 차이를 무엇이라고 하나요?',ARRAY['SO6-1-u3-X16','SO6-1-u3-X15']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C10","difficulty":1,"kind":"mc","stem":"세계 각 지역의 시간 차이를 무엇이라고 하나요?","options":[{"t":"시차","correct":true},{"t":"위도","mis":"SO6-1-u3-X16"},{"t":"계절","mis":"SO6-1-u3-X15"},{"t":"경선","mis":"SO6-1-u3-X16"}],"explanation":["시간의 차이예요.","◯차예요.","시차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#5','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C9',2,'blank','auto','경도는 본초 자오선을 기준으로 동쪽과 서쪽으로 각각 (    )씩 나뉘어요. 빈칸에 알맞은 것은 무엇인가요?',ARRAY['SO6-1-u3-X12']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C9","difficulty":2,"kind":"blank","stem":"경도는 본초 자오선을 기준으로 동쪽과 서쪽으로 각각 (    )씩 나뉘어요. 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"180°","correct":true},{"t":"90°","mis":"SO6-1-u3-X12"},{"t":"30°","mis":"SO6-1-u3-X12"},{"t":"360°","mis":"SO6-1-u3-X12"}],"explanation":["동서로 나뉘어요.","위도보다 커요.","180°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#6','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C7',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C7","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"위선","r":"위도를 나타내는 가로선"},{"l":"경선","r":"경도를 나타내는 세로선"},{"l":"북위","r":"적도를 기준으로 북쪽"},{"l":"동경","r":"본초 자오선을 기준으로 동쪽"}],"mis":"SO6-1-u3-X13","explanation":["가로선과 세로선이에요.","적도 북쪽이에요.","본초 자오선 동쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#7','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C8',2,'mc','auto','같은 양의 햇볕을 받을 때 ㉠이 ㉡보다 기온이 높은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X14','SO6-1-u3-X15']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C8","difficulty":2,"kind":"mc","stem":"같은 양의 햇볕을 받을 때 ㉠이 ㉡보다 기온이 높은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"햇볕이 좁은 곳에 모여 열이 덜 퍼지기 때문에","correct":true},{"t":"햇볕이 넓은 곳으로 퍼지기 때문에","mis":"SO6-1-u3-X14"},{"t":"㉠이 태양과 아주 가깝기 때문에","mis":"SO6-1-u3-X15"},{"t":"㉡에는 햇볕이 아예 들지 않기 때문에","mis":"SO6-1-u3-X14"}],"explanation":["수직에 가깝게 들어와요.","좁은 곳에 모여요.","그래서 더 따뜻해요."],"asset":{"type":"passage","lines":["같은 양의 햇볕이 두 곳에 들어온다.","㉠ 적도 가까운 곳 — 햇볕이 수직에 가깝게 들어와 좁은 곳에 모인다.","㉡ 극 가까운 곳 — 햇볕이 비스듬하게 들어와 넓은 곳으로 퍼진다."],"title":"위도에 따라 달라지는 햇볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#8','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C10',2,'mc','auto','친구 다의 물음에 대한 답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X16','SO6-1-u3-X15']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C10","difficulty":2,"kind":"mc","stem":"친구 다의 물음에 대한 답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지구가 하루에 한 바퀴씩 스스로 돌아 경도에 따라 시각이 다르기 때문에","correct":true},{"t":"위도에 따라 햇볕을 받는 양이 다르기 때문에","mis":"SO6-1-u3-X16"},{"t":"경기를 하는 곳이 태양과 더 가깝기 때문에","mis":"SO6-1-u3-X15"},{"t":"지구가 기울어져 있기 때문에","mis":"SO6-1-u3-X15"}],"explanation":["지구는 스스로 돌아요.","경도에 따라 달라요.","그래서 시각이 달라요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"먼 곳에서 열린 경기를 새벽에 일어나서 봤어."},{"who":"친구 나","text":"그곳은 낮이었는데 우리는 새벽이었구나."},{"who":"친구 다","text":"같은 때인데 왜 이렇게 다를까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#9','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C9',2,'mc','auto','지구본에서 모든 경선이 모이는 곳은 어디인가요?',ARRAY['SO6-1-u3-X11']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C9","difficulty":2,"kind":"mc","stem":"지구본에서 모든 경선이 모이는 곳은 어디인가요?","options":[{"t":"북극과 남극","correct":true},{"t":"적도 위 한 점","mis":"SO6-1-u3-X11"},{"t":"본초 자오선 한가운데","mis":"SO6-1-u3-X11"},{"t":"지구본의 받침대","mis":"SO6-1-u3-X11"}],"explanation":["경선은 세로선이에요.","위와 아래 끝으로 모여요.","북극과 남극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_basic#10','soc',6,1,'u3','L03','g6_1_soc_u3_L03_basic','lesson_basic','SO6-1-u3-C8',3,'error','auto','두 반구의 계절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X15']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C8","difficulty":3,"kind":"error","stem":"두 반구의 계절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「맞은편 반구에는 햇볕이 아예 들지 않아서 겨울이야.」","correct":true,"mis_target":"SO6-1-u3-X15"},{"t":"친구 가 — 「지구가 기울어진 채 태양 주위를 돌아서 계절이 바뀌어.」","mis":"SO6-1-u3-X15"},{"t":"친구 나 — 「한쪽이 여름이면 맞은편은 겨울이야.」","mis":"SO6-1-u3-X15"}],"explanation":["햇볕이 아예 안 들까요?","기울어져 덜 받아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#1','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C7',2,'sa','auto','위도는 적도를 기준으로 북쪽과 남쪽으로 각각 몇 °씩 나뉘나요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C7","difficulty":2,"kind":"sa","stem":"위도는 적도를 기준으로 북쪽과 남쪽으로 각각 몇 °씩 나뉘나요? 숫자만 쓰세요.","answer":["90"],"explanation":["남북이에요.","경도의 절반이에요.","90°예요."],"mis":"SO6-1-u3-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#2','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C10',2,'ox','auto','우리가 새벽일 때 다른 지역은 낮일 수 있어요.',ARRAY['SO6-1-u3-X16']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C10","difficulty":2,"kind":"ox","stem":"우리가 새벽일 때 다른 지역은 낮일 수 있어요.","answer":"O","reason_options":[{"t":"경도에 따라 시각이 달라 시차가 생기기 때문에","correct":true},{"t":"위도에 따라 햇볕을 받는 양이 다르기 때문에","mis":"SO6-1-u3-X16"}],"mis":"SO6-1-u3-X16","explanation":["경기를 새벽에 봤어요.","그곳은 낮이었어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"먼 곳에서 열린 경기를 새벽에 일어나서 봤어."},{"who":"친구 나","text":"그곳은 낮이었는데 우리는 새벽이었구나."},{"who":"친구 다","text":"같은 때인데 왜 이렇게 다를까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#3','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C8',3,'mc','auto','㉮처럼 남북으로만 옮겼을 때 달라지는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X17']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C8","difficulty":3,"kind":"mc","stem":"㉮처럼 남북으로만 옮겼을 때 달라지는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"햇볕을 받는 양","correct":true},{"t":"시각","mis":"SO6-1-u3-X17"},{"t":"경도","mis":"SO6-1-u3-X17"},{"t":"아무것도 달라지지 않는다","mis":"SO6-1-u3-X17"}],"explanation":["남북은 위도예요.","위도는 햇볕과 이어져요.","햇볕을 받는 양이에요."],"asset":{"type":"passage","lines":["㉮ 한 자리에서 남북으로만 옮겨 보았다.","㉯ 같은 자리에서 동서로만 옮겨 보았다."],"title":"자리 옮겨 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#4','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C10',3,'mc','auto','㉯처럼 동서로만 옮겼을 때 달라지는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X17']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C10","difficulty":3,"kind":"mc","stem":"㉯처럼 동서로만 옮겼을 때 달라지는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"시각","correct":true},{"t":"햇볕을 받는 양","mis":"SO6-1-u3-X17"},{"t":"위도","mis":"SO6-1-u3-X17"},{"t":"계절","mis":"SO6-1-u3-X17"}],"explanation":["동서는 경도예요.","경도는 시각과 이어져요.","시각이에요."],"asset":{"type":"passage","lines":["㉮ 한 자리에서 남북으로만 옮겨 보았다.","㉯ 같은 자리에서 동서로만 옮겨 보았다."],"title":"자리 옮겨 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#5','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C10',3,'mc','auto','같은 나라 안에서도 기준이 되는 경선을 정해 그 시각을 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X11','SO6-1-u3-X16']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C10","difficulty":3,"kind":"mc","stem":"같은 나라 안에서도 기준이 되는 경선을 정해 그 시각을 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자리마다 시각이 다르면 서로 오가고 약속할 때 불편하기 때문에","correct":true},{"t":"경선은 하나만 그을 수 있기 때문에","mis":"SO6-1-u3-X11"},{"t":"위도가 같으면 시각도 같기 때문에","mis":"SO6-1-u3-X16"},{"t":"지구가 스스로 돌지 않기 때문에","mis":"SO6-1-u3-X16"}],"explanation":["자리마다 경도가 조금씩 달라요.","시각이 다 다르면 불편해요.","그래서 하나를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#6','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C13',3,'ox','auto','적도를 기준으로 남쪽은 북위, 북쪽은 남위라고 해요.',ARRAY['SO6-1-u3-X13']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C13","difficulty":3,"kind":"ox","stem":"적도를 기준으로 남쪽은 북위, 북쪽은 남위라고 해요.","answer":"X","reason_options":[{"t":"적도 북쪽이 북위이고 남쪽이 남위이기 때문에","correct":true},{"t":"위도는 본초 자오선을 기준으로 나누기 때문에","mis":"SO6-1-u3-X13"}],"mis":"SO6-1-u3-X13","explanation":["이름에 방향이 들어 있어요.","북쪽은 북위예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#7','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C9',3,'error','auto','위도와 경도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X10','SO6-1-u3-X11','SO6-1-u3-X13']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C9","difficulty":3,"kind":"error","stem":"위도와 경도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「경도는 적도를 기준으로 남북으로 떨어진 정도야.」","correct":true,"mis_target":"SO6-1-u3-X10"},{"t":"친구 나 — 「위선은 가로선, 경선은 세로선이야.」","mis":"SO6-1-u3-X11"},{"t":"친구 다 — 「본초 자오선의 서쪽은 서경이야.」","mis":"SO6-1-u3-X13"}],"explanation":["경도의 기준은 무엇일까요?","본초 자오선이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#8','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C8',4,'mc','auto','적도에서 먼 곳으로 갈수록 기온이 대체로 낮아지는 까닭을 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X17','SO6-1-u3-X15','SO6-1-u3-X14']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C8","difficulty":4,"kind":"mc","stem":"적도에서 먼 곳으로 갈수록 기온이 대체로 낮아지는 까닭을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"고위도로 갈수록 햇볕이 비스듬하게 들어와 같은 양의 햇볕이 넓게 퍼지기 때문에","correct":true},{"t":"고위도로 갈수록 시차가 커지기 때문에","mis":"SO6-1-u3-X17"},{"t":"고위도로 갈수록 태양에서 아주 멀어지기 때문에","mis":"SO6-1-u3-X15"},{"t":"고위도에는 경선이 모이기 때문에","mis":"SO6-1-u3-X14"}],"explanation":["같은 양의 햇볕이에요.","비스듬하면 넓게 퍼져요.","그래서 기온이 낮아요."],"asset":{"type":"passage","lines":["같은 양의 햇볕이 두 곳에 들어온다.","㉠ 적도 가까운 곳 — 햇볕이 수직에 가깝게 들어와 좁은 곳에 모인다.","㉡ 극 가까운 곳 — 햇볕이 비스듬하게 들어와 넓은 곳으로 퍼진다."],"title":"위도에 따라 달라지는 햇볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#9','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C9',4,'mc','auto','「본초 자오선의 바로 동쪽과 바로 서쪽에 있는 두 곳」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X13','SO6-1-u3-X10']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C9","difficulty":4,"kind":"mc","stem":"「본초 자오선의 바로 동쪽과 바로 서쪽에 있는 두 곳」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 곳은 동경, 다른 곳은 서경으로 나타낸다","correct":true},{"t":"두 곳 모두 동경으로 나타낸다","mis":"SO6-1-u3-X13"},{"t":"두 곳 모두 북위로 나타낸다","mis":"SO6-1-u3-X10"},{"t":"두 곳은 경도가 아니라 위도로만 나타낸다","mis":"SO6-1-u3-X10"}],"explanation":["기준선의 양쪽이에요.","동쪽은 동경이에요.","서쪽은 서경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L03_challenge#10','soc',6,1,'u3','L03','g6_1_soc_u3_L03_challenge','lesson_challenge','SO6-1-u3-C10',4,'essay','teacher','위도와 경도가 무엇인지 각각 쓰고, 위도가 달라지면 무엇이, 경도가 달라지면 무엇이 달라지는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C10","difficulty":4,"kind":"essay","stem":"위도와 경도가 무엇인지 각각 쓰고, 위도가 달라지면 무엇이, 경도가 달라지면 무엇이 달라지는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 위도는 적도를 기준으로 남북으로 떨어진 정도이고, 경도는 본초 자오선을 기준으로 동서로 떨어진 정도이다. 지구는 둥글어서 위도가 달라지면 햇볕을 받는 양이 달라져 기온이 달라진다. 지구가 하루에 한 바퀴씩 스스로 돌기 때문에 경도가 달라지면 시각이 달라져 시차가 생긴다.","scoring_points":["위도와 경도의 뜻을 썼는가","위도와 햇볕(기온)을 까닭과 함께 이었는가","경도와 시각(시차)을 까닭과 함께 이었는가"]},"explanation":["기준선을 떠올려요.","둥근 지구와 햇볕이에요.","스스로 도는 지구와 시각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#1','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C11',1,'mc','auto','지구본이나 세계지도에서 위치를 표현하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X18']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C11","difficulty":1,"kind":"mc","stem":"지구본이나 세계지도에서 위치를 표현하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"위선과 경선이 만나는 지점으로 나타낸다","correct":true},{"t":"위선 하나만으로 나타낸다","mis":"SO6-1-u3-X18"},{"t":"경선 하나만으로 나타낸다","mis":"SO6-1-u3-X18"},{"t":"땅의 높낮이로 나타낸다","mis":"SO6-1-u3-X18"}],"explanation":["두 선이 있어요.","만나는 곳은 하나예요.","만나는 지점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#2','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C12',1,'sa','auto','적도가 지나는 나라에는 케냐, 에콰도르, (    ) 등이 있어요. 빈칸에 알맞은 나라 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C12","difficulty":1,"kind":"sa","stem":"적도가 지나는 나라에는 케냐, 에콰도르, (    ) 등이 있어요. 빈칸에 알맞은 나라 이름을 쓰세요.","answer":["인도네시아"],"explanation":["적도가 지나는 섬나라예요.","인도◯◯◯예요.","인도네시아예요."],"mis":"SO6-1-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#3','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C11',1,'ox','auto','위선 하나만 정하면 위치가 하나로 정해져요.',ARRAY['SO6-1-u3-X18']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C11","difficulty":1,"kind":"ox","stem":"위선 하나만 정하면 위치가 하나로 정해져요.","answer":"X","reason_options":[{"t":"위선 하나 위에도 여러 자리가 있어 경선과 만나야 하나로 정해지기 때문에","correct":true},{"t":"위선은 위치를 나타내는 데 쓰이지 않기 때문에","mis":"SO6-1-u3-X18"}],"mis":"SO6-1-u3-X18","explanation":["가로선 위의 자리를 세어 봐요.","여러 개예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#4','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C12',1,'mc','auto','본초 자오선이 지나는 나라로만 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X20','SO6-1-u3-X21']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C12","difficulty":1,"kind":"mc","stem":"본초 자오선이 지나는 나라로만 짝지은 것은 어느 것인가요?","options":[{"t":"영국, 프랑스, 알제리","correct":true},{"t":"케냐, 인도네시아, 에콰도르","mis":"SO6-1-u3-X20"},{"t":"미국, 브라질, 오스트레일리아","mis":"SO6-1-u3-X21"},{"t":"본초 자오선이 지나는 나라는 없다","mis":"SO6-1-u3-X20"}],"explanation":["경도 0° 선이에요.","세로로 지나요.","영국·프랑스·알제리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#5','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C11',2,'blank','auto','자리를 나타낼 때에는 위도와 (    )를 함께 써요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X18']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C11","difficulty":2,"kind":"blank","stem":"자리를 나타낼 때에는 위도와 (    )를 함께 써요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"경도","correct":true},{"t":"시차","mis":"SO6-1-u3-X18"},{"t":"높이","mis":"SO6-1-u3-X18"},{"t":"계절","mis":"SO6-1-u3-X18"}],"explanation":["가로선과 세로선이에요.","세로선은 경선이에요.","경도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#6','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C12',2,'mc','auto','㉮ 범위가 속한 나라는 어느 것인가요?',ARRAY['SO6-1-u3-X21','SO6-1-u3-X20']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"mc","stem":"㉮ 범위가 속한 나라는 어느 것인가요?","options":[{"t":"미국","correct":true},{"t":"브라질","mis":"SO6-1-u3-X21"},{"t":"오스트레일리아","mis":"SO6-1-u3-X21"},{"t":"케냐","mis":"SO6-1-u3-X20"}],"explanation":["북위예요.","서경이에요.","미국이에요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#7','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C12',2,'mc','auto','㉯ 범위가 속한 나라는 어느 것인가요?',ARRAY['SO6-1-u3-X21','SO6-1-u3-X20']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"mc","stem":"㉯ 범위가 속한 나라는 어느 것인가요?","options":[{"t":"브라질","correct":true},{"t":"미국","mis":"SO6-1-u3-X21"},{"t":"오스트레일리아","mis":"SO6-1-u3-X21"},{"t":"영국","mis":"SO6-1-u3-X20"}],"explanation":["남위예요.","서경이에요.","브라질이에요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#8','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C11',2,'mc','auto','친구 다가 「왼쪽에서 둘째 칸」을 더 말하려는 까닭과 같은 원리는 어느 것인가요?',ARRAY['SO6-1-u3-X19','SO6-1-u3-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C11","difficulty":2,"kind":"mc","stem":"친구 다가 「왼쪽에서 둘째 칸」을 더 말하려는 까닭과 같은 원리는 어느 것인가요?","options":[{"t":"위선 하나만으로는 자리가 여럿이라 경선을 함께 말해야 한다","correct":true},{"t":"경선을 먼저 말해야 자리가 달라진다","mis":"SO6-1-u3-X19"},{"t":"줄 이름만 말해도 자리는 하나로 정해진다","mis":"SO6-1-u3-X18"},{"t":"자리는 높낮이로만 말할 수 있다","mis":"SO6-1-u3-X18"}],"explanation":["셋째 줄에 자리가 여럿이에요.","칸을 더하면 하나가 돼요.","위선과 경선도 같아요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"내 자리는 셋째 줄이야."},{"who":"친구 나","text":"셋째 줄에는 자리가 여러 개인데?"},{"who":"친구 다","text":"그럼 왼쪽에서 둘째 칸까지 말해야겠네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#9','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C13',2,'mc','auto','이야기 속 사람의 직업으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X22']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C13","difficulty":2,"kind":"mc","stem":"이야기 속 사람의 직업으로 알맞은 것은 어느 것인가요?","options":[{"t":"공간 정보 연구원","correct":true},{"t":"외교관","mis":"SO6-1-u3-X22"},{"t":"기상 캐스터","mis":"SO6-1-u3-X22"},{"t":"여행 안내원","mis":"SO6-1-u3-X22"}],"explanation":["공간상의 정보예요.","만들고 활용해요.","공간 정보 연구원이에요."],"asset":{"type":"passage","lines":["공간상에 있는 물체의 크기와 높이를 바탕으로 정보를 만든다.","도로·교통·도시 계획 등 여러 분야에서 목적에 맞게 활용한다.","국토를 효율적으로 관리하는 데에도 활용한다."],"title":"어떤 직업 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_basic#10','soc',6,1,'u3','L04','g6_1_soc_u3_L04_basic','lesson_basic','SO6-1-u3-C11',3,'error','auto','위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X19','SO6-1-u3-X18']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C11","difficulty":3,"kind":"error","stem":"위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「경선을 먼저 그으면 만나는 지점이 달라져.」","correct":true,"mis_target":"SO6-1-u3-X19"},{"t":"친구 가 — 「위선과 경선이 만나는 지점은 하나야.」","mis":"SO6-1-u3-X18"},{"t":"친구 다 — 「위도와 경도를 함께 써야 자리가 정해져.」","mis":"SO6-1-u3-X18"}],"explanation":["차례를 바꾸어 봐요.","만나는 곳은 같아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#1','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C12',2,'sa','auto','㉰ 범위가 속한 나라 이름을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"sa","stem":"㉰ 범위가 속한 나라 이름을 쓰세요.","answer":["오스트레일리아","호주"],"explanation":["남위예요.","동경이에요.","오스트레일리아예요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"},"mis":"SO6-1-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#2','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C13',2,'ox','auto','지도도 대표적인 공간 정보예요.',ARRAY['SO6-1-u3-X22']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C13","difficulty":2,"kind":"ox","stem":"지도도 대표적인 공간 정보예요.","answer":"O","reason_options":[{"t":"공간상에 있는 물체의 위치나 특성을 나타낸 정보이기 때문에","correct":true},{"t":"공간 정보는 다른 사람이 볼 수 없게 감추는 정보이기 때문에","mis":"SO6-1-u3-X22"}],"mis":"SO6-1-u3-X22","explanation":["위치를 나타내요.","특성도 나타내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#3','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C12',3,'mc','auto','㉮~㉰를 보고 나라를 찾을 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X21','SO6-1-u3-X18']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"㉮~㉰를 보고 나라를 찾을 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"북위인지 남위인지, 동경인지 서경인지 먼저 가린다","correct":true},{"t":"위도만 보고 경도는 나중에 생각하지 않는다","mis":"SO6-1-u3-X21"},{"t":"숫자가 큰 범위부터 고른다","mis":"SO6-1-u3-X21"},{"t":"경도만 보면 나라가 하나로 정해진다","mis":"SO6-1-u3-X18"}],"explanation":["방향이 반대면 전혀 다른 곳이에요.","반구를 먼저 가려요.","그다음 범위를 함께 봐요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#4','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C12',3,'mc','auto','적도와 본초 자오선이 지나는 나라에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X20']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"적도와 본초 자오선이 지나는 나라에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"케냐에는 적도가, 영국에는 본초 자오선이 지난다","correct":true},{"t":"케냐에는 본초 자오선이, 영국에는 적도가 지난다","mis":"SO6-1-u3-X20"},{"t":"두 선 모두 한 나라에만 지난다","mis":"SO6-1-u3-X20"},{"t":"적도는 아무 나라도 지나지 않는다","mis":"SO6-1-u3-X20"}],"explanation":["적도는 가로선이에요.","본초 자오선은 세로선이에요.","케냐와 영국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#5','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C11',3,'mc','auto','경선 하나만 정했을 때 자리가 하나로 정해지지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X18','SO6-1-u3-X19','SO6-1-u3-X11']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C11","difficulty":3,"kind":"mc","stem":"경선 하나만 정했을 때 자리가 하나로 정해지지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"경선 하나 위에도 여러 자리가 있기 때문에","correct":true},{"t":"경선은 위치를 나타내는 데 쓰이지 않기 때문에","mis":"SO6-1-u3-X18"},{"t":"경선은 위선보다 먼저 그어야 하기 때문에","mis":"SO6-1-u3-X19"},{"t":"경선은 적도에서만 쓸 수 있기 때문에","mis":"SO6-1-u3-X11"}],"explanation":["세로선 위를 따라가 봐요.","자리가 여럿이에요.","위선과 만나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#6','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C13',3,'ox','auto','공간 정보 연구원이 되려면 컴퓨터를 다루는 능력과 시각적 이미지를 정확하게 파악하는 능력이 도움이 돼요.',ARRAY['SO6-1-u3-X22']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C13","difficulty":3,"kind":"ox","stem":"공간 정보 연구원이 되려면 컴퓨터를 다루는 능력과 시각적 이미지를 정확하게 파악하는 능력이 도움이 돼요.","answer":"O","reason_options":[{"t":"공간 정보를 만들고 지도 같은 이미지를 정확하게 읽어 활용하기 때문에","correct":true},{"t":"공간 정보 연구원은 정보를 감추는 일만 하기 때문에","mis":"SO6-1-u3-X22"}],"mis":"SO6-1-u3-X22","explanation":["정보를 만들어요.","이미지를 읽어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#7','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C13',3,'error','auto','공간 정보 연구원을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X22']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C13","difficulty":3,"kind":"error","stem":"공간 정보 연구원을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「만든 공간 정보를 아무도 못 보게 감추는 일을 해.」","correct":true,"mis_target":"SO6-1-u3-X22"},{"t":"친구 가 — 「도로나 교통 같은 분야에 공간 정보를 활용해.」","mis":"SO6-1-u3-X22"},{"t":"친구 나 — 「국토를 효율적으로 관리하는 데에도 써.」","mis":"SO6-1-u3-X22"}],"explanation":["정보를 만드는 까닭은요?","여러 분야에 활용하려고요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#8','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C12',4,'mc','auto','「북위 30°~40°」만 알고 경도를 모를 때 일어나는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X18','SO6-1-u3-X13','SO6-1-u3-X21']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C12","difficulty":4,"kind":"mc","stem":"「북위 30°~40°」만 알고 경도를 모를 때 일어나는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 위도 범위에 여러 나라가 있어 나라를 하나로 좁히기 어렵다","correct":true},{"t":"위도만 알아도 나라가 언제나 하나로 정해진다","mis":"SO6-1-u3-X18"},{"t":"남반구의 나라로 정해진다","mis":"SO6-1-u3-X13"},{"t":"경도는 위도를 알면 저절로 정해진다","mis":"SO6-1-u3-X21"}],"explanation":["가로로 긴 띠를 떠올려요.","그 띠에 나라가 여럿이에요.","경도를 함께 봐야 해요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#9','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C11',4,'mc','auto','두 친구가 같은 자리를 찾는데 한 친구는 위선부터, 다른 친구는 경선부터 그었어요. 결과로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X19','SO6-1-u3-X18']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C11","difficulty":4,"kind":"mc","stem":"두 친구가 같은 자리를 찾는데 한 친구는 위선부터, 다른 친구는 경선부터 그었어요. 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"두 선이 만나는 지점이 같아 같은 자리를 찾는다","correct":true},{"t":"먼저 그은 선에 따라 서로 다른 자리를 찾는다","mis":"SO6-1-u3-X19"},{"t":"위선부터 그은 친구만 자리를 찾는다","mis":"SO6-1-u3-X19"},{"t":"두 친구 모두 자리를 찾을 수 없다","mis":"SO6-1-u3-X18"}],"explanation":["만나는 곳은 어디일까요?","차례와 관계없어요.","같은 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L04_challenge#10','soc',6,1,'u3','L04','g6_1_soc_u3_L04_challenge','lesson_challenge','SO6-1-u3-C11',4,'essay','teacher','지구본이나 세계지도에서 한 자리를 나타낼 때 위도와 경도를 함께 써야 하는 까닭을 쓰고, ㉯ 범위의 자리를 찾는 차례를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C11","difficulty":4,"kind":"essay","stem":"지구본이나 세계지도에서 한 자리를 나타낼 때 위도와 경도를 함께 써야 하는 까닭을 쓰고, ㉯ 범위의 자리를 찾는 차례를 쓰세요.","answer_guide":{"answer":"예: 위선 하나 위에도, 경선 하나 위에도 여러 자리가 있어서 한 선만으로는 자리가 하나로 정해지지 않고, 두 선이 만나야 하나로 정해지므로 위도와 경도를 함께 쓴다. ㉯는 먼저 남위이므로 적도의 남쪽, 서경이므로 본초 자오선의 서쪽을 가린 뒤, 남위 10°~20°와 서경 40°~50°가 겹치는 곳을 찾으면 브라질에 속한다.","scoring_points":["한 선만으로 정해지지 않는 까닭을 썼는가","반구(남위·서경)를 먼저 가렸는가","두 범위가 겹치는 곳을 찾는다고 썼는가"]},"explanation":["선 하나 위의 자리를 세어 봐요.","방향을 먼저 가려요.","두 범위를 겹쳐요."],"asset":{"type":"passage","lines":["㉮ 북위 30°~40°, 서경 90°~100°","㉯ 남위 10°~20°, 서경 40°~50°","㉰ 남위 20°~30°, 동경 120°~130°"],"title":"범위로 나타낸 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#1','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C14',1,'mc','auto','바다로 둘러싸인 커다란 육지를 무엇이라고 하나요?',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C14","difficulty":1,"kind":"mc","stem":"바다로 둘러싸인 커다란 육지를 무엇이라고 하나요?","options":[{"t":"대륙","correct":true},{"t":"대양","mis":"SO6-1-u3-X23"},{"t":"반도","mis":"SO6-1-u3-X23"},{"t":"섬","mis":"SO6-1-u3-X23"}],"explanation":["육지예요.","아주 커요.","대륙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#2','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C14',1,'sa','auto','세계의 바다 가운데 넓은 바다를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C14","difficulty":1,"kind":"sa","stem":"세계의 바다 가운데 넓은 바다를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["대양"],"explanation":["넓은 바다예요.","대◯이에요.","대양이에요."],"mis":"SO6-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#3','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',1,'ox','auto','세계에서 가장 넓은 대륙은 아시아예요.',ARRAY['SO6-1-u3-X25']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"ox","stem":"세계에서 가장 넓은 대륙은 아시아예요.","answer":"O","reason_options":[{"t":"일곱 대륙 가운데 아시아의 면적이 가장 넓기 때문에","correct":true},{"t":"아시아는 사람이 살 수 없는 대륙이기 때문에","mis":"SO6-1-u3-X25"}],"mis":"SO6-1-u3-X25","explanation":["대륙 일곱을 떠올려요.","가장 넓은 대륙이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#4','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',1,'mc','auto','세계에서 가장 넓은 대양은 어느 것인가요?',ARRAY['SO6-1-u3-X25']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"mc","stem":"세계에서 가장 넓은 대양은 어느 것인가요?","options":[{"t":"태평양","correct":true},{"t":"대서양","mis":"SO6-1-u3-X25"},{"t":"인도양","mis":"SO6-1-u3-X25"},{"t":"북극해","mis":"SO6-1-u3-X25"}],"explanation":["네 대륙 사이에 있어요.","가장 넓어요.","태평양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#5','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C14',2,'mc','auto','대양을 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X24']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C14","difficulty":2,"kind":"mc","stem":"대양을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"태평양, 대서양, 인도양, 북극해, 남극해","correct":true},{"t":"태평양, 대서양, 인도양, 유럽, 남극해","mis":"SO6-1-u3-X24"},{"t":"아시아, 오세아니아, 유럽, 아프리카, 남극 대륙","mis":"SO6-1-u3-X24"},{"t":"태평양, 대서양, 아시아, 북극해, 남극해","mis":"SO6-1-u3-X24"}],"explanation":["바다의 이름만 골라요.","대륙 이름이 섞이면 안 돼요.","첫째 묶음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#6','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',2,'match','auto','대양 설명 카드와 대양을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"match","stem":"대양 설명 카드와 대양을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"남극해"},{"l":"㉡","r":"북극해"},{"l":"㉢","r":"태평양"},{"l":"㉣","r":"인도양"}],"mis":"SO6-1-u3-X26","explanation":["남극 대륙을 둘러싸요.","북극 주변이에요.","가장 넓은 것과 세 번째로 넓은 것이에요."],"asset":{"type":"passage","lines":["㉠ 남극 대륙을 둘러싸고 있다.","㉡ 아시아·유럽·북아메리카 대륙에 둘러싸인 북극 주변의 바다이다.","㉢ 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있다.","㉣ 세 번째로 넓은 대양으로 아시아·아프리카·오세아니아에 접해 있다."],"title":"대양 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#7','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',2,'blank','auto','대서양, 인도양, 태평양을 넓은 차례로 늘어놓으면 태평양 → (    ) → 인도양이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X25','SO6-1-u3-X24']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"blank","stem":"대서양, 인도양, 태평양을 넓은 차례로 늘어놓으면 태평양 → (    ) → 인도양이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"대서양","correct":true},{"t":"북극해","mis":"SO6-1-u3-X25"},{"t":"남극해","mis":"SO6-1-u3-X25"},{"t":"아시아","mis":"SO6-1-u3-X24"}],"explanation":["세 대양을 견주어요.","가운데 차례예요.","대서양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#8','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',2,'mc','auto','대부분 남반구에 있는 대륙끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"mc","stem":"대부분 남반구에 있는 대륙끼리 짝지은 것은 어느 것인가요?","options":[{"t":"오세아니아, 남아메리카, 남극 대륙","correct":true},{"t":"아시아, 유럽, 아프리카","mis":"SO6-1-u3-X27"},{"t":"북아메리카, 유럽, 아시아","mis":"SO6-1-u3-X27"},{"t":"아시아, 오세아니아, 북아메리카","mis":"SO6-1-u3-X27"}],"explanation":["적도의 아래쪽이에요.","셋이에요.","오세아니아·남아메리카·남극 대륙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#9','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C14',2,'mc','auto','이름 카드에서 대륙의 이름은 모두 몇 개인가요?',ARRAY['SO6-1-u3-X24']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C14","difficulty":2,"kind":"mc","stem":"이름 카드에서 대륙의 이름은 모두 몇 개인가요?","options":[{"t":"일곱 개","correct":true},{"t":"다섯 개","mis":"SO6-1-u3-X24"},{"t":"여섯 개","mis":"SO6-1-u3-X24"},{"t":"열두 개","mis":"SO6-1-u3-X24"}],"explanation":["육지의 이름만 세요.","남극 대륙도 대륙이에요.","일곱 개예요."],"asset":{"type":"passage","lines":["아시아 · 태평양 · 유럽 · 대서양 · 아프리카 · 인도양","오세아니아 · 북극해 · 북아메리카 · 남극해","남아메리카 · 남극 대륙"],"title":"뒤섞인 이름 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_basic#10','soc',6,1,'u3','L05','g6_1_soc_u3_L05_basic','lesson_basic','SO6-1-u3-C15',3,'error','auto','대륙과 대양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X25','SO6-1-u3-X23']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"error","stem":"대륙과 대양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「모든 대륙을 합치면 태평양보다 넓어.」","correct":true,"mis_target":"SO6-1-u3-X25"},{"t":"친구 가 — 「남극 대륙은 얼음으로 덮여 있어 사람이 살기 어려워.」","mis":"SO6-1-u3-X25"},{"t":"친구 다 — 「대륙은 주로 대양을 기준으로 나눠.」","mis":"SO6-1-u3-X23"}],"explanation":["태평양은 얼마나 넓을까요?","모든 대륙을 합쳐도 작아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#1','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',2,'sa','auto','대양 설명 카드 가운데 둘레의 대륙이 하나뿐인 대양을 찾아 그 이름을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"sa","stem":"대양 설명 카드 가운데 둘레의 대륙이 하나뿐인 대양을 찾아 그 이름을 쓰세요.","answer":["남극해"],"explanation":["둘레를 세어 봐요.","남극 대륙 하나예요.","남극해예요."],"asset":{"type":"passage","lines":["㉠ 남극 대륙을 둘러싸고 있다.","㉡ 아시아·유럽·북아메리카 대륙에 둘러싸인 북극 주변의 바다이다.","㉢ 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있다.","㉣ 세 번째로 넓은 대양으로 아시아·아프리카·오세아니아에 접해 있다."],"title":"대양 설명 카드"},"mis":"SO6-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#2','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C14',2,'ox','auto','지구의 표면에서는 육지가 바다보다 더 넓어요.',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C14","difficulty":2,"kind":"ox","stem":"지구의 표면에서는 육지가 바다보다 더 넓어요.","answer":"X","reason_options":[{"t":"지구의 표면은 바다가 훨씬 더 넓은 자리를 차지하기 때문에","correct":true},{"t":"대양은 대륙보다 언제나 좁기 때문에","mis":"SO6-1-u3-X23"}],"mis":"SO6-1-u3-X23","explanation":["지구본을 떠올려요.","파란 곳이 더 넓어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#3','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',3,'mc','auto','가장 넓은 대륙과 가장 넓은 대양을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X25']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"mc","stem":"가장 넓은 대륙과 가장 넓은 대양을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"아시아 / 태평양","correct":true},{"t":"유럽 / 대서양","mis":"SO6-1-u3-X25"},{"t":"아프리카 / 인도양","mis":"SO6-1-u3-X25"},{"t":"남극 대륙 / 북극해","mis":"SO6-1-u3-X25"}],"explanation":["가장 넓은 육지예요.","가장 넓은 바다예요.","아시아와 태평양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#4','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',3,'mc','auto','아시아가 맞닿아 있는 대양을 모두 고른 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"mc","stem":"아시아가 맞닿아 있는 대양을 모두 고른 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"태평양, 인도양, 북극해","correct":true},{"t":"대서양, 남극해","mis":"SO6-1-u3-X26"},{"t":"태평양 하나","mis":"SO6-1-u3-X26"},{"t":"남극해, 인도양","mis":"SO6-1-u3-X26"}],"explanation":["카드에서 아시아를 찾아요.","㉡·㉢·㉣에 있어요.","세 대양이에요."],"asset":{"type":"passage","lines":["㉠ 남극 대륙을 둘러싸고 있다.","㉡ 아시아·유럽·북아메리카 대륙에 둘러싸인 북극 주변의 바다이다.","㉢ 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있다.","㉣ 세 번째로 넓은 대양으로 아시아·아프리카·오세아니아에 접해 있다."],"title":"대양 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#5','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',3,'mc','auto','태평양의 둘레에 있는 대륙으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"mc","stem":"태평양의 둘레에 있는 대륙으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"유럽","correct":true},{"t":"아시아","mis":"SO6-1-u3-X26"},{"t":"오세아니아","mis":"SO6-1-u3-X26"},{"t":"남아메리카","mis":"SO6-1-u3-X26"}],"explanation":["카드 ㉢을 읽어요.","네 대륙이에요.","유럽은 들어 있지 않아요."],"asset":{"type":"passage","lines":["㉠ 남극 대륙을 둘러싸고 있다.","㉡ 아시아·유럽·북아메리카 대륙에 둘러싸인 북극 주변의 바다이다.","㉢ 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있다.","㉣ 세 번째로 넓은 대양으로 아시아·아프리카·오세아니아에 접해 있다."],"title":"대양 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#6','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',3,'ox','auto','대륙과 대양은 서로 맞닿아 있어, 한 대륙이 여러 대양과 맞닿을 수 있어요.',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"ox","stem":"대륙과 대양은 서로 맞닿아 있어, 한 대륙이 여러 대양과 맞닿을 수 있어요.","answer":"O","reason_options":[{"t":"아시아처럼 셋이 넘는 대양과 맞닿은 대륙도 있기 때문에","correct":true},{"t":"한 대륙은 언제나 한 대양과만 맞닿기 때문에","mis":"SO6-1-u3-X26"}],"mis":"SO6-1-u3-X26","explanation":["아시아를 떠올려요.","여러 대양과 맞닿아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#7','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C14',3,'error','auto','이름 카드를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X24','SO6-1-u3-X23']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C14","difficulty":3,"kind":"error","stem":"이름 카드를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「유럽은 대양이고, 북극해는 대륙이야.」","correct":true,"mis_target":"SO6-1-u3-X24"},{"t":"친구 가 — 「남극 대륙과 남극해는 하나는 육지, 하나는 바다야.」","mis":"SO6-1-u3-X23"},{"t":"친구 나 — 「대양은 다섯 개야.」","mis":"SO6-1-u3-X24"}],"explanation":["유럽은 육지일까요?","북극해는 바다예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["아시아 · 태평양 · 유럽 · 대서양 · 아프리카 · 인도양","오세아니아 · 북극해 · 북아메리카 · 남극해","남아메리카 · 남극 대륙"],"title":"뒤섞인 이름 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#8','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',4,'mc','auto','적도를 그어 대륙을 북반구와 남반구로 나눌 때, 북반구에 주로 속한 대륙을 모두 고른 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C15","difficulty":4,"kind":"mc","stem":"적도를 그어 대륙을 북반구와 남반구로 나눌 때, 북반구에 주로 속한 대륙을 모두 고른 것은 어느 것인가요?","options":[{"t":"아시아, 유럽, 아프리카, 북아메리카","correct":true},{"t":"오세아니아, 남아메리카, 남극 대륙","mis":"SO6-1-u3-X27"},{"t":"아시아, 오세아니아, 남아메리카","mis":"SO6-1-u3-X27"},{"t":"유럽, 남극 대륙","mis":"SO6-1-u3-X27"}],"explanation":["적도의 위쪽이에요.","넷이에요.","아시아·유럽·아프리카·북아메리카예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#9','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C14',4,'mc','auto','「남극 대륙」과 「남극해」가 서로 다른 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X23','SO6-1-u3-X24']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C14","difficulty":4,"kind":"mc","stem":"「남극 대륙」과 「남극해」가 서로 다른 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"남극 대륙은 바다로 둘러싸인 육지이고, 남극해는 그 대륙을 둘러싼 넓은 바다이기 때문에","correct":true},{"t":"둘은 같은 곳을 다르게 부른 이름이기 때문에","mis":"SO6-1-u3-X23"},{"t":"남극해는 얼음으로 덮인 육지이기 때문에","mis":"SO6-1-u3-X23"},{"t":"남극 대륙은 대양의 하나이기 때문에","mis":"SO6-1-u3-X24"}],"explanation":["하나는 육지예요.","하나는 바다예요.","둘레와 가운데예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L05_challenge#10','soc',6,1,'u3','L05','g6_1_soc_u3_L05_challenge','lesson_challenge','SO6-1-u3-C15',4,'essay','teacher','대륙과 대양의 뜻을 각각 쓰고, 가장 넓은 대륙과 가장 넓은 대양의 특징을 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C15","difficulty":4,"kind":"essay","stem":"대륙과 대양의 뜻을 각각 쓰고, 가장 넓은 대륙과 가장 넓은 대양의 특징을 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 대륙은 바다로 둘러싸인 커다란 육지이고, 대양은 세계의 바다 가운데 넓은 바다이다. 가장 넓은 대륙인 아시아는 대부분 북반구에 있고 태평양·인도양·북극해와 맞닿아 있다. 가장 넓은 대양인 태평양은 아시아·오세아니아·북아메리카·남아메리카 사이에 있으며, 모든 대륙을 합쳐도 태평양보다 작다.","scoring_points":["대륙과 대양의 뜻을 썼는가","가장 넓은 대륙의 특징을 썼는가","가장 넓은 대양의 특징을 썼는가"]},"explanation":["육지와 바다예요.","아시아를 떠올려요.","태평양을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#1','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C16',1,'mc','auto','아시아 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X28','SO6-1-u3-X27']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C16","difficulty":1,"kind":"mc","stem":"아시아 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계에서 가장 넓은 대륙으로 대부분 북반구에 있다","correct":true},{"t":"세계에서 가장 작은 대륙으로 대부분 북반구에 있다","mis":"SO6-1-u3-X28"},{"t":"세계에서 가장 넓은 대륙으로 대부분 남반구에 있다","mis":"SO6-1-u3-X27"},{"t":"세계에서 가장 작은 대륙으로 대부분 남반구에 있다","mis":"SO6-1-u3-X28"}],"explanation":["가장 넓어요.","적도의 위쪽이에요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#2','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C18',1,'sa','auto','오세아니아에서 가장 큰 나라로, 땅이 매우 넓어 나라 자체가 하나의 대륙인 나라는 어디인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C18","difficulty":1,"kind":"sa","stem":"오세아니아에서 가장 큰 나라로, 땅이 매우 넓어 나라 자체가 하나의 대륙인 나라는 어디인가요?","answer":["오스트레일리아","호주"],"explanation":["태평양과 인도양 사이예요.","대륙과 이름이 같아요.","오스트레일리아예요."],"mis":"SO6-1-u3-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#3','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C17',1,'ox','auto','우리나라의 영토는 동서로 넓게 펼쳐진 모양이에요.',ARRAY['SO6-1-u3-X30']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C17","difficulty":1,"kind":"ox","stem":"우리나라의 영토는 동서로 넓게 펼쳐진 모양이에요.","answer":"X","reason_options":[{"t":"우리나라의 영토는 남북으로 긴 모양이기 때문에","correct":true},{"t":"우리나라는 아시아의 서쪽 끝에 있기 때문에","mis":"SO6-1-u3-X30"}],"mis":"SO6-1-u3-X30","explanation":["지구본에서 본떠 봐요.","위아래로 길어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#4','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C18',1,'mc','auto','오세아니아에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X28','SO6-1-u3-X27']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C18","difficulty":1,"kind":"mc","stem":"오세아니아에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계에서 가장 작은 대륙으로 대부분 남반구에 있다","correct":true},{"t":"세계에서 가장 넓은 대륙이다","mis":"SO6-1-u3-X28"},{"t":"대부분 북반구에 있다","mis":"SO6-1-u3-X27"},{"t":"섬은 하나도 없다","mis":"SO6-1-u3-X28"}],"explanation":["가장 작아요.","적도의 아래쪽이에요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#5','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C16',2,'match','auto','아시아의 세 나라 설명과 나라 이름, 그리고 우리나라 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u3-C16","difficulty":2,"kind":"match","stem":"아시아의 세 나라 설명과 나라 이름, 그리고 우리나라 설명을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"일본"},{"l":"㉯","r":"중국"},{"l":"㉰","r":"사우디아라비아"},{"l":"삼면이 바다로 둘러싸인 남북으로 긴 나라","r":"대한민국"}],"mis":"SO6-1-u3-X29","explanation":["섬나라 · 동서로 넓게예요.","아라비아반도예요.","삼면이 바다예요."],"asset":{"type":"passage","lines":["㉮ 우리나라의 동쪽에 있으며 태평양에 접한 섬나라이다.","㉯ 우리나라의 서쪽에 있으며 영토가 동서로 넓게 펼쳐져 있다.","㉰ 아시아의 서쪽, 아라비아반도의 대부분을 차지하며 국경선이 단조롭다."],"title":"아시아의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#6','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C17',2,'mc','auto','지구본으로 찾은 나라는 어디인가요?',ARRAY['SO6-1-u3-X30']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C17","difficulty":2,"kind":"mc","stem":"지구본으로 찾은 나라는 어디인가요?","options":[{"t":"대한민국","correct":true},{"t":"일본","mis":"SO6-1-u3-X30"},{"t":"중국","mis":"SO6-1-u3-X30"},{"t":"뉴질랜드","mis":"SO6-1-u3-X30"}],"explanation":["동쪽에 섬나라가 있어요.","삼면이 바다예요.","대한민국이에요."],"asset":{"type":"passage","lines":["지구본에서 북위 33°~43°, 동경 124°~132° 사이에 있는 나라를 찾았다.","동쪽에는 섬나라가, 서쪽과 북쪽에는 큰 나라들이 있다.","동쪽·서쪽·남쪽의 세 면이 바다로 둘러싸여 있다."],"title":"지구본으로 찾은 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#7','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C18',2,'blank','auto','오세아니아는 오스트레일리아 대륙과 (    )의 수많은 섬으로 이루어져 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C18","difficulty":2,"kind":"blank","stem":"오세아니아는 오스트레일리아 대륙과 (    )의 수많은 섬으로 이루어져 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"태평양","correct":true},{"t":"북극해","mis":"SO6-1-u3-X26"},{"t":"대서양","mis":"SO6-1-u3-X26"},{"t":"남극해","mis":"SO6-1-u3-X26"}],"explanation":["오세아니아의 동쪽 바다예요.","가장 넓은 대양이에요.","태평양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#8','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C18',2,'mc','auto','신문 기사를 보고 니우에에서 발달할 수 있는 산업으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X31']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C18","difficulty":2,"kind":"mc","stem":"신문 기사를 보고 니우에에서 발달할 수 있는 산업으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바다에서 수영과 다이빙을 즐기려는 사람들이 찾는 관광 산업","correct":true},{"t":"넓은 들에서 곡식을 기르는 산업","mis":"SO6-1-u3-X31"},{"t":"높은 산에서 나무를 기르는 산업","mis":"SO6-1-u3-X31"},{"t":"얼음을 캐어 내는 산업","mis":"SO6-1-u3-X31"}],"explanation":["바다로 둘러싸였어요.","다이빙을 즐겨요.","관광 산업이에요."],"asset":{"type":"passage","lines":["우리나라와 태평양의 섬나라 니우에가 정식으로 외교 관계를 맺었다.","니우에는 오세아니아에 속하는, 바다로 둘러싸인 섬나라이다.","이곳에서는 수영과 다이빙을 즐길 수 있고 혹등고래도 볼 수 있다.","그래서 니우에를 찾는 사람들이 늘고 있다."],"title":"신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#9','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C19',2,'mc','auto','외교관이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X32']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C19","difficulty":2,"kind":"mc","stem":"외교관이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라를 대표해 세계 여러 나라와 협력하고 외교 문제를 해결한다","correct":true},{"t":"도로와 교통 정보를 만들어 활용한다","mis":"SO6-1-u3-X32"},{"t":"다른 나라와 만나지 않고 우리나라 일만 한다","mis":"SO6-1-u3-X32"},{"t":"물건을 만들어 다른 나라에 판다","mis":"SO6-1-u3-X32"}],"explanation":["나라를 대표해요.","여러 나라와 협력해요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_basic#10','soc',6,1,'u3','L06','g6_1_soc_u3_L06_basic','lesson_basic','SO6-1-u3-C16',3,'error','auto','아시아의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X29']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C16","difficulty":3,"kind":"error","stem":"아시아의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「일본은 영토가 동서로 넓게 펼쳐진 나라야.」","correct":true,"mis_target":"SO6-1-u3-X29"},{"t":"친구 나 — 「중국은 동쪽에서 서쪽으로 갈수록 지형이 높아져.」","mis":"SO6-1-u3-X29"},{"t":"친구 다 — 「일본은 네 개의 큰 섬과 수천 개의 작은 섬으로 이루어져 있어.」","mis":"SO6-1-u3-X29"}],"explanation":["동서로 넓은 나라는 어디일까요?","중국이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#1','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C17',2,'sa','auto','우리나라와 영토의 면적이 비슷한 유럽의 섬나라는 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C17","difficulty":2,"kind":"sa","stem":"우리나라와 영토의 면적이 비슷한 유럽의 섬나라는 어디인가요? 두 글자로 쓰세요.","answer":["영국"],"explanation":["유럽의 서쪽이에요.","본초 자오선이 지나요.","영국이에요."],"mis":"SO6-1-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#2','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C18',2,'ox','auto','뉴질랜드는 북동쪽에서 남서쪽으로 길게 뻗은 모양으로, 두 개의 큰 섬과 여러 개의 작은 섬으로 이루어져 있어요.',ARRAY['SO6-1-u3-X28']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C18","difficulty":2,"kind":"ox","stem":"뉴질랜드는 북동쪽에서 남서쪽으로 길게 뻗은 모양으로, 두 개의 큰 섬과 여러 개의 작은 섬으로 이루어져 있어요.","answer":"O","reason_options":[{"t":"뉴질랜드의 영토는 길게 뻗은 섬들로 이루어져 있기 때문에","correct":true},{"t":"뉴질랜드는 땅이 넓어 나라 자체가 하나의 대륙이기 때문에","mis":"SO6-1-u3-X28"}],"mis":"SO6-1-u3-X28","explanation":["오세아니아의 섬나라예요.","큰 섬이 둘이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#3','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C17',3,'mc','auto','우리나라의 주변 나라를 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X30']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C17","difficulty":3,"kind":"mc","stem":"우리나라의 주변 나라를 바르게 말한 것은 어느 것인가요?","options":[{"t":"동쪽에는 일본, 서쪽에는 중국이 있고 북쪽으로 중국·러시아와 국경을 맞댄다","correct":true},{"t":"동쪽에는 중국, 서쪽에는 일본이 있다","mis":"SO6-1-u3-X30"},{"t":"북쪽으로 일본과 국경을 맞댄다","mis":"SO6-1-u3-X30"},{"t":"주변에 국경을 맞댄 나라가 없다","mis":"SO6-1-u3-X30"}],"explanation":["섬나라는 동쪽이에요.","큰 나라는 서쪽이에요.","북쪽에는 두 나라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#4','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C16',3,'mc','auto','㉰ 나라가 차지한 아라비아반도가 잇는 두 대륙은 어느 것인가요?',ARRAY['SO6-1-u3-X29']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C16","difficulty":3,"kind":"mc","stem":"㉰ 나라가 차지한 아라비아반도가 잇는 두 대륙은 어느 것인가요?","options":[{"t":"아시아와 아프리카","correct":true},{"t":"아시아와 오세아니아","mis":"SO6-1-u3-X29"},{"t":"유럽과 북아메리카","mis":"SO6-1-u3-X29"},{"t":"오세아니아와 남극 대륙","mis":"SO6-1-u3-X29"}],"explanation":["아시아의 서쪽이에요.","서쪽 너머의 대륙이에요.","아시아와 아프리카예요."],"asset":{"type":"passage","lines":["㉮ 우리나라의 동쪽에 있으며 태평양에 접한 섬나라이다.","㉯ 우리나라의 서쪽에 있으며 영토가 동서로 넓게 펼쳐져 있다.","㉰ 아시아의 서쪽, 아라비아반도의 대부분을 차지하며 국경선이 단조롭다."],"title":"아시아의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#5','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C18',3,'mc','auto','오세아니아의 동쪽과 서쪽에 있는 바다를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C18","difficulty":3,"kind":"mc","stem":"오세아니아의 동쪽과 서쪽에 있는 바다를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"동쪽 — 태평양, 서쪽 — 인도양","correct":true},{"t":"동쪽 — 인도양, 서쪽 — 태평양","mis":"SO6-1-u3-X26"},{"t":"동쪽 — 대서양, 서쪽 — 북극해","mis":"SO6-1-u3-X26"},{"t":"동쪽과 서쪽 모두 남극해","mis":"SO6-1-u3-X26"}],"explanation":["가장 넓은 대양은 어느 쪽일까요?","서쪽은 세 번째로 넓은 대양이에요.","태평양과 인도양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#6','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C18',3,'ox','auto','니우에처럼 바다로 둘러싸인 나라는 영토의 특징 때문에 바다를 즐기는 관광 산업이 발달할 수 있어요.',ARRAY['SO6-1-u3-X31']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C18","difficulty":3,"kind":"ox","stem":"니우에처럼 바다로 둘러싸인 나라는 영토의 특징 때문에 바다를 즐기는 관광 산업이 발달할 수 있어요.","answer":"O","reason_options":[{"t":"영토의 특징이 그 나라의 산업에 영향을 주기 때문에","correct":true},{"t":"섬나라는 어떤 산업도 할 수 없기 때문에","mis":"SO6-1-u3-X31"}],"mis":"SO6-1-u3-X31","explanation":["기사를 떠올려요.","바다가 둘레에 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["우리나라와 태평양의 섬나라 니우에가 정식으로 외교 관계를 맺었다.","니우에는 오세아니아에 속하는, 바다로 둘러싸인 섬나라이다.","이곳에서는 수영과 다이빙을 즐길 수 있고 혹등고래도 볼 수 있다.","그래서 니우에를 찾는 사람들이 늘고 있다."],"title":"신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#7','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C19',3,'error','auto','외교관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X32']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C19","difficulty":3,"kind":"error","stem":"외교관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「외교관은 외국어나 다른 나라 문화는 몰라도 돼.」","correct":true,"mis_target":"SO6-1-u3-X32"},{"t":"친구 가 — 「대부분 외국에 파견되어 일해.」","mis":"SO6-1-u3-X32"},{"t":"친구 다 — 「다른 사람과 원활하게 소통하는 능력이 도움이 돼.」","mis":"SO6-1-u3-X32"}],"explanation":["여러 나라 사람과 일해요.","말과 문화를 알아야 해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#8','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C17',4,'mc','auto','지구본에 투명 종이를 올려 우리나라를 본뜬 뒤 다른 나라 위에 겹쳐 보는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X30','SO6-1-u3-X03']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C17","difficulty":4,"kind":"mc","stem":"지구본에 투명 종이를 올려 우리나라를 본뜬 뒤 다른 나라 위에 겹쳐 보는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"본뜬 한 장으로 여러 나라의 면적과 모양을 견주어 보려고","correct":true},{"t":"나라마다 종이를 새로 본떠야 하기 때문에","mis":"SO6-1-u3-X30"},{"t":"겹쳐 보면 그 나라의 위치가 바뀌기 때문에","mis":"SO6-1-u3-X30"},{"t":"세계지도는 면적이 늘 정확하기 때문에","mis":"SO6-1-u3-X03"}],"explanation":["본뜬 종이는 한 장이에요.","여러 나라 위에 겹쳐요.","면적과 모양을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#9','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C16',4,'mc','auto','아시아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X26','SO6-1-u3-X29']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C16","difficulty":4,"kind":"mc","stem":"아시아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"아시아의 나라들은 모두 바다에 접해 있다","correct":true},{"t":"동쪽에 태평양이 있다","mis":"SO6-1-u3-X26"},{"t":"서쪽에 유럽 대륙과 아프리카 대륙이 있다","mis":"SO6-1-u3-X26"},{"t":"바다로 둘러싸인 섬나라도 있다","mis":"SO6-1-u3-X29"}],"explanation":["바다에 접하지 않은 나라도 있어요.","「알맞지 않은」 것을 골라요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L06_challenge#10','soc',6,1,'u3','L06','g6_1_soc_u3_L06_challenge','lesson_challenge','SO6-1-u3-C17',4,'essay','teacher','지구본으로 찾은 나라의 위치와 영토 특징을 쓰고, 그 나라와 일본·중국의 영토 특징을 하나씩 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C17","difficulty":4,"kind":"essay","stem":"지구본으로 찾은 나라의 위치와 영토 특징을 쓰고, 그 나라와 일본·중국의 영토 특징을 하나씩 견주어 쓰세요.","answer_guide":{"answer":"예: 이 나라는 대한민국으로, 북반구 아시아 대륙의 동쪽에 있다. 영토는 남북으로 긴 모양이고 한반도와 여러 섬으로 이루어져 있으며 삼면이 바다로 둘러싸여 있다. 동쪽의 일본은 네 개의 큰 섬과 수천 개의 작은 섬으로 이루어진 섬나라이고, 서쪽의 중국은 영토가 동서로 넓게 펼쳐져 있다.","scoring_points":["우리나라의 위치를 썼는가","우리나라의 영토 특징을 썼는가","일본·중국의 영토 특징과 견주었는가"]},"explanation":["어느 대륙의 어느 쪽인가요?","남북으로 길어요.","섬나라와 동서로 넓은 나라예요."],"asset":{"type":"passage","lines":["지구본에서 북위 33°~43°, 동경 124°~132° 사이에 있는 나라를 찾았다.","동쪽에는 섬나라가, 서쪽과 북쪽에는 큰 나라들이 있다.","동쪽·서쪽·남쪽의 세 면이 바다로 둘러싸여 있다."],"title":"지구본으로 찾은 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#1','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C20',1,'mc','auto','유럽 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X33','SO6-1-u3-X35']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C20","difficulty":1,"kind":"mc","stem":"유럽 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"우랄산맥을 경계로 아시아의 서쪽에 있으며 북쪽으로 북극해, 서쪽으로 대서양과 접한다","correct":true},{"t":"우랄산맥을 경계로 아시아의 동쪽에 있으며 남쪽으로 인도양과 접한다","mis":"SO6-1-u3-X33"},{"t":"넓은 대륙이지만 나라의 수가 가장 적다","mis":"SO6-1-u3-X33"},{"t":"북반구와 남반구에 걸쳐 있다","mis":"SO6-1-u3-X35"}],"explanation":["우랄산맥의 서쪽이에요.","북극해와 대서양이에요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#2','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C21',1,'sa','auto','아프리카 동부에 있으며 여러 나라에 둘러싸여 접한 바다가 없는 나라는 어디인가요?','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C21","difficulty":1,"kind":"sa","stem":"아프리카 동부에 있으며 여러 나라에 둘러싸여 접한 바다가 없는 나라는 어디인가요?","answer":["에티오피아"],"explanation":["㉡이에요.","에◯◯◯◯예요.","에티오피아예요."],"asset":{"type":"passage","lines":["㉠ 아프리카의 남쪽 끝에 있으며 동쪽으로 인도양, 서쪽으로 대서양과 접한다.","㉡ 아프리카 동부에 있으며 여러 나라에 둘러싸여 접한 바다가 없다.","㉢ 아프리카의 북동쪽 끝에 있으며 국경선 일부가 직선이라 사각형과 비슷하다."],"title":"아프리카의 세 나라"},"mis":"SO6-1-u3-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#3','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C21',1,'ox','auto','아프리카는 북반구에만 있는 대륙이에요.',ARRAY['SO6-1-u3-X35']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C21","difficulty":1,"kind":"ox","stem":"아프리카는 북반구에만 있는 대륙이에요.","answer":"X","reason_options":[{"t":"아프리카는 적도를 기준으로 북반구와 남반구에 걸쳐 있기 때문에","correct":true},{"t":"아프리카는 유럽의 북쪽에 있기 때문에","mis":"SO6-1-u3-X35"}],"mis":"SO6-1-u3-X35","explanation":["적도가 지나요.","위아래에 걸쳐 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#4','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C20',1,'mc','auto','유럽의 서쪽에 있는 섬나라로, 본초 자오선이 지나는 나라는 어디인가요?',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C20","difficulty":1,"kind":"mc","stem":"유럽의 서쪽에 있는 섬나라로, 본초 자오선이 지나는 나라는 어디인가요?","options":[{"t":"영국","correct":true},{"t":"독일","mis":"SO6-1-u3-X34"},{"t":"노르웨이","mis":"SO6-1-u3-X34"},{"t":"스위스","mis":"SO6-1-u3-X34"}],"explanation":["섬나라예요.","본초 자오선이 지나요.","영국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#5','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C20',2,'match','auto','유럽의 네 나라와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u3-C20","difficulty":2,"kind":"match","stem":"유럽의 네 나라와 알맞은 설명을 이으세요.","pairs":[{"l":"아이슬란드","r":"바다로 둘러싸인 나라"},{"l":"스위스","r":"바다에 접하지 않은 나라"},{"l":"프랑스","r":"본초 자오선이 지나는 나라"},{"l":"핀란드","r":"러시아와 국경을 마주한 나라"}],"mis":"SO6-1-u3-X34","explanation":["섬나라를 찾아요.","바다가 없는 나라를 찾아요.","본초 자오선과 이웃 나라예요."],"asset":{"type":"passage","lines":["아이슬란드 · 스위스 · 프랑스 · 핀란드"],"title":"지도에서 찾은 유럽의 네 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#6','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C21',2,'mc','auto','아프리카의 세 나라 설명 가운데 ㉢에 해당하는 나라는 어디인가요?',ARRAY['SO6-1-u3-X36']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C21","difficulty":2,"kind":"mc","stem":"아프리카의 세 나라 설명 가운데 ㉢에 해당하는 나라는 어디인가요?","options":[{"t":"이집트","correct":true},{"t":"남아프리카 공화국","mis":"SO6-1-u3-X36"},{"t":"에티오피아","mis":"SO6-1-u3-X36"},{"t":"나이지리아","mis":"SO6-1-u3-X36"}],"explanation":["북동쪽 끝이에요.","사각형과 비슷해요.","이집트예요."],"asset":{"type":"passage","lines":["㉠ 아프리카의 남쪽 끝에 있으며 동쪽으로 인도양, 서쪽으로 대서양과 접한다.","㉡ 아프리카 동부에 있으며 여러 나라에 둘러싸여 접한 바다가 없다.","㉢ 아프리카의 북동쪽 끝에 있으며 국경선 일부가 직선이라 사각형과 비슷하다."],"title":"아프리카의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#7','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C20',2,'blank','auto','노르웨이의 스발바르 제도에는 우리나라의 (    ) 과학 기지가 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C20","difficulty":2,"kind":"blank","stem":"노르웨이의 스발바르 제도에는 우리나라의 (    ) 과학 기지가 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"다산","correct":true},{"t":"세종","mis":"SO6-1-u3-X34"},{"t":"장보고","mis":"SO6-1-u3-X34"},{"t":"한빛","mis":"SO6-1-u3-X34"}],"explanation":["북쪽 섬들이에요.","다◯이에요.","다산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#8','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C21',2,'mc','auto','아프리카 여덟 나라를 적도를 기준으로 나눌 때 남반구에 있는 나라끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X35']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C21","difficulty":2,"kind":"mc","stem":"아프리카 여덟 나라를 적도를 기준으로 나눌 때 남반구에 있는 나라끼리 짝지은 것은 어느 것인가요?","options":[{"t":"나미비아, 앙골라, 마다가스카르","correct":true},{"t":"알제리, 리비아, 이집트","mis":"SO6-1-u3-X35"},{"t":"수단, 나이지리아, 알제리","mis":"SO6-1-u3-X35"},{"t":"이집트, 나미비아, 수단","mis":"SO6-1-u3-X35"}],"explanation":["적도를 선으로 그어요.","아래쪽 나라예요.","나미비아·앙골라·마다가스카르예요."],"asset":{"type":"passage","lines":["알제리 · 수단 · 나미비아 · 리비아","앙골라 · 이집트 · 나이지리아 · 마다가스카르"],"title":"아프리카에 속한 여덟 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#9','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C22',2,'mc','auto','이탈리아의 영토에 둘러싸인 나라끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X38']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C22","difficulty":2,"kind":"mc","stem":"이탈리아의 영토에 둘러싸인 나라끼리 짝지은 것은 어느 것인가요?","options":[{"t":"산마리노, 바티칸 시국","correct":true},{"t":"레소토, 산마리노","mis":"SO6-1-u3-X38"},{"t":"바티칸 시국, 레소토","mis":"SO6-1-u3-X38"},{"t":"이집트, 산마리노","mis":"SO6-1-u3-X38"}],"explanation":["유럽 남부예요.","두 나라예요.","산마리노와 바티칸 시국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_basic#10','soc',6,1,'u3','L07','g6_1_soc_u3_L07_basic','lesson_basic','SO6-1-u3-C21',3,'error','auto','아프리카를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X35']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C21","difficulty":3,"kind":"error","stem":"아프리카를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「아프리카는 세계에서 가장 작은 대륙이야.」","correct":true,"mis_target":"SO6-1-u3-X35"},{"t":"친구 가 — 「아프리카에는 가장 많은 나라가 있어.」","mis":"SO6-1-u3-X35"},{"t":"친구 다 — 「아프리카는 유럽의 남쪽에 있어.」","mis":"SO6-1-u3-X35"}],"explanation":["아시아 다음으로 넓어요.","가장 작지 않아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#1','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C22',2,'sa','auto','하나의 도시로 이루어진 국가를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C22","difficulty":2,"kind":"sa","stem":"하나의 도시로 이루어진 국가를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["도시 국가","도시국가"],"explanation":["바티칸 시국이 그래요.","도시 ◯◯예요.","도시 국가예요."],"mis":"SO6-1-u3-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#2','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C21',2,'ox','auto','남아프리카 공화국은 아프리카의 남쪽 끝에 있어 두 대양과 접해 있어요.',ARRAY['SO6-1-u3-X36']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C21","difficulty":2,"kind":"ox","stem":"남아프리카 공화국은 아프리카의 남쪽 끝에 있어 두 대양과 접해 있어요.","answer":"O","reason_options":[{"t":"동쪽으로 인도양, 서쪽으로 대서양과 접하기 때문에","correct":true},{"t":"남아프리카 공화국은 바다에 접하지 않은 나라이기 때문에","mis":"SO6-1-u3-X36"}],"mis":"SO6-1-u3-X36","explanation":["남쪽 끝이에요.","양쪽이 바다예요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 아프리카의 남쪽 끝에 있으며 동쪽으로 인도양, 서쪽으로 대서양과 접한다.","㉡ 아프리카 동부에 있으며 여러 나라에 둘러싸여 접한 바다가 없다.","㉢ 아프리카의 북동쪽 끝에 있으며 국경선 일부가 직선이라 사각형과 비슷하다."],"title":"아프리카의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#3','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C20',3,'mc','auto','유럽의 세 나라 ㉮~㉰를 차례대로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C20","difficulty":3,"kind":"mc","stem":"유럽의 세 나라 ㉮~㉰를 차례대로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"노르웨이 — 영국 — 독일","correct":true},{"t":"영국 — 노르웨이 — 독일","mis":"SO6-1-u3-X34"},{"t":"독일 — 영국 — 노르웨이","mis":"SO6-1-u3-X34"},{"t":"노르웨이 — 독일 — 영국","mis":"SO6-1-u3-X34"}],"explanation":["길게 뻗은 나라예요.","섬나라예요.","아홉 나라와 국경이에요."],"asset":{"type":"passage","lines":["㉮ 북동쪽에서 남서쪽으로 길게 뻗어 있고 해안선이 복잡하다.","㉯ 유럽의 서쪽에 있는 섬나라로, 본초 자오선이 지난다.","㉰ 아홉 나라와 국경을 맞대고 있고 북쪽은 바다와도 맞닿아 있다."],"title":"유럽의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#4','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C21',3,'mc','auto','아프리카 여러 나라의 국경선 일부가 직선으로 반듯한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X37']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C21","difficulty":3,"kind":"mc","stem":"아프리카 여러 나라의 국경선 일부가 직선으로 반듯한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"과거 유럽 여러 나라가 식민지로 삼으며 원래 국경을 무시하고 위도나 경도에 따라 직선을 그었기 때문에","correct":true},{"t":"아프리카의 땅이 모두 평평해서 저절로 반듯해졌기 때문에","mis":"SO6-1-u3-X37"},{"t":"나라마다 반듯한 모양을 좋아했기 때문에","mis":"SO6-1-u3-X37"},{"t":"적도가 국경선을 따라 지나기 때문에","mis":"SO6-1-u3-X37"}],"explanation":["국경을 누가 그었을까요?","원래 국경을 무시했어요.","위도·경도를 따라 그었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#5','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C22',3,'mc','auto','나라 안의 나라 ㉮~㉰를 차례대로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X38']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C22","difficulty":3,"kind":"mc","stem":"나라 안의 나라 ㉮~㉰를 차례대로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"산마리노 — 바티칸 시국 — 레소토","correct":true},{"t":"바티칸 시국 — 산마리노 — 레소토","mis":"SO6-1-u3-X38"},{"t":"레소토 — 바티칸 시국 — 산마리노","mis":"SO6-1-u3-X38"},{"t":"산마리노 — 레소토 — 바티칸 시국","mis":"SO6-1-u3-X38"}],"explanation":["유럽 남부예요.","가장 작은 나라예요.","아프리카 남부예요."],"asset":{"type":"passage","lines":["㉮ 유럽 남부에 있으며 다른 나라의 영토에 둘러싸여 있다.","㉯ 다른 나라의 수도에 둘러싸인, 세계에서 가장 작은 나라이다.","㉰ 아프리카 남부에 있으며 영토의 모양이 직사각형과 비슷하다."],"title":"나라 안의 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#6','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C20',3,'ox','auto','러시아의 영토는 우랄산맥을 기준으로 서쪽은 유럽, 동쪽은 아시아예요.',ARRAY['SO6-1-u3-X33']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C20","difficulty":3,"kind":"ox","stem":"러시아의 영토는 우랄산맥을 기준으로 서쪽은 유럽, 동쪽은 아시아예요.","answer":"O","reason_options":[{"t":"유럽과 아시아는 우랄산맥을 경계로 나누기 때문에","correct":true},{"t":"러시아는 오세아니아에 속하는 나라이기 때문에","mis":"SO6-1-u3-X33"}],"mis":"SO6-1-u3-X33","explanation":["경계는 우랄산맥이에요.","서쪽이 유럽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#7','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C20',3,'error','auto','독일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C20","difficulty":3,"kind":"error","stem":"독일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「독일은 접해 있는 바다가 전혀 없어.」","correct":true,"mis_target":"SO6-1-u3-X34"},{"t":"친구 가 — 「독일은 아홉 나라와 국경을 맞대고 있어.」","mis":"SO6-1-u3-X34"},{"t":"친구 나 — 「북쪽에서 남쪽으로 갈수록 지형이 높아져.」","mis":"SO6-1-u3-X34"}],"explanation":["북쪽을 살펴봐요.","바다와도 맞닿아 있어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#8','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C21',4,'mc','auto','아프리카 여덟 나라를 북반구와 남반구로 바르게 나누는 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X35','SO6-1-u3-X11']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"mc","stem":"아프리카 여덟 나라를 북반구와 남반구로 바르게 나누는 방법은 어느 것인가요?","options":[{"t":"적도를 선으로 그어 그것을 기준으로 북쪽과 남쪽으로 나눈다","correct":true},{"t":"나라의 넓이를 재어 큰 나라와 작은 나라로 나눈다","mis":"SO6-1-u3-X35"},{"t":"나라 이름의 글자 수로 나눈다","mis":"SO6-1-u3-X35"},{"t":"본초 자오선을 기준으로 동쪽과 서쪽으로 나눈다","mis":"SO6-1-u3-X11"}],"explanation":["반구를 나누는 선은 무엇일까요?","적도예요.","북쪽과 남쪽으로 나눠요."],"asset":{"type":"passage","lines":["알제리 · 수단 · 나미비아 · 리비아","앙골라 · 이집트 · 나이지리아 · 마다가스카르"],"title":"아프리카에 속한 여덟 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#9','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C22',4,'mc','auto','레소토와 남아프리카 공화국의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X38']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C22","difficulty":4,"kind":"mc","stem":"레소토와 남아프리카 공화국의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"레소토는 남아프리카 공화국의 영토에 둘러싸여 있다","correct":true},{"t":"남아프리카 공화국이 레소토의 영토에 둘러싸여 있다","mis":"SO6-1-u3-X38"},{"t":"레소토는 이탈리아의 영토에 둘러싸여 있다","mis":"SO6-1-u3-X38"},{"t":"두 나라는 서로 다른 대륙에 있다","mis":"SO6-1-u3-X38"}],"explanation":["아프리카 남부예요.","작은 나라가 안에 있어요.","레소토가 둘러싸여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L07_challenge#10','soc',6,1,'u3','L07','g6_1_soc_u3_L07_challenge','lesson_challenge','SO6-1-u3-C21',4,'essay','teacher','유럽과 아프리카의 위치를 하나씩 쓰고, 아프리카에서 이집트와 에티오피아의 영토 특징을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"essay","stem":"유럽과 아프리카의 위치를 하나씩 쓰고, 아프리카에서 이집트와 에티오피아의 영토 특징을 견주어 쓰세요.","answer_guide":{"answer":"예: 유럽은 우랄산맥을 경계로 아시아의 서쪽에 있으며 북쪽으로 북극해, 서쪽으로 대서양과 접한다. 아프리카는 유럽의 남쪽에 있으며 북반구와 남반구에 걸쳐 있다. 이집트는 아프리카의 북동쪽 끝에 있고 국경선 일부가 직선이라 영토가 사각형과 비슷하며, 에티오피아는 아프리카 동부에 있고 여러 나라에 둘러싸여 접한 바다가 없다.","scoring_points":["유럽의 위치를 썼는가","아프리카의 위치를 썼는가","두 나라의 영토 특징을 견주었는가"]},"explanation":["우랄산맥을 떠올려요.","적도를 떠올려요.","사각형과 바다 없음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#1','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C25',1,'mc','auto','두 개의 육지를 연결하는 좁고 잘록한 땅을 무엇이라고 하나요?',ARRAY['SO6-1-u3-X41']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C25","difficulty":1,"kind":"mc","stem":"두 개의 육지를 연결하는 좁고 잘록한 땅을 무엇이라고 하나요?","options":[{"t":"지협","correct":true},{"t":"본토","mis":"SO6-1-u3-X41"},{"t":"제도","mis":"SO6-1-u3-X41"},{"t":"반도","mis":"SO6-1-u3-X41"}],"explanation":["좁고 잘록해요.","두 육지를 이어요.","지협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#2','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C23',1,'sa','auto','국가의 주가 되는 국토를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C23","difficulty":1,"kind":"sa","stem":"국가의 주가 되는 국토를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["본토"],"explanation":["주가 되는 땅이에요.","◯토예요.","본토예요."],"mis":"SO6-1-u3-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#3','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C24',1,'ox','auto','남아메리카는 대부분 남반구에 속해 있어요.',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C24","difficulty":1,"kind":"ox","stem":"남아메리카는 대부분 남반구에 속해 있어요.","answer":"O","reason_options":[{"t":"남아메리카의 대부분이 적도의 아래쪽에 있기 때문에","correct":true},{"t":"남아메리카는 북아메리카의 북쪽에 있기 때문에","mis":"SO6-1-u3-X27"}],"mis":"SO6-1-u3-X27","explanation":["적도를 떠올려요.","아래쪽이 넓어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#4','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C24',1,'mc','auto','세계에서 가장 긴 산맥으로, 남아메리카에 있는 산맥은 무엇인가요?',ARRAY['SO6-1-u3-X40','SO6-1-u3-X41']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C24","difficulty":1,"kind":"mc","stem":"세계에서 가장 긴 산맥으로, 남아메리카에 있는 산맥은 무엇인가요?","options":[{"t":"안데스산맥","correct":true},{"t":"우랄산맥","mis":"SO6-1-u3-X40"},{"t":"파나마 지협","mis":"SO6-1-u3-X41"},{"t":"그린란드","mis":"SO6-1-u3-X41"}],"explanation":["남아메리카의 서쪽을 따라 있어요.","아주 길어요.","안데스산맥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#5','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C23',2,'match','auto','북아메리카의 세 나라 설명과 나라 이름, 그리고 북아메리카의 섬을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u3-C23","difficulty":2,"kind":"match","stem":"북아메리카의 세 나라 설명과 나라 이름, 그리고 북아메리카의 섬을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"미국"},{"l":"㉯","r":"캐나다"},{"l":"㉰","r":"멕시코"},{"l":"세계에서 가장 큰 섬","r":"그린란드"}],"mis":"SO6-1-u3-X39","explanation":["영토가 나뉜 나라예요.","세 대양에 접한 나라예요.","남부의 나라와 가장 큰 섬이에요."],"asset":{"type":"passage","lines":["㉮ 캐나다를 사이에 두고 본토와 알래스카 지역으로 나뉜다.","㉯ 태평양·대서양·북극해에 접하고 남쪽으로 이웃 나라의 본토와 국경을 맞댄다.","㉰ 북아메리카 남부에 있으며 북서쪽에서 남동쪽으로 길게 뻗어 있다."],"title":"북아메리카의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#6','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C23',2,'mc','auto','북아메리카 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X39','SO6-1-u3-X27']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C23","difficulty":2,"kind":"mc","stem":"북아메리카 대륙에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 번째로 큰 대륙으로 동쪽으로 대서양, 서쪽으로 태평양과 접한다","correct":true},{"t":"바다와 접한 나라가 하나도 없다","mis":"SO6-1-u3-X39"},{"t":"대부분 남반구에 속해 있다","mis":"SO6-1-u3-X27"},{"t":"가장 작은 대륙이다","mis":"SO6-1-u3-X39"}],"explanation":["세 번째로 커요.","양쪽이 바다예요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#7','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C24',2,'blank','auto','남아메리카에서 바다에 접하지 않은 두 나라는 볼리비아와 (    )예요. 빈칸에 알맞은 나라 이름은 무엇인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C24","difficulty":2,"kind":"blank","stem":"남아메리카에서 바다에 접하지 않은 두 나라는 볼리비아와 (    )예요. 빈칸에 알맞은 나라 이름은 무엇인가요?","options":[{"t":"파라과이","correct":true},{"t":"칠레","mis":"SO6-1-u3-X40"},{"t":"브라질","mis":"SO6-1-u3-X40"},{"t":"아르헨티나","mis":"SO6-1-u3-X40"}],"explanation":["바다에 닿지 않아요.","볼리비아의 이웃이에요.","파라과이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#8','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C25',2,'mc','auto','어느 나라 이야기에 나오는 나라는 어디인가요?',ARRAY['SO6-1-u3-X41','SO6-1-u3-X40','SO6-1-u3-X39']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C25","difficulty":2,"kind":"mc","stem":"어느 나라 이야기에 나오는 나라는 어디인가요?","options":[{"t":"파나마","correct":true},{"t":"멕시코","mis":"SO6-1-u3-X41"},{"t":"칠레","mis":"SO6-1-u3-X40"},{"t":"캐나다","mis":"SO6-1-u3-X39"}],"explanation":["가장 남쪽에 있어요.","두 대륙을 이어요.","파나마예요."],"asset":{"type":"passage","lines":["북아메리카의 가장 남쪽에 있는 나라이다.","영토의 동서 길이가 남북 길이보다 길다.","영토 전체가 두 대륙을 잇는 좁고 잘록한 땅이다."],"title":"어느 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_basic#9','soc',6,1,'u3','L08','g6_1_soc_u3_L08_basic','lesson_basic','SO6-1-u3-C24',2,'mc','auto','남아메리카의 세 나라 설명 가운데 ㉡에 해당하는 나라는 어디인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C24","difficulty":2,"kind":"mc","stem":"남아메리카의 세 나라 설명 가운데 ㉡에 해당하는 나라는 어디인가요?","options":[{"t":"칠레","correct":true},{"t":"브라질","mis":"SO6-1-u3-X40"},{"t":"아르헨티나","mis":"SO6-1-u3-X40"},{"t":"파라과이","mis":"SO6-1-u3-X40"}],"explanation":["남북으로 아주 길어요.","서쪽이 태평양이에요.","칠레예요."],"asset":{"type":"passage","lines":["㉠ 남아메리카에서 가장 넓은 나라로, 열 나라와 국경을 맞댄다.","㉡ 동서 길이에 비해 남북 길이가 매우 길고 서쪽은 태평양과 접한다.","㉢ 남아메리카 남부에 있으며 동쪽으로 대서양과 접한다."],"title":"남아메리카의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
