INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#2','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C23',2,'ox','auto','북아메리카에 있는 모든 나라는 바다와 접해 있어요.',ARRAY['SO6-1-u3-X39']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C23","difficulty":2,"kind":"ox","stem":"북아메리카에 있는 모든 나라는 바다와 접해 있어요.","answer":"O","reason_options":[{"t":"북아메리카에는 바다에 접하지 않은 나라가 없기 때문에","correct":true},{"t":"북아메리카는 사방이 육지로 막힌 대륙이기 때문에","mis":"SO6-1-u3-X39"}],"mis":"SO6-1-u3-X39","explanation":["대서양과 태평양 사이예요.","모든 나라가 바다에 닿아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#3','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C25',3,'mc','auto','북아메리카와 남아메리카가 이어져 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X41']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C25","difficulty":3,"kind":"mc","stem":"북아메리카와 남아메리카가 이어져 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 대륙에 함께 닿아 있는 좁고 잘록한 땅인 파나마 지협이 있기 때문에","correct":true},{"t":"가장 큰 섬인 그린란드가 두 대륙 사이에 있기 때문에","mis":"SO6-1-u3-X41"},{"t":"가장 긴 산맥인 안데스산맥이 두 대륙을 덮기 때문에","mis":"SO6-1-u3-X41"},{"t":"두 대륙 사이에 바다가 없기 때문에","mis":"SO6-1-u3-X41"}],"explanation":["두 쪽에 함께 닿아야 해요.","크기로 이어지지 않아요.","파나마 지협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#4','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C24',3,'mc','auto','남아메리카에서 브라질과 국경을 마주하지 않은 두 나라는 어느 것인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C24","difficulty":3,"kind":"mc","stem":"남아메리카에서 브라질과 국경을 마주하지 않은 두 나라는 어느 것인가요?","options":[{"t":"에콰도르와 칠레","correct":true},{"t":"볼리비아와 파라과이","mis":"SO6-1-u3-X40"},{"t":"페루와 콜롬비아","mis":"SO6-1-u3-X40"},{"t":"아르헨티나와 볼리비아","mis":"SO6-1-u3-X40"}],"explanation":["브라질의 이웃을 지워 봐요.","서쪽 끝 나라들이에요.","에콰도르와 칠레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#5','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C23',3,'mc','auto','캐나다와 미국의 국경선에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X39']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C23","difficulty":3,"kind":"mc","stem":"캐나다와 미국의 국경선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"국경선 일부가 직선으로 반듯하다","correct":true},{"t":"두 나라 사이에는 국경선이 없다","mis":"SO6-1-u3-X39"},{"t":"국경선이 모두 구불구불한 강을 따라간다","mis":"SO6-1-u3-X39"},{"t":"두 나라는 바다를 사이에 두고 떨어져 있다","mis":"SO6-1-u3-X39"}],"explanation":["따라 그려 봐요.","곧은 부분이 있어요.","직선으로 반듯해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#6','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C25',3,'ox','auto','그린란드와 안데스산맥은 아주 크고 길어서 두 대륙을 이어 줘요.',ARRAY['SO6-1-u3-X41']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C25","difficulty":3,"kind":"ox","stem":"그린란드와 안데스산맥은 아주 크고 길어서 두 대륙을 이어 줘요.","answer":"X","reason_options":[{"t":"둘 다 한 대륙 안에만 있어 두 쪽에 함께 닿아 있지 않기 때문에","correct":true},{"t":"크고 길면 언제나 두 대륙을 이어 주기 때문에","mis":"SO6-1-u3-X41"}],"mis":"SO6-1-u3-X41","explanation":["어느 대륙에 있나요?","한쪽에만 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#7','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C24',3,'error','auto','남아메리카의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C24","difficulty":3,"kind":"error","stem":"남아메리카의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「칠레는 동서 길이가 남북 길이보다 훨씬 길어.」","correct":true,"mis_target":"SO6-1-u3-X40"},{"t":"친구 가 — 「아르헨티나는 동쪽으로 대서양과 접해.」","mis":"SO6-1-u3-X40"},{"t":"친구 다 — 「칠레의 동쪽에는 안데스산맥이 있어.」","mis":"SO6-1-u3-X40"}],"explanation":["칠레를 떠올려요.","남북으로 아주 길어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#8','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C23',4,'mc','auto','미국의 영토를 지도에 색칠할 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X39']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C23","difficulty":4,"kind":"mc","stem":"미국의 영토를 지도에 색칠할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"본토뿐 아니라 알래스카 지역과 하와이 제도도 함께 색칠한다","correct":true},{"t":"본토만 색칠한다","mis":"SO6-1-u3-X39"},{"t":"알래스카 지역은 캐나다이므로 빼고 색칠한다","mis":"SO6-1-u3-X39"},{"t":"하와이 제도는 오세아니아에 있으므로 미국 영토가 아니다","mis":"SO6-1-u3-X39"}],"explanation":["영토가 나뉘어 있어요.","하와이 제도도 영토예요.","모두 함께 색칠해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#9','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C25',4,'mc','auto','파나마의 위치와 영토를 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X40','SO6-1-u3-X39','SO6-1-u3-X41']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C25","difficulty":4,"kind":"mc","stem":"파나마의 위치와 영토를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"북아메리카의 가장 남쪽 나라로 영토 전체가 두 대륙을 잇는 지협이다","correct":true},{"t":"남아메리카에서 가장 넓은 나라이다","mis":"SO6-1-u3-X40"},{"t":"북서쪽에서 남동쪽으로 길게 뻗은 북아메리카 남부의 큰 나라이다","mis":"SO6-1-u3-X39"},{"t":"두 대륙 가운데 한쪽에만 닿아 있다","mis":"SO6-1-u3-X41"}],"explanation":["두 대륙 사이예요.","영토 전체가 잘록해요.","첫째 것이에요."],"asset":{"type":"passage","lines":["북아메리카의 가장 남쪽에 있는 나라이다.","영토의 동서 길이가 남북 길이보다 길다.","영토 전체가 두 대륙을 잇는 좁고 잘록한 땅이다."],"title":"어느 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L08_challenge#10','soc',6,1,'u3','L08','g6_1_soc_u3_L08_challenge','lesson_challenge','SO6-1-u3-C24',4,'essay','teacher','남아메리카의 세 나라 ㉠~㉢의 이름을 쓰고, 그 가운데 두 나라의 영토 특징을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C24","difficulty":4,"kind":"essay","stem":"남아메리카의 세 나라 ㉠~㉢의 이름을 쓰고, 그 가운데 두 나라의 영토 특징을 견주어 쓰세요.","answer_guide":{"answer":"예: ㉠은 브라질, ㉡은 칠레, ㉢은 아르헨티나이다. 브라질은 남아메리카에서 가장 넓은 나라로 열 나라와 국경을 맞대고 있지만, 칠레는 동서 길이에 비해 남북 길이가 매우 길고 동쪽에는 안데스산맥, 서쪽에는 태평양이 있다.","scoring_points":["세 나라 이름을 바르게 썼는가","두 나라의 영토 특징을 썼는가","두 나라를 견주어 썼는가"]},"explanation":["가장 넓은 나라부터요.","남북으로 긴 나라예요.","대서양과 접한 나라예요."],"asset":{"type":"passage","lines":["㉠ 남아메리카에서 가장 넓은 나라로, 열 나라와 국경을 맞댄다.","㉡ 동서 길이에 비해 남북 길이가 매우 길고 서쪽은 태평양과 접한다.","㉢ 남아메리카 남부에 있으며 동쪽으로 대서양과 접한다."],"title":"남아메리카의 세 나라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#1','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',1,'mc','auto','[생각을 펼쳐요] 첫 활동에서 대륙별로 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42','SO6-1-u3-X43']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"mc","stem":"[생각을 펼쳐요] 첫 활동에서 대륙별로 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"가 보고 싶은 나라를 하나씩 정하고 그 까닭을 쓴다","correct":true},{"t":"한 대륙에서 여러 나라를 골라 모두 쓴다","mis":"SO6-1-u3-X42"},{"t":"대륙 이름만 쓰고 나라는 쓰지 않는다","mis":"SO6-1-u3-X42"},{"t":"가장 넓은 나라만 찾아 쓴다","mis":"SO6-1-u3-X43"}],"explanation":["대륙마다예요.","하나씩 정해요.","까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#2','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',1,'sa','auto','어느 친구의 여행 경로에서 빈칸에 들어갈 도착 나라를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"sa","stem":"어느 친구의 여행 경로에서 빈칸에 들어갈 도착 나라를 쓰세요.","answer":["대한민국","우리나라","한국"],"explanation":["어디에서 출발했나요?","출발한 곳으로 돌아와요.","대한민국이에요."],"asset":{"type":"passage","lines":["대한민국 출발 → 독일 → 이집트 → 뉴질랜드 → 칠레 → 미국 → 일본","→ (    )"],"title":"어느 친구의 여행 경로"},"mis":"SO6-1-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#3','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',1,'ox','auto','가 보고 싶은 나라의 위치와 영토의 특징은 지구본, 세계지도, 디지털 영상 지도로 살펴볼 수 있어요.',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"ox","stem":"가 보고 싶은 나라의 위치와 영토의 특징은 지구본, 세계지도, 디지털 영상 지도로 살펴볼 수 있어요.","answer":"O","reason_options":[{"t":"이 단원에서 배운 세 자료가 위치와 영토를 살펴보는 데 쓰이기 때문에","correct":true},{"t":"나라의 위치는 달력과 시계로 살펴보기 때문에","mis":"SO6-1-u3-X42"}],"mis":"SO6-1-u3-X42","explanation":["세 자료를 떠올려요.","위치를 살펴봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#4','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',1,'mc','auto','여행 경로를 만들 때 고려해야 하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"mc","stem":"여행 경로를 만들 때 고려해야 하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"대륙 및 나라의 위치","correct":true},{"t":"나라 이름의 글자 수","mis":"SO6-1-u3-X42"},{"t":"친구가 고른 나라의 수","mis":"SO6-1-u3-X42"},{"t":"나라 이름의 가나다 차례","mis":"SO6-1-u3-X42"}],"explanation":["길은 어디에서 어디로 가요.","위치를 봐야 해요.","대륙 및 나라의 위치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#5','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',2,'mc','auto','어느 친구가 표를 만들 때 대륙을 여섯만 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X24','SO6-1-u3-X23']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"mc","stem":"어느 친구가 표를 만들 때 대륙을 여섯만 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 살기 어려운 남극 대륙을 빼고 여섯 대륙에 하나씩 정했기 때문에","correct":true},{"t":"대륙이 모두 여섯 개뿐이기 때문에","mis":"SO6-1-u3-X24"},{"t":"남극 대륙은 대륙이 아니기 때문에","mis":"SO6-1-u3-X23"},{"t":"오세아니아는 대륙이 아니기 때문에","mis":"SO6-1-u3-X24"}],"explanation":["대륙은 일곱이에요.","얼음으로 덮인 대륙이 있어요.","남극 대륙을 뺐어요."],"asset":{"type":"passage","lines":["아시아 — 일본 · 섬나라라서","오세아니아 — 뉴질랜드 · 남반구에 있는 나라라서","유럽 — 독일 · 아홉 나라와 국경을 맞대서","아프리카 — 이집트 · 국경선 일부가 반듯해서","북아메리카 — 미국 · 영토가 나뉘어 있어서","남아메리카 — 칠레 · 남북으로 아주 길어서"],"title":"어느 친구가 정한 나라와 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#6','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',2,'match','auto','어느 친구가 고른 나라와 그 나라가 속한 대륙을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"match","stem":"어느 친구가 고른 나라와 그 나라가 속한 대륙을 알맞게 이으세요.","pairs":[{"l":"뉴질랜드","r":"오세아니아"},{"l":"이집트","r":"아프리카"},{"l":"칠레","r":"남아메리카"},{"l":"독일","r":"유럽"}],"mis":"SO6-1-u3-X27","explanation":["남반구의 섬나라예요.","북동쪽 끝의 나라예요.","남북으로 긴 나라와 아홉 나라의 이웃이에요."],"asset":{"type":"passage","lines":["아시아 — 일본 · 섬나라라서","오세아니아 — 뉴질랜드 · 남반구에 있는 나라라서","유럽 — 독일 · 아홉 나라와 국경을 맞대서","아프리카 — 이집트 · 국경선 일부가 반듯해서","북아메리카 — 미국 · 영토가 나뉘어 있어서","남아메리카 — 칠레 · 남북으로 아주 길어서"],"title":"어느 친구가 정한 나라와 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#7','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',2,'blank','auto','여행 경로는 출발한 곳에서 시작해 출발한 곳으로 (    )와야 완성돼요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"blank","stem":"여행 경로는 출발한 곳에서 시작해 출발한 곳으로 (    )와야 완성돼요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"돌아","correct":true},{"t":"멀어져","mis":"SO6-1-u3-X42"},{"t":"건너뛰어","mis":"SO6-1-u3-X42"},{"t":"멈춰","mis":"SO6-1-u3-X42"}],"explanation":["처음과 끝을 봐요.","같은 곳이에요.","돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#8','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',2,'mc','auto','뒤섞인 활동 차례를 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"mc","stem":"뒤섞인 활동 차례를 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉠ → ㉡ → ㉣ → ㉢","mis":"SO6-1-u3-X42"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SO6-1-u3-X42"},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SO6-1-u3-X42"}],"explanation":["먼저 나라를 정해요.","살펴보고 길을 만들어요.","마지막에 소개해요."],"asset":{"type":"passage","lines":["㉠ 위치를 고려해 여행 경로를 만들고 세계지도에 나타낸다.","㉡ 대륙별로 가 보고 싶은 나라를 하나씩 정하고 까닭을 쓴다.","㉢ 완성한 여행 경로를 친구들에게 소개한다.","㉣ 여러 자료로 그 나라의 위치와 영토의 특징을 살펴본다."],"title":"뒤섞인 활동 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#9','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C18',2,'mc','auto','오세아니아의 뉴질랜드를 살펴본 친구가 말한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27','SO6-1-u3-X39','SO6-1-u3-X40']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C18","difficulty":2,"kind":"mc","stem":"오세아니아의 뉴질랜드를 살펴본 친구가 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「남반구에 있고, 바다로 둘러싸여 있어.」","correct":true},{"t":"「북반구에 있고, 여러 나라와 국경을 맞대.」","mis":"SO6-1-u3-X27"},{"t":"「캐나다를 사이에 두고 영토가 나뉘어 있어.」","mis":"SO6-1-u3-X39"},{"t":"「동서 길이에 비해 남북 길이가 매우 길어.」","mis":"SO6-1-u3-X40"}],"explanation":["적도의 아래쪽이에요.","섬으로 이루어져요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_basic#10','soc',6,1,'u3','L09','g6_1_soc_u3_L09_basic','lesson_basic','SO6-1-u3-C26',3,'error','auto','[생각을 펼쳐요]를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X43','SO6-1-u3-X42']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C26","difficulty":3,"kind":"error","stem":"[생각을 펼쳐요]를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「내가 고른 나라가 친구가 고른 나라보다 더 좋은 나라야.」","correct":true,"mis_target":"SO6-1-u3-X43"},{"t":"친구 가 — 「가 보고 싶은 까닭은 사람마다 달라.」","mis":"SO6-1-u3-X43"},{"t":"친구 나 — 「완성한 경로를 친구들에게 소개하자.」","mis":"SO6-1-u3-X42"}],"explanation":["더 좋은 나라가 있을까요?","까닭은 사람마다 달라요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#1','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',2,'sa','auto','어느 친구의 여행 경로에서 출발 나라를 빼고 들르는 나라는 모두 몇 나라인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"sa","stem":"어느 친구의 여행 경로에서 출발 나라를 빼고 들르는 나라는 모두 몇 나라인가요? 숫자만 쓰세요.","answer":["6","여섯"],"explanation":["화살표를 따라 세어요.","도착은 출발한 나라예요.","여섯 나라예요."],"asset":{"type":"passage","lines":["대한민국 출발 → 독일 → 이집트 → 뉴질랜드 → 칠레 → 미국 → 일본","→ (    )"],"title":"어느 친구의 여행 경로"},"mis":"SO6-1-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#2','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',2,'ox','auto','여섯 나라를 모두 들렀다면 출발한 곳으로 돌아오지 않아도 여행 경로가 완성돼요.',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"ox","stem":"여섯 나라를 모두 들렀다면 출발한 곳으로 돌아오지 않아도 여행 경로가 완성돼요.","answer":"X","reason_options":[{"t":"여행 경로는 출발한 곳으로 돌아와야 닫히기 때문에","correct":true},{"t":"여행 경로는 나라를 늘어놓은 줄이면 충분하기 때문에","mis":"SO6-1-u3-X42"}],"mis":"SO6-1-u3-X42","explanation":["활동판의 끝을 떠올려요.","도착도 대한민국이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#3','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',3,'mc','auto','여행 경로에서 마지막에 대한민국으로 돌아오는 걸음에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C26","difficulty":3,"kind":"mc","stem":"여행 경로에서 마지막에 대한민국으로 돌아오는 걸음에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"들른 나라는 늘지 않고 이어진 선만 하나 늘어 길이 닫힌다","correct":true},{"t":"새 나라를 하나 더 들르는 걸음이다","mis":"SO6-1-u3-X42"},{"t":"들른 나라를 하나 지우는 걸음이다","mis":"SO6-1-u3-X42"},{"t":"아무 일도 일어나지 않는 걸음이다","mis":"SO6-1-u3-X42"}],"explanation":["이미 다녀온 자리예요.","나라 수는 그대로예요.","길이 닫혀요."],"asset":{"type":"passage","lines":["대한민국 출발 → 독일 → 이집트 → 뉴질랜드 → 칠레 → 미국 → 일본","→ (    )"],"title":"어느 친구의 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#4','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C16',3,'mc','auto','어느 친구가 일본을 고른 까닭 「섬나라라서」와 이어지는 일본의 영토 특징은 어느 것인가요?',ARRAY['SO6-1-u3-X29','SO6-1-u3-X36']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C16","difficulty":3,"kind":"mc","stem":"어느 친구가 일본을 고른 까닭 「섬나라라서」와 이어지는 일본의 영토 특징은 어느 것인가요?","options":[{"t":"네 개의 큰 섬과 수천 개의 작은 섬으로 이루어져 있다","correct":true},{"t":"영토가 동서로 넓게 펼쳐져 있다","mis":"SO6-1-u3-X29"},{"t":"아라비아반도의 대부분을 차지한다","mis":"SO6-1-u3-X29"},{"t":"여러 나라에 둘러싸여 바다가 없다","mis":"SO6-1-u3-X36"}],"explanation":["섬나라예요.","큰 섬이 넷이에요.","첫째 것이에요."],"asset":{"type":"passage","lines":["아시아 — 일본 · 섬나라라서","오세아니아 — 뉴질랜드 · 남반구에 있는 나라라서","유럽 — 독일 · 아홉 나라와 국경을 맞대서","아프리카 — 이집트 · 국경선 일부가 반듯해서","북아메리카 — 미국 · 영토가 나뉘어 있어서","남아메리카 — 칠레 · 남북으로 아주 길어서"],"title":"어느 친구가 정한 나라와 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#5','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C23',3,'mc','auto','어느 친구가 미국을 고른 까닭 「영토가 나뉘어 있어서」를 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u3-X39','SO6-1-u3-X41']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C23","difficulty":3,"kind":"mc","stem":"어느 친구가 미국을 고른 까닭 「영토가 나뉘어 있어서」를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"캐나다를 사이에 두고 본토와 알래스카 지역으로 나뉘어 있다","correct":true},{"t":"멕시코를 사이에 두고 두 지역으로 나뉘어 있다","mis":"SO6-1-u3-X39"},{"t":"영토 전체가 두 대륙을 잇는 지협이다","mis":"SO6-1-u3-X41"},{"t":"적도를 기준으로 둘로 나뉘어 있다","mis":"SO6-1-u3-X39"}],"explanation":["북쪽의 이웃 나라예요.","알래스카예요.","첫째 것이에요."],"asset":{"type":"passage","lines":["아시아 — 일본 · 섬나라라서","오세아니아 — 뉴질랜드 · 남반구에 있는 나라라서","유럽 — 독일 · 아홉 나라와 국경을 맞대서","아프리카 — 이집트 · 국경선 일부가 반듯해서","북아메리카 — 미국 · 영토가 나뉘어 있어서","남아메리카 — 칠레 · 남북으로 아주 길어서"],"title":"어느 친구가 정한 나라와 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#6','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',3,'ox','auto','같은 여섯 나라를 골라도 위치를 고려하면 친구마다 서로 다른 여행 경로를 만들 수 있어요.',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C26","difficulty":3,"kind":"ox","stem":"같은 여섯 나라를 골라도 위치를 고려하면 친구마다 서로 다른 여행 경로를 만들 수 있어요.","answer":"O","reason_options":[{"t":"들르는 차례는 정해져 있지 않고 위치를 보고 스스로 정하기 때문에","correct":true},{"t":"여행 경로는 누구나 똑같은 차례로만 만들 수 있기 때문에","mis":"SO6-1-u3-X42"}],"mis":"SO6-1-u3-X42","explanation":["차례가 정해져 있나요?","위치를 보고 내가 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#7','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',3,'error','auto','여행 경로 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C26","difficulty":3,"kind":"error","stem":"여행 경로 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「위치는 생각하지 말고 이름이 마음에 드는 차례로 이으면 돼.」","correct":true,"mis_target":"SO6-1-u3-X42"},{"t":"친구 나 — 「가까운 나라끼리 이어 가면 길이 덜 엇갈려.」","mis":"SO6-1-u3-X42"},{"t":"친구 다 — 「완성한 경로는 세계지도에 나타내.」","mis":"SO6-1-u3-X42"}],"explanation":["경로를 만들 때 무엇을 고려하나요?","위치예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#8','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',4,'mc','auto','[생각을 펼쳐요] 활동으로 기를 수 있는 힘으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42','SO6-1-u3-X43']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":4,"kind":"mc","stem":"[생각을 펼쳐요] 활동으로 기를 수 있는 힘으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라에 관한 지리 정보를 조사해 활용하는 힘과 창의적으로 생각하는 힘","correct":true},{"t":"나라 이름을 빨리 외우는 힘","mis":"SO6-1-u3-X42"},{"t":"가장 좋은 나라를 가려내는 힘","mis":"SO6-1-u3-X43"},{"t":"자료 없이 어림으로 정하는 힘","mis":"SO6-1-u3-X42"}],"explanation":["조사하고 활용해요.","경로를 새로 만들어요.","정보 활용 능력과 창의적 사고력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#9','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C21',4,'mc','auto','어느 친구가 이집트를 고른 까닭 「국경선 일부가 반듯해서」와 관련해 알맞은 설명은 어느 것인가요?',ARRAY['SO6-1-u3-X37','SO6-1-u3-X38','SO6-1-u3-X20']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"mc","stem":"어느 친구가 이집트를 고른 까닭 「국경선 일부가 반듯해서」와 관련해 알맞은 설명은 어느 것인가요?","options":[{"t":"과거 식민지로 삼으며 위도나 경도를 따라 그은 직선이 국경이 되었다","correct":true},{"t":"이집트의 땅이 모두 평평해 저절로 반듯해졌다","mis":"SO6-1-u3-X37"},{"t":"이집트는 남아프리카 공화국에 둘러싸여 있다","mis":"SO6-1-u3-X38"},{"t":"이집트는 적도가 지나는 나라이다","mis":"SO6-1-u3-X20"}],"explanation":["반듯한 국경선의 까닭이에요.","누가 그었을까요?","첫째 것이에요."],"asset":{"type":"passage","lines":["아시아 — 일본 · 섬나라라서","오세아니아 — 뉴질랜드 · 남반구에 있는 나라라서","유럽 — 독일 · 아홉 나라와 국경을 맞대서","아프리카 — 이집트 · 국경선 일부가 반듯해서","북아메리카 — 미국 · 영토가 나뉘어 있어서","남아메리카 — 칠레 · 남북으로 아주 길어서"],"title":"어느 친구가 정한 나라와 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_L09_challenge#10','soc',6,1,'u3','L09','g6_1_soc_u3_L09_challenge','lesson_challenge','SO6-1-u3-C26',4,'essay','teacher','대륙 두 곳을 골라 가 보고 싶은 나라와 그 까닭을 위치와 영토의 특징을 넣어 쓰고, 두 나라를 넣은 여행 경로를 출발부터 도착까지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C26","difficulty":4,"kind":"essay","stem":"대륙 두 곳을 골라 가 보고 싶은 나라와 그 까닭을 위치와 영토의 특징을 넣어 쓰고, 두 나라를 넣은 여행 경로를 출발부터 도착까지 쓰세요.","answer_guide":{"answer":"예: 오세아니아에서는 남반구에 있고 두 개의 큰 섬과 여러 작은 섬으로 이루어진 뉴질랜드에, 남아메리카에서는 동서 길이에 비해 남북 길이가 매우 긴 칠레에 가 보고 싶다. 대한민국에서 출발해 뉴질랜드, 칠레를 거쳐 다시 대한민국으로 돌아오는 경로를 만들겠다.","scoring_points":["대륙 두 곳에서 나라를 하나씩 골랐는가","위치와 영토의 특징을 넣어 까닭을 썼는가","출발한 곳으로 돌아오는 경로를 썼는가"]},"explanation":["대륙마다 하나씩이에요.","위치와 영토를 넣어요.","출발한 곳으로 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#1','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C1',1,'mc','auto','모둠 나가 고르기에 더 알맞은 자료는 어느 것인가요?',ARRAY['SO6-1-u3-X05']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C1","difficulty":1,"kind":"mc","stem":"모둠 나가 고르기에 더 알맞은 자료는 어느 것인가요?","options":[{"t":"지구본","correct":true},{"t":"세계지도","mis":"SO6-1-u3-X05"},{"t":"달력","mis":"SO6-1-u3-X05"},{"t":"사진첩","mis":"SO6-1-u3-X05"}],"explanation":["면적을 견줘요.","비교적 정확해야 해요.","지구본이에요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#2','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C7',1,'mc','auto','적도를 기준으로 남북으로 얼마나 떨어져 있는지 나타내는 것은 어느 것인가요?',ARRAY['SO6-1-u3-X10','SO6-1-u3-X16','SO6-1-u3-X23']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C7","difficulty":1,"kind":"mc","stem":"적도를 기준으로 남북으로 얼마나 떨어져 있는지 나타내는 것은 어느 것인가요?","options":[{"t":"위도","correct":true},{"t":"경도","mis":"SO6-1-u3-X10"},{"t":"시차","mis":"SO6-1-u3-X16"},{"t":"대양","mis":"SO6-1-u3-X23"}],"explanation":["남북이에요.","기준은 적도예요.","위도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#3','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C15',1,'mc','auto','일지 ④의 ㉠에 해당하는 대양은 어느 것인가요?',ARRAY['SO6-1-u3-X25','SO6-1-u3-X26']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"mc","stem":"일지 ④의 ㉠에 해당하는 대양은 어느 것인가요?","options":[{"t":"태평양","correct":true},{"t":"대서양","mis":"SO6-1-u3-X25"},{"t":"인도양","mis":"SO6-1-u3-X25"},{"t":"남극해","mis":"SO6-1-u3-X26"}],"explanation":["가장 넓어요.","네 대륙 사이예요.","태평양이에요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#4','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C14',1,'mc','auto','세계의 대륙이 아닌 것은 어느 것인가요?',ARRAY['SO6-1-u3-X24']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C14","difficulty":1,"kind":"mc","stem":"세계의 대륙이 아닌 것은 어느 것인가요?","options":[{"t":"대서양","correct":true},{"t":"오세아니아","mis":"SO6-1-u3-X24"},{"t":"남아메리카","mis":"SO6-1-u3-X24"},{"t":"아프리카","mis":"SO6-1-u3-X24"}],"explanation":["육지를 찾아요.","바다 이름이 섞였어요.","대서양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#5','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C16',1,'mc','auto','일지 ⑤의 엽서 1을 보낸 나라는 어디인가요?',ARRAY['SO6-1-u3-X29','SO6-1-u3-X28']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C16","difficulty":1,"kind":"mc","stem":"일지 ⑤의 엽서 1을 보낸 나라는 어디인가요?","options":[{"t":"중국","correct":true},{"t":"일본","mis":"SO6-1-u3-X29"},{"t":"사우디아라비아","mis":"SO6-1-u3-X29"},{"t":"뉴질랜드","mis":"SO6-1-u3-X28"}],"explanation":["동서로 넓어요.","서쪽이 높아요.","중국이에요."],"asset":{"type":"passage","lines":["엽서 1 — 영토가 동서로 넓은 나라: 서쪽으로 갈수록 땅이 높아져요.","엽서 2 — 오세아니아에서 가장 큰 나라: 나라 하나가 곧 대륙이에요.","엽서 3 — 바다로 둘러싸인 작은 섬나라: 다이빙하러 온 사람이 많아요."],"title":"일지 ⑤ — 아시아·오세아니아에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#6','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C20',1,'mc','auto','일지 ⑥의 엽서 4를 보낸 나라는 어디인가요?',ARRAY['SO6-1-u3-X34','SO6-1-u3-X36']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C20","difficulty":1,"kind":"mc","stem":"일지 ⑥의 엽서 4를 보낸 나라는 어디인가요?","options":[{"t":"노르웨이","correct":true},{"t":"영국","mis":"SO6-1-u3-X34"},{"t":"독일","mis":"SO6-1-u3-X34"},{"t":"이집트","mis":"SO6-1-u3-X36"}],"explanation":["길게 뻗었어요.","북쪽 섬에 과학 기지가 있어요.","노르웨이예요."],"asset":{"type":"passage","lines":["엽서 4 — 길게 뻗은 나라의 북쪽 섬들: 우리나라 과학 기지가 있어요.","엽서 5 — 다른 나라의 수도에 둘러싸인 아주 작은 나라예요.","엽서 6 — 아프리카 북동쪽 끝 나라: 국경선이 자로 그은 듯 반듯해요."],"title":"일지 ⑥ — 유럽·아프리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#7','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C25',1,'mc','auto','일지 ⑦의 엽서 7을 보낸 나라는 어디인가요?',ARRAY['SO6-1-u3-X41','SO6-1-u3-X40']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C25","difficulty":1,"kind":"mc","stem":"일지 ⑦의 엽서 7을 보낸 나라는 어디인가요?","options":[{"t":"파나마","correct":true},{"t":"멕시코","mis":"SO6-1-u3-X41"},{"t":"칠레","mis":"SO6-1-u3-X40"},{"t":"브라질","mis":"SO6-1-u3-X40"}],"explanation":["좁고 잘록한 땅이에요.","두 대륙을 이어요.","파나마예요."],"asset":{"type":"passage","lines":["엽서 7 — 두 대륙을 잇는 좁고 잘록한 땅의 나라예요.","엽서 8 — 남북으로 아주 긴 나라: 동쪽에 높은 산맥이 있어요.","엽서 9 — 이웃 나라를 사이에 두고 본토와 떨어진 북쪽 지역이에요."],"title":"일지 ⑦ — 아메리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#8','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C26',1,'mc','auto','일지 ⑧의 경로에서 마지막에 더해야 할 나라는 어디인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"mc","stem":"일지 ⑧의 경로에서 마지막에 더해야 할 나라는 어디인가요?","options":[{"t":"대한민국","correct":true},{"t":"일본","mis":"SO6-1-u3-X42"},{"t":"미국","mis":"SO6-1-u3-X42"},{"t":"더할 나라가 없다","mis":"SO6-1-u3-X42"}],"explanation":["어디에서 출발했나요?","돌아와야 닫혀요.","대한민국이에요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#9','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C3',2,'mc','auto','일지 ①에서 모둠과 자료를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X05','SO6-1-u3-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C3","difficulty":2,"kind":"mc","stem":"일지 ①에서 모둠과 자료를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"가 — 세계지도, 나 — 지구본, 다 — 디지털 영상 지도","correct":true},{"t":"가 — 지구본, 나 — 세계지도, 다 — 디지털 영상 지도","mis":"SO6-1-u3-X05"},{"t":"가 — 디지털 영상 지도, 나 — 세계지도, 다 — 지구본","mis":"SO6-1-u3-X05"},{"t":"가 — 세계지도, 나 — 세계지도, 다 — 세계지도","mis":"SO6-1-u3-X01"}],"explanation":["한눈에는 평면이에요.","정확하게는 모형이에요.","실제 모습은 사진이에요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#10','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C10',2,'mc','auto','일지 ②의 기지 가와 기지 다에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X17','SO6-1-u3-X10','SO6-1-u3-X16']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C10","difficulty":2,"kind":"mc","stem":"일지 ②의 기지 가와 기지 다에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 기지는 경도가 달라 시각이 다르다","correct":true},{"t":"두 기지는 위도가 달라 햇볕을 받는 양이 크게 다르다","mis":"SO6-1-u3-X17"},{"t":"두 기지는 위도와 경도가 모두 같다","mis":"SO6-1-u3-X10"},{"t":"두 기지는 시각이 언제나 같다","mis":"SO6-1-u3-X16"}],"explanation":["위도는 같아요.","동쪽으로 멀어요.","시각이 달라요."],"asset":{"type":"passage","lines":["기지 가 — 적도 가까운 북쪽","기지 나 — 기지 가와 경도가 같고, 북극에 가까운 곳","기지 다 — 기지 가와 위도가 같고, 동쪽으로 멀리 떨어진 곳"],"title":"일지 ② — 상상 탐험 기지 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#11','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C12',2,'mc','auto','일지 ③의 ㉮에 해당하는 나라는 어디인가요?',ARRAY['SO6-1-u3-X20','SO6-1-u3-X21','SO6-1-u3-X36']::text[],false,'{"seq":11,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"mc","stem":"일지 ③의 ㉮에 해당하는 나라는 어디인가요?","options":[{"t":"케냐","correct":true},{"t":"영국","mis":"SO6-1-u3-X20"},{"t":"브라질","mis":"SO6-1-u3-X21"},{"t":"이집트","mis":"SO6-1-u3-X36"}],"explanation":["적도가 지나요.","아프리카 동부예요.","케냐예요."],"asset":{"type":"passage","lines":["㉮ 적도가 지나는, 아프리카 동부의 나라","㉯ 본초 자오선이 지나는, 유럽 서쪽의 섬나라","㉰ 남위 10°~20°, 서경 40°~50° 범위가 속한 나라"],"title":"일지 ③ — 탐험 깃발 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#12','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C15',2,'mc','auto','대부분 북반구에 있는 대륙끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":12,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"mc","stem":"대부분 북반구에 있는 대륙끼리 짝지은 것은 어느 것인가요?","options":[{"t":"아시아, 유럽","correct":true},{"t":"오세아니아, 남아메리카","mis":"SO6-1-u3-X27"},{"t":"남극 대륙, 오세아니아","mis":"SO6-1-u3-X27"},{"t":"남아메리카, 남극 대륙","mis":"SO6-1-u3-X27"}],"explanation":["적도의 위쪽이에요.","둘 다 위쪽이에요.","아시아와 유럽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#13','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C17',2,'mc','auto','우리나라의 위치와 영토에 대한 설명으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X30']::text[],false,'{"seq":13,"concept":"SO6-1-u3-C17","difficulty":2,"kind":"mc","stem":"우리나라의 위치와 영토에 대한 설명으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"영토가 동서로 넓게 펼쳐져 있다","correct":true},{"t":"북반구에 있다","mis":"SO6-1-u3-X30"},{"t":"아시아 대륙의 동쪽에 있다","mis":"SO6-1-u3-X30"},{"t":"삼면이 바다로 둘러싸여 있다","mis":"SO6-1-u3-X30"}],"explanation":["「알맞지 않은」 것을 골라요.","영토 모양을 떠올려요.","동서로 넓은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#14','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C21',2,'mc','auto','아프리카에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X35']::text[],false,'{"seq":14,"concept":"SO6-1-u3-C21","difficulty":2,"kind":"mc","stem":"아프리카에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"아시아 다음으로 넓고 가장 많은 나라가 있다","correct":true},{"t":"세계에서 가장 작은 대륙이다","mis":"SO6-1-u3-X35"},{"t":"북반구에만 있다","mis":"SO6-1-u3-X35"},{"t":"유럽의 북쪽에 있다","mis":"SO6-1-u3-X35"}],"explanation":["두 번째로 넓어요.","나라가 가장 많아요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#15','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C23',2,'mc','auto','캐나다에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X39','SO6-1-u3-X41']::text[],false,'{"seq":15,"concept":"SO6-1-u3-C23","difficulty":2,"kind":"mc","stem":"캐나다에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"태평양·대서양·북극해에 접하고 남쪽으로 미국 본토와 국경을 맞댄다","correct":true},{"t":"북아메리카 남부에 있으며 북서쪽에서 남동쪽으로 길게 뻗어 있다","mis":"SO6-1-u3-X39"},{"t":"바다에 접하지 않은 나라이다","mis":"SO6-1-u3-X39"},{"t":"영토 전체가 지협이다","mis":"SO6-1-u3-X41"}],"explanation":["북아메리카의 북쪽이에요.","세 대양에 접해요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#16','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C26',2,'mc','auto','일지 ⑧에서 친구가 「아직 길이 닫히지 않았어.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":16,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"mc","stem":"일지 ⑧에서 친구가 「아직 길이 닫히지 않았어.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"출발한 대한민국으로 돌아오지 않았기 때문에","correct":true},{"t":"여섯 대륙을 모두 들렀기 때문에","mis":"SO6-1-u3-X42"},{"t":"나라를 들르는 차례가 정해진 차례와 달랐기 때문에","mis":"SO6-1-u3-X42"},{"t":"같은 대륙의 나라를 두 번 들렀기 때문에","mis":"SO6-1-u3-X42"}],"explanation":["처음과 끝을 봐요.","끝이 출발한 곳이 아니에요.","돌아와야 닫혀요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#17','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C3',3,'mc','auto','같은 두 자리를 세계지도에서는 자로, 지구본에서는 실로 이었을 때 지나는 길이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X01','SO6-1-u3-X05']::text[],false,'{"seq":17,"concept":"SO6-1-u3-C3","difficulty":3,"kind":"mc","stem":"같은 두 자리를 세계지도에서는 자로, 지구본에서는 실로 이었을 때 지나는 길이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"둥근 지구를 평면으로 펼친 세계지도는 거리와 모양이 실제와 다르게 나타날 수 있기 때문에","correct":true},{"t":"실이 자보다 언제나 짧기 때문에","mis":"SO6-1-u3-X01"},{"t":"지구본이 세계지도보다 언제나 좋은 자료이기 때문에","mis":"SO6-1-u3-X01"},{"t":"두 자리를 잘못 골랐기 때문에","mis":"SO6-1-u3-X05"}],"explanation":["평면과 공 모양이에요.","펼치면 달라져요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#18','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C17',3,'mc','auto','북위 33°~43°, 동경 124°~132° 범위가 알려 주는 우리나라의 위치로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X13']::text[],false,'{"seq":18,"concept":"SO6-1-u3-C17","difficulty":3,"kind":"mc","stem":"북위 33°~43°, 동경 124°~132° 범위가 알려 주는 우리나라의 위치로 알맞은 것은 어느 것인가요?","options":[{"t":"적도의 북쪽, 본초 자오선의 동쪽에 있다","correct":true},{"t":"적도의 남쪽, 본초 자오선의 서쪽에 있다","mis":"SO6-1-u3-X13"},{"t":"적도의 북쪽, 본초 자오선의 서쪽에 있다","mis":"SO6-1-u3-X13"},{"t":"적도 위에 있다","mis":"SO6-1-u3-X13"}],"explanation":["북위예요.","동경이에요.","북쪽과 동쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#19','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C15',3,'mc','auto','아시아가 맞닿은 대양이 아닌 것은 어느 것인가요?',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":19,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"mc","stem":"아시아가 맞닿은 대양이 아닌 것은 어느 것인가요?","options":[{"t":"남극해","correct":true},{"t":"태평양","mis":"SO6-1-u3-X26"},{"t":"인도양","mis":"SO6-1-u3-X26"},{"t":"북극해","mis":"SO6-1-u3-X26"}],"explanation":["아시아의 둘레를 떠올려요.","남극 대륙만 둘러싼 바다가 있어요.","남극해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#20','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C16',3,'mc','auto','영토의 모습이 서로 비슷한 두 나라를 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X30','SO6-1-u3-X34','SO6-1-u3-X36']::text[],false,'{"seq":20,"concept":"SO6-1-u3-C16","difficulty":3,"kind":"mc","stem":"영토의 모습이 서로 비슷한 두 나라를 짝지은 것은 어느 것인가요?","options":[{"t":"칠레와 우리나라 — 둘 다 남북으로 긴 모양이다","correct":true},{"t":"중국과 우리나라 — 둘 다 동서로 넓은 모양이다","mis":"SO6-1-u3-X30"},{"t":"일본과 스위스 — 둘 다 섬나라이다","mis":"SO6-1-u3-X34"},{"t":"에티오피아와 영국 — 둘 다 섬나라이다","mis":"SO6-1-u3-X36"}],"explanation":["남북으로 긴 나라를 찾아요.","칠레도 그래요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#21','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C25',3,'mc','auto','두 대륙을 이어 주는 땅의 조건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X41']::text[],false,'{"seq":21,"concept":"SO6-1-u3-C25","difficulty":3,"kind":"mc","stem":"두 대륙을 이어 주는 땅의 조건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 대륙 모두에 함께 닿아 있어야 한다","correct":true},{"t":"세계에서 가장 커야 한다","mis":"SO6-1-u3-X41"},{"t":"세계에서 가장 길어야 한다","mis":"SO6-1-u3-X41"},{"t":"한 대륙 안에만 있어야 한다","mis":"SO6-1-u3-X41"}],"explanation":["그린란드와 안데스산맥을 떠올려요.","크기가 아니에요.","두 쪽에 닿아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#22','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C11',3,'mc','auto','위선과 경선으로 위치를 나타내는 방법이 쓸모 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X18','SO6-1-u3-X19']::text[],false,'{"seq":22,"concept":"SO6-1-u3-C11","difficulty":3,"kind":"mc","stem":"위선과 경선으로 위치를 나타내는 방법이 쓸모 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지구처럼 넓은 곳에서도 두 선이 만나는 한 지점으로 자리를 정확하게 말할 수 있기 때문에","correct":true},{"t":"위선만 알면 자리가 정해지기 때문에","mis":"SO6-1-u3-X18"},{"t":"선을 긋는 차례에 따라 자리가 바뀌기 때문에","mis":"SO6-1-u3-X19"},{"t":"땅의 높낮이를 알려 주기 때문에","mis":"SO6-1-u3-X18"}],"explanation":["넓은 지구예요.","두 선이 만나요.","한 지점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#23','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C3',4,'essay','teacher','일지 ①의 세 모둠에게 알맞은 자료를 각각 고르고, 그 자료를 고른 까닭을 자료의 특징과 이어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C3","difficulty":4,"kind":"essay","stem":"일지 ①의 세 모둠에게 알맞은 자료를 각각 고르고, 그 자료를 고른 까닭을 자료의 특징과 이어 쓰세요.","answer_guide":{"answer":"예: 모둠 가는 세계를 한눈에 볼 수 있는 세계지도, 모둠 나는 위치와 면적이 비교적 정확한 지구본, 모둠 다는 거리 보기 기능으로 실제 모습을 사진으로 볼 수 있는 디지털 영상 지도가 알맞다. 세 자료는 좋고 나쁨이 아니라 쓰임이 달라 하려는 일에 따라 고른다.","scoring_points":["세 모둠에 알맞은 자료를 골랐는가","자료의 특징과 까닭을 이었는가","쓰임에 따라 고른다고 썼는가"]},"explanation":["한눈에 · 정확하게 · 실제 모습이에요.","특징을 붙여요.","쓰임이 달라요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#24','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C16',4,'essay','teacher','일지 ⑤의 엽서 세 장을 보낸 나라를 쓰고, 그 가운데 한 나라의 영토 특징이 그 나라 사람들의 생활이나 산업과 어떻게 이어질 수 있는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C16","difficulty":4,"kind":"essay","stem":"일지 ⑤의 엽서 세 장을 보낸 나라를 쓰고, 그 가운데 한 나라의 영토 특징이 그 나라 사람들의 생활이나 산업과 어떻게 이어질 수 있는지 쓰세요.","answer_guide":{"answer":"예: 엽서 1은 중국, 엽서 2는 오스트레일리아, 엽서 3은 니우에처럼 바다로 둘러싸인 섬나라이다. 섬나라는 바다로 둘러싸여 있어 수영과 다이빙을 즐기는 관광 산업이 발달할 수 있으므로, 영토의 특징이 그 나라의 산업에 영향을 준다.","scoring_points":["세 나라를 알맞게 썼는가","한 나라의 영토 특징을 썼는가","영토 특징과 생활·산업을 이었는가"]},"explanation":["동서로 넓은 나라예요.","나라가 곧 대륙이에요.","섬나라와 산업이에요."],"asset":{"type":"passage","lines":["엽서 1 — 영토가 동서로 넓은 나라: 서쪽으로 갈수록 땅이 높아져요.","엽서 2 — 오세아니아에서 가장 큰 나라: 나라 하나가 곧 대륙이에요.","엽서 3 — 바다로 둘러싸인 작은 섬나라: 다이빙하러 온 사람이 많아요."],"title":"일지 ⑤ — 아시아·오세아니아에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_a#25','soc',6,1,'u3','','g6_1_soc_u3_review_a','unit_review','SO6-1-u3-C26',4,'essay','teacher','일지 ⑧의 경로를 완성하고, 빠진 대륙에서 나라를 하나 골라 넣은 새 경로를 위치를 고려해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C26","difficulty":4,"kind":"essay","stem":"일지 ⑧의 경로를 완성하고, 빠진 대륙에서 나라를 하나 골라 넣은 새 경로를 위치를 고려해 쓰세요.","answer_guide":{"answer":"예: 일지 ⑧의 경로는 오스트레일리아 다음에 대한민국으로 돌아와야 완성된다. 빠진 북아메리카에서 미국을 골라 넣으면, 대한민국에서 출발해 중국 → 이집트 → 영국 → 브라질 → 미국 → 오스트레일리아를 거쳐 대한민국으로 돌아오는 경로를 만들 수 있다.","scoring_points":["출발한 곳으로 돌아와 경로를 완성했는가","빠진 대륙의 나라를 골랐는가","위치를 고려한 새 경로를 썼는가"]},"explanation":["끝이 출발한 곳이어야 해요.","빠진 대륙을 찾아요.","위치를 보고 넣어요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#1','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C2',1,'sa','auto','모둠 가가 고르기에 더 알맞은, 평면으로 된 자료의 이름을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u3-C2","difficulty":1,"kind":"sa","stem":"모둠 가가 고르기에 더 알맞은, 평면으로 된 자료의 이름을 쓰세요.","answer":["세계지도"],"explanation":["한눈에 봐요.","평면이에요.","세계지도예요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"},"mis":"SO6-1-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#2','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C9',1,'sa','auto','지구본의 세로선으로, 경도를 나타내는 선을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u3-C9","difficulty":1,"kind":"sa","stem":"지구본의 세로선으로, 경도를 나타내는 선을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["경선"],"explanation":["세로선이에요.","◯선이에요.","경선이에요."],"mis":"SO6-1-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#3','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C15',1,'sa','auto','일지 ④의 ㉡에 해당하는 바다의 이름을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"sa","stem":"일지 ④의 ㉡에 해당하는 바다의 이름을 쓰세요.","answer":["남극해"],"explanation":["남극 대륙을 둘러싸요.","남극◯예요.","남극해예요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"},"mis":"SO6-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#4','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C14',1,'sa','auto','세계의 대륙은 모두 몇 개인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-1-u3-C14","difficulty":1,"kind":"sa","stem":"세계의 대륙은 모두 몇 개인가요? 숫자만 쓰세요.","answer":["7","일곱"],"explanation":["남극 대륙도 세요.","대양보다 둘 많아요.","일곱 개예요."],"mis":"SO6-1-u3-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#5','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C18',1,'sa','auto','일지 ⑤의 엽서 2를 보낸 나라 이름을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u3-C18","difficulty":1,"kind":"sa","stem":"일지 ⑤의 엽서 2를 보낸 나라 이름을 쓰세요.","answer":["오스트레일리아","호주"],"explanation":["오세아니아에서 가장 커요.","나라가 곧 대륙이에요.","오스트레일리아예요."],"asset":{"type":"passage","lines":["엽서 1 — 영토가 동서로 넓은 나라: 서쪽으로 갈수록 땅이 높아져요.","엽서 2 — 오세아니아에서 가장 큰 나라: 나라 하나가 곧 대륙이에요.","엽서 3 — 바다로 둘러싸인 작은 섬나라: 다이빙하러 온 사람이 많아요."],"title":"일지 ⑤ — 아시아·오세아니아에서 온 엽서"},"mis":"SO6-1-u3-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#6','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C22',1,'sa','auto','일지 ⑥의 엽서 5를 보낸, 세계에서 가장 작은 나라의 이름을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u3-C22","difficulty":1,"kind":"sa","stem":"일지 ⑥의 엽서 5를 보낸, 세계에서 가장 작은 나라의 이름을 쓰세요.","answer":["바티칸 시국","바티칸"],"explanation":["수도에 둘러싸였어요.","바티칸 ◯◯이에요.","바티칸 시국이에요."],"asset":{"type":"passage","lines":["엽서 4 — 길게 뻗은 나라의 북쪽 섬들: 우리나라 과학 기지가 있어요.","엽서 5 — 다른 나라의 수도에 둘러싸인 아주 작은 나라예요.","엽서 6 — 아프리카 북동쪽 끝 나라: 국경선이 자로 그은 듯 반듯해요."],"title":"일지 ⑥ — 유럽·아프리카에서 온 엽서"},"mis":"SO6-1-u3-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#7','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C24',1,'sa','auto','일지 ⑦의 엽서 8을 보낸 나라 이름을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-1-u3-C24","difficulty":1,"kind":"sa","stem":"일지 ⑦의 엽서 8을 보낸 나라 이름을 쓰세요.","answer":["칠레"],"explanation":["남북으로 아주 길어요.","동쪽에 안데스산맥이 있어요.","칠레예요."],"asset":{"type":"passage","lines":["엽서 7 — 두 대륙을 잇는 좁고 잘록한 땅의 나라예요.","엽서 8 — 남북으로 아주 긴 나라: 동쪽에 높은 산맥이 있어요.","엽서 9 — 이웃 나라를 사이에 두고 본토와 떨어진 북쪽 지역이에요."],"title":"일지 ⑦ — 아메리카에서 온 엽서"},"mis":"SO6-1-u3-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#8','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C26',1,'sa','auto','여행 경로를 만들 때 고려해야 하는 것은 대륙 및 나라의 (    )예요. 빈칸에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"sa","stem":"여행 경로를 만들 때 고려해야 하는 것은 대륙 및 나라의 (    )예요. 빈칸에 알맞은 두 글자를 쓰세요.","answer":["위치"],"explanation":["어디에 있는지예요.","◯◯예요.","위치예요."],"mis":"SO6-1-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#9','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C5',2,'match','auto','하고 싶은 일과 디지털 영상 지도의 기능을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-1-u3-C5","difficulty":2,"kind":"match","stem":"하고 싶은 일과 디지털 영상 지도의 기능을 알맞게 이으세요.","pairs":[{"l":"찾고 싶은 곳의 위치 확인","r":"장소 검색"},{"l":"두 자리 사이의 곧은 거리 확인","r":"거리 측정"},{"l":"장소의 실제 모습 보기","r":"거리 보기"},{"l":"원하는 지도로 바꾸어 보기","r":"지도 유형 설정"}],"mis":"SO6-1-u3-X07","explanation":["찾기예요.","재기예요.","보기와 바꾸기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#10','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C8',2,'mc','auto','일지 ②의 기지 가와 기지 나에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X17','SO6-1-u3-X14']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C8","difficulty":2,"kind":"mc","stem":"일지 ②의 기지 가와 기지 나에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"기지 가가 햇볕을 더 많이 받아 기온이 더 높다","correct":true},{"t":"두 기지는 시각이 크게 다르다","mis":"SO6-1-u3-X17"},{"t":"기지 나가 햇볕을 더 많이 받는다","mis":"SO6-1-u3-X14"},{"t":"두 기지는 햇볕을 받는 양이 같다","mis":"SO6-1-u3-X17"}],"explanation":["경도는 같아요.","적도와 북극 가까이예요.","기지 가가 더 따뜻해요."],"asset":{"type":"passage","lines":["기지 가 — 적도 가까운 북쪽","기지 나 — 기지 가와 경도가 같고, 북극에 가까운 곳","기지 다 — 기지 가와 위도가 같고, 동쪽으로 멀리 떨어진 곳"],"title":"일지 ② — 상상 탐험 기지 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#11','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C12',2,'mc','auto','일지 ③의 ㉯에 해당하는 나라는 어디인가요?',ARRAY['SO6-1-u3-X20','SO6-1-u3-X34']::text[],false,'{"seq":11,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"mc","stem":"일지 ③의 ㉯에 해당하는 나라는 어디인가요?","options":[{"t":"영국","correct":true},{"t":"케냐","mis":"SO6-1-u3-X20"},{"t":"아이슬란드","mis":"SO6-1-u3-X34"},{"t":"독일","mis":"SO6-1-u3-X34"}],"explanation":["본초 자오선이 지나요.","섬나라예요.","영국이에요."],"asset":{"type":"passage","lines":["㉮ 적도가 지나는, 아프리카 동부의 나라","㉯ 본초 자오선이 지나는, 유럽 서쪽의 섬나라","㉰ 남위 10°~20°, 서경 40°~50° 범위가 속한 나라"],"title":"일지 ③ — 탐험 깃발 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#12','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C15',2,'match','auto','대양과 그 대양이 맞닿은 대륙을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"match","stem":"대양과 그 대양이 맞닿은 대륙을 알맞게 이으세요.","pairs":[{"l":"태평양","r":"아시아·오세아니아·북아메리카·남아메리카"},{"l":"인도양","r":"아시아·아프리카·오세아니아"},{"l":"북극해","r":"아시아·유럽·북아메리카"},{"l":"남극해","r":"남극 대륙"}],"mis":"SO6-1-u3-X26","explanation":["가장 넓은 대양은 네 대륙이에요.","북극 주변이에요.","남극 대륙 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#13','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C18',2,'mc','auto','뉴질랜드에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X28','SO6-1-u3-X29','SO6-1-u3-X27']::text[],false,'{"seq":13,"concept":"SO6-1-u3-C18","difficulty":2,"kind":"mc","stem":"뉴질랜드에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 개의 큰 섬과 여러 개의 작은 섬으로 이루어져 있다","correct":true},{"t":"나라 자체가 하나의 대륙이다","mis":"SO6-1-u3-X28"},{"t":"아라비아반도의 대부분을 차지한다","mis":"SO6-1-u3-X29"},{"t":"대부분 북반구에 있다","mis":"SO6-1-u3-X27"}],"explanation":["오세아니아의 섬나라예요.","큰 섬이 둘이에요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#14','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C20',2,'match','auto','유럽·아프리카의 나라와 영토 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO6-1-u3-C20","difficulty":2,"kind":"match","stem":"유럽·아프리카의 나라와 영토 특징을 알맞게 이으세요.","pairs":[{"l":"노르웨이","r":"길게 뻗고 해안선이 복잡함"},{"l":"독일","r":"아홉 나라와 국경을 맞댐"},{"l":"에티오피아","r":"접한 바다가 없음"},{"l":"남아프리카 공화국","r":"두 대양과 접한 남쪽 끝 나라"}],"mis":"SO6-1-u3-X34","explanation":["길게 뻗은 나라예요.","이웃이 많아요.","바다 없음과 남쪽 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#15','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C24',2,'match','auto','아메리카의 나라와 영토 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO6-1-u3-C24","difficulty":2,"kind":"match","stem":"아메리카의 나라와 영토 특징을 알맞게 이으세요.","pairs":[{"l":"브라질","r":"남아메리카에서 가장 넓음"},{"l":"칠레","r":"남북 길이가 매우 김"},{"l":"파라과이","r":"바다에 접하지 않음"},{"l":"멕시코","r":"북아메리카 남부에 길게 뻗음"}],"mis":"SO6-1-u3-X40","explanation":["가장 넓은 나라예요.","남북으로 긴 나라예요.","바다 없음과 북아메리카 남부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#16','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C26',2,'mc','auto','일지 ⑧의 경로에서 들른 나라들이 속한 대륙이 아닌 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":16,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"mc","stem":"일지 ⑧의 경로에서 들른 나라들이 속한 대륙이 아닌 것은 어느 것인가요?","options":[{"t":"북아메리카","correct":true},{"t":"아프리카","mis":"SO6-1-u3-X27"},{"t":"유럽","mis":"SO6-1-u3-X27"},{"t":"오세아니아","mis":"SO6-1-u3-X27"}],"explanation":["나라마다 대륙을 붙여요.","중국·이집트·영국·브라질·오스트레일리아예요.","북아메리카가 없어요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#17','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C6',3,'ox','auto','디지털 영상 지도로 같은 자리를 늘렸다 줄였다 하면 보고 있는 자리가 다른 곳으로 바뀌어요.',ARRAY['SO6-1-u3-X08']::text[],false,'{"seq":17,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"ox","stem":"디지털 영상 지도로 같은 자리를 늘렸다 줄였다 하면 보고 있는 자리가 다른 곳으로 바뀌어요.","answer":"X","reason_options":[{"t":"자리는 그대로이고 한 번에 보이는 만큼만 달라지기 때문에","correct":true},{"t":"화면을 늘리면 언제나 다른 나라로 옮겨 가기 때문에","mis":"SO6-1-u3-X08"}],"mis":"SO6-1-u3-X08","explanation":["자리는 같아요.","보이는 만큼이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#18','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C10',3,'ox','auto','경도가 같고 위도만 다른 두 곳은 시각이 같아요.',ARRAY['SO6-1-u3-X17']::text[],false,'{"seq":18,"concept":"SO6-1-u3-C10","difficulty":3,"kind":"ox","stem":"경도가 같고 위도만 다른 두 곳은 시각이 같아요.","answer":"O","reason_options":[{"t":"시각은 경도에 따라 달라지기 때문에","correct":true},{"t":"시각은 위도에 따라 달라지기 때문에","mis":"SO6-1-u3-X17"}],"mis":"SO6-1-u3-X17","explanation":["남북으로만 다르네요.","시각은 경도예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#19','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C15',3,'ox','auto','아프리카는 인도양과 맞닿아 있어요.',ARRAY['SO6-1-u3-X26']::text[],false,'{"seq":19,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"ox","stem":"아프리카는 인도양과 맞닿아 있어요.","answer":"O","reason_options":[{"t":"인도양은 아시아·아프리카·오세아니아에 접한 대양이기 때문에","correct":true},{"t":"인도양은 남극 대륙만 둘러싼 바다이기 때문에","mis":"SO6-1-u3-X26"}],"mis":"SO6-1-u3-X26","explanation":["인도양의 둘레예요.","아프리카가 들어 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#20','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C21',3,'ox','auto','아프리카 여러 나라의 국경선이 반듯한 것은 원래 살던 사람들이 정한 경계를 그대로 따랐기 때문이에요.',ARRAY['SO6-1-u3-X37']::text[],false,'{"seq":20,"concept":"SO6-1-u3-C21","difficulty":3,"kind":"ox","stem":"아프리카 여러 나라의 국경선이 반듯한 것은 원래 살던 사람들이 정한 경계를 그대로 따랐기 때문이에요.","answer":"X","reason_options":[{"t":"과거 식민지로 삼은 나라들이 원래 국경을 무시하고 직선을 그었기 때문에","correct":true},{"t":"아프리카의 땅이 모두 평평해서 저절로 반듯해졌기 때문에","mis":"SO6-1-u3-X37"}],"mis":"SO6-1-u3-X37","explanation":["누가 그었을까요?","원래 국경을 무시했어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#21','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C22',3,'ox','auto','나라 안의 나라는 다른 나라의 영토에 둘러싸여 있어요.',ARRAY['SO6-1-u3-X38']::text[],false,'{"seq":21,"concept":"SO6-1-u3-C22","difficulty":3,"kind":"ox","stem":"나라 안의 나라는 다른 나라의 영토에 둘러싸여 있어요.","answer":"O","reason_options":[{"t":"산마리노·바티칸 시국·레소토는 다른 나라의 영토 안에 자리 잡고 있기 때문에","correct":true},{"t":"나라 안의 나라는 모두 바다로 둘러싸인 섬나라이기 때문에","mis":"SO6-1-u3-X38"}],"mis":"SO6-1-u3-X38","explanation":["예를 떠올려요.","이탈리아·남아프리카 공화국이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#22','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C12',3,'ox','auto','적도와 본초 자오선은 모두 여러 나라를 지나요.',ARRAY['SO6-1-u3-X20']::text[],false,'{"seq":22,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"ox","stem":"적도와 본초 자오선은 모두 여러 나라를 지나요.","answer":"O","reason_options":[{"t":"적도는 케냐 등을, 본초 자오선은 영국 등을 지나기 때문에","correct":true},{"t":"두 선은 바다로만 지나기 때문에","mis":"SO6-1-u3-X20"}],"mis":"SO6-1-u3-X20","explanation":["적도가 지나는 나라예요.","본초 자오선이 지나는 나라예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#23','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C10',4,'essay','teacher','일지 ②의 세 기지 가운데 두 곳을 골라, 위도와 경도에 따라 무엇이 같고 무엇이 다른지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C10","difficulty":4,"kind":"essay","stem":"일지 ②의 세 기지 가운데 두 곳을 골라, 위도와 경도에 따라 무엇이 같고 무엇이 다른지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 기지 가와 기지 나는 경도가 같아 시각은 같지만, 위도가 달라 기지 가는 햇볕이 수직에 가깝게 들어와 기온이 높고 기지 나는 비스듬하게 들어와 기온이 낮다. 기지 가와 기지 다는 위도가 같아 햇볕을 받는 양은 비슷하지만 경도가 달라 시각이 다르다.","scoring_points":["두 기지의 같은 점을 썼는가","두 기지의 다른 점을 썼는가","위도·경도와 까닭을 이었는가"]},"explanation":["경도가 같으면 시각이 같아요.","위도가 다르면 햇볕이 달라요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["기지 가 — 적도 가까운 북쪽","기지 나 — 기지 가와 경도가 같고, 북극에 가까운 곳","기지 다 — 기지 가와 위도가 같고, 동쪽으로 멀리 떨어진 곳"],"title":"일지 ② — 상상 탐험 기지 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#24','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C20',4,'essay','teacher','일지 ⑥의 엽서 세 장을 보낸 나라를 쓰고, 엽서 6의 국경선이 반듯한 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C20","difficulty":4,"kind":"essay","stem":"일지 ⑥의 엽서 세 장을 보낸 나라를 쓰고, 엽서 6의 국경선이 반듯한 까닭을 쓰세요.","answer_guide":{"answer":"예: 엽서 4는 노르웨이, 엽서 5는 바티칸 시국, 엽서 6은 이집트이다. 이집트처럼 아프리카 여러 나라의 국경선 일부가 반듯한 것은 과거 유럽 여러 나라가 아프리카를 식민지로 삼으면서 원래 국경을 무시하고 위도나 경도에 따라 직선을 그어 새로운 국경으로 삼았기 때문이다.","scoring_points":["세 나라를 바르게 썼는가","반듯한 국경선의 까닭을 썼는가","원래 국경을 무시했다는 점을 썼는가"]},"explanation":["길게 뻗은 나라예요.","가장 작은 나라예요.","식민지와 직선이에요."],"asset":{"type":"passage","lines":["엽서 4 — 길게 뻗은 나라의 북쪽 섬들: 우리나라 과학 기지가 있어요.","엽서 5 — 다른 나라의 수도에 둘러싸인 아주 작은 나라예요.","엽서 6 — 아프리카 북동쪽 끝 나라: 국경선이 자로 그은 듯 반듯해요."],"title":"일지 ⑥ — 유럽·아프리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_b#25','soc',6,1,'u3','','g6_1_soc_u3_review_b','unit_review','SO6-1-u3-C26',4,'essay','teacher','[생각을 펼쳐요]에서 여행 경로를 만들고 소개하는 차례를 쓰고, 이 활동에서 어떤 자료를 왜 쓰는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C26","difficulty":4,"kind":"essay","stem":"[생각을 펼쳐요]에서 여행 경로를 만들고 소개하는 차례를 쓰고, 이 활동에서 어떤 자료를 왜 쓰는지 쓰세요.","answer_guide":{"answer":"예: 대륙별로 가 보고 싶은 나라를 하나씩 정하고 까닭을 쓴 뒤, 그 나라의 위치와 영토의 특징을 살펴보고, 위치를 고려해 여행 경로를 만들어 세계지도에 나타낸 다음 친구들에게 소개한다. 위치와 영토를 살펴볼 때는 지구본·세계지도·디지털 영상 지도를 쓰는데, 자료마다 쓰임이 달라 함께 쓰면 더 잘 알 수 있기 때문이다.","scoring_points":["활동 차례를 바르게 썼는가","쓰는 자료를 썼는가","자료를 쓰는 까닭을 썼는가"]},"explanation":["정하기 → 살펴보기예요.","만들기 → 소개하기예요.","세 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#1','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C5',1,'ox','auto','모둠 다는 디지털 영상 지도의 거리 보기 기능을 쓰면 좋아요.',ARRAY['SO6-1-u3-X07']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C5","difficulty":1,"kind":"ox","stem":"모둠 다는 디지털 영상 지도의 거리 보기 기능을 쓰면 좋아요.","answer":"O","reason_options":[{"t":"거리 보기로 여러 장소의 실제 모습을 사진으로 볼 수 있기 때문에","correct":true},{"t":"거리 보기는 두 자리 사이의 곧은 거리를 재는 기능이기 때문에","mis":"SO6-1-u3-X07"}],"mis":"SO6-1-u3-X07","explanation":["실제 모습이에요.","사진으로 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#2','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C9',1,'ox','auto','본초 자오선은 경도 0° 선이에요.',ARRAY['SO6-1-u3-X11']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C9","difficulty":1,"kind":"ox","stem":"본초 자오선은 경도 0° 선이에요.","answer":"O","reason_options":[{"t":"경도는 본초 자오선을 기준으로 동서로 나뉘기 때문에","correct":true},{"t":"본초 자오선은 위도의 기준선이기 때문에","mis":"SO6-1-u3-X11"}],"mis":"SO6-1-u3-X11","explanation":["경도의 기준이에요.","0°예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#3','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C15',1,'ox','auto','일지 ④의 ㉣은 남극 대륙이에요.',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"ox","stem":"일지 ④의 ㉣은 남극 대륙이에요.","answer":"O","reason_options":[{"t":"남극 대륙은 얼음으로 덮여 있어 매우 추워 사람이 살기 어렵기 때문에","correct":true},{"t":"남극 대륙은 대륙이 아니라 바다이기 때문에","mis":"SO6-1-u3-X23"}],"mis":"SO6-1-u3-X23","explanation":["얼음으로 덮였어요.","대륙이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#4','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C14',1,'ox','auto','세계의 대양은 태평양, 대서양, 인도양, 북극해, 남극해의 다섯이에요.',ARRAY['SO6-1-u3-X24']::text[],false,'{"seq":4,"concept":"SO6-1-u3-C14","difficulty":1,"kind":"ox","stem":"세계의 대양은 태평양, 대서양, 인도양, 북극해, 남극해의 다섯이에요.","answer":"O","reason_options":[{"t":"세계의 바다 가운데 넓은 바다 다섯을 대양이라 하기 때문에","correct":true},{"t":"대양은 대륙과 같은 일곱 개이기 때문에","mis":"SO6-1-u3-X24"}],"mis":"SO6-1-u3-X24","explanation":["넓은 바다예요.","다섯이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#5','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C18',1,'ox','auto','일지 ⑤의 엽서 3처럼 섬나라에는 바다를 즐기는 관광 산업이 발달할 수 있어요.',ARRAY['SO6-1-u3-X31']::text[],false,'{"seq":5,"concept":"SO6-1-u3-C18","difficulty":1,"kind":"ox","stem":"일지 ⑤의 엽서 3처럼 섬나라에는 바다를 즐기는 관광 산업이 발달할 수 있어요.","answer":"O","reason_options":[{"t":"영토의 특징이 산업에 영향을 주기 때문에","correct":true},{"t":"섬나라에서는 아무 산업도 할 수 없기 때문에","mis":"SO6-1-u3-X31"}],"mis":"SO6-1-u3-X31","explanation":["바다로 둘러싸였어요.","다이빙을 즐겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["엽서 1 — 영토가 동서로 넓은 나라: 서쪽으로 갈수록 땅이 높아져요.","엽서 2 — 오세아니아에서 가장 큰 나라: 나라 하나가 곧 대륙이에요.","엽서 3 — 바다로 둘러싸인 작은 섬나라: 다이빙하러 온 사람이 많아요."],"title":"일지 ⑤ — 아시아·오세아니아에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#6','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C21',1,'ox','auto','일지 ⑥의 엽서 6을 보낸 나라는 이집트예요.',ARRAY['SO6-1-u3-X36']::text[],false,'{"seq":6,"concept":"SO6-1-u3-C21","difficulty":1,"kind":"ox","stem":"일지 ⑥의 엽서 6을 보낸 나라는 이집트예요.","answer":"O","reason_options":[{"t":"이집트는 아프리카 북동쪽 끝에 있고 국경선 일부가 반듯하기 때문에","correct":true},{"t":"이집트는 아프리카의 남쪽 끝에 있기 때문에","mis":"SO6-1-u3-X36"}],"mis":"SO6-1-u3-X36","explanation":["북동쪽 끝이에요.","반듯한 국경선이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["엽서 4 — 길게 뻗은 나라의 북쪽 섬들: 우리나라 과학 기지가 있어요.","엽서 5 — 다른 나라의 수도에 둘러싸인 아주 작은 나라예요.","엽서 6 — 아프리카 북동쪽 끝 나라: 국경선이 자로 그은 듯 반듯해요."],"title":"일지 ⑥ — 유럽·아프리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#7','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C23',1,'ox','auto','일지 ⑦의 엽서 9는 미국의 알래스카 지역에서 보낸 것이에요.',ARRAY['SO6-1-u3-X39']::text[],false,'{"seq":7,"concept":"SO6-1-u3-C23","difficulty":1,"kind":"ox","stem":"일지 ⑦의 엽서 9는 미국의 알래스카 지역에서 보낸 것이에요.","answer":"O","reason_options":[{"t":"미국은 캐나다를 사이에 두고 본토와 알래스카 지역으로 나뉘기 때문에","correct":true},{"t":"알래스카는 캐나다의 본토이기 때문에","mis":"SO6-1-u3-X39"}],"mis":"SO6-1-u3-X39","explanation":["본토와 떨어졌어요.","북쪽 지역이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["엽서 7 — 두 대륙을 잇는 좁고 잘록한 땅의 나라예요.","엽서 8 — 남북으로 아주 긴 나라: 동쪽에 높은 산맥이 있어요.","엽서 9 — 이웃 나라를 사이에 두고 본토와 떨어진 북쪽 지역이에요."],"title":"일지 ⑦ — 아메리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#8','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C26',1,'ox','auto','가 보고 싶은 나라를 고른 까닭은 사람마다 달라도 괜찮아요.',ARRAY['SO6-1-u3-X43']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"ox","stem":"가 보고 싶은 나라를 고른 까닭은 사람마다 달라도 괜찮아요.","answer":"O","reason_options":[{"t":"어느 나라도 더 좋거나 나쁘지 않고 관심이 사람마다 다르기 때문에","correct":true},{"t":"정해진 나라를 골라야만 하기 때문에","mis":"SO6-1-u3-X43"}],"mis":"SO6-1-u3-X43","explanation":["까닭을 견주어 봐요.","사람마다 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#9','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C2',2,'error','auto','탐험 일지를 쓰며 세계지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X03','SO6-1-u3-X04','SO6-1-u3-X02']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C2","difficulty":2,"kind":"error","stem":"탐험 일지를 쓰며 세계지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「세계지도의 넓이는 지구본과 언제나 똑같이 나타나.」","correct":true,"mis_target":"SO6-1-u3-X03"},{"t":"친구 가 — 「둥근 표면을 펼친 빈 곳을 채워 만들어.」","mis":"SO6-1-u3-X04"},{"t":"친구 다 — 「접어서 들고 다니기 편리해.」","mis":"SO6-1-u3-X02"}],"explanation":["펼치면 달라질 수 있어요.","넓이도 달라 보여요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#10','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C8',2,'ox','auto','기지 가와 기지 나는 같은 때에 계절이 서로 반대예요.',ARRAY['SO6-1-u3-X15']::text[],false,'{"seq":10,"concept":"SO6-1-u3-C8","difficulty":2,"kind":"ox","stem":"기지 가와 기지 나는 같은 때에 계절이 서로 반대예요.","answer":"X","reason_options":[{"t":"두 기지 모두 적도의 북쪽, 같은 반구에 있기 때문에","correct":true},{"t":"기지 나는 경도가 달라 계절이 반대이기 때문에","mis":"SO6-1-u3-X15"}],"mis":"SO6-1-u3-X15","explanation":["두 기지는 어느 반구일까요?","둘 다 북쪽이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["기지 가 — 적도 가까운 북쪽","기지 나 — 기지 가와 경도가 같고, 북극에 가까운 곳","기지 다 — 기지 가와 위도가 같고, 동쪽으로 멀리 떨어진 곳"],"title":"일지 ② — 상상 탐험 기지 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#11','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C12',2,'mc','auto','일지 ③의 ㉰에 해당하는 나라는 어디인가요?',ARRAY['SO6-1-u3-X21']::text[],false,'{"seq":11,"concept":"SO6-1-u3-C12","difficulty":2,"kind":"mc","stem":"일지 ③의 ㉰에 해당하는 나라는 어디인가요?","options":[{"t":"브라질","correct":true},{"t":"미국","mis":"SO6-1-u3-X21"},{"t":"오스트레일리아","mis":"SO6-1-u3-X21"},{"t":"칠레","mis":"SO6-1-u3-X21"}],"explanation":["남위예요.","서경이에요.","브라질이에요."],"asset":{"type":"passage","lines":["㉮ 적도가 지나는, 아프리카 동부의 나라","㉯ 본초 자오선이 지나는, 유럽 서쪽의 섬나라","㉰ 남위 10°~20°, 서경 40°~50° 범위가 속한 나라"],"title":"일지 ③ — 탐험 깃발 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#12','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C14',2,'error','auto','지구본 수수께끼를 풀며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":12,"concept":"SO6-1-u3-C14","difficulty":2,"kind":"error","stem":"지구본 수수께끼를 풀며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「바다는 크든 작든 모두 대양이야.」","correct":true,"mis_target":"SO6-1-u3-X23"},{"t":"친구 가 — 「대륙은 바다로 둘러싸인 커다란 육지야.」","mis":"SO6-1-u3-X23"},{"t":"친구 나 — 「대양은 넓은 바다야.」","mis":"SO6-1-u3-X23"}],"explanation":["대양의 뜻을 떠올려요.","넓은 바다예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#13','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C16',2,'match','auto','아시아·오세아니아의 나라와 영토 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-1-u3-C16","difficulty":2,"kind":"match","stem":"아시아·오세아니아의 나라와 영토 특징을 알맞게 이으세요.","pairs":[{"l":"일본","r":"네 개의 큰 섬과 수천 개의 작은 섬"},{"l":"중국","r":"동서로 넓고 서쪽으로 갈수록 높아짐"},{"l":"사우디아라비아","r":"아라비아반도의 대부분"},{"l":"오스트레일리아","r":"나라 자체가 하나의 대륙"}],"mis":"SO6-1-u3-X29","explanation":["섬나라예요.","동서로 넓어요.","반도와 대륙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#14','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C22',2,'error','auto','나라 안의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X38']::text[],false,'{"seq":14,"concept":"SO6-1-u3-C22","difficulty":2,"kind":"error","stem":"나라 안의 나라를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「레소토는 이탈리아의 영토에 둘러싸여 있어.」","correct":true,"mis_target":"SO6-1-u3-X38"},{"t":"친구 가 — 「산마리노는 이탈리아의 영토에 둘러싸여 있어.」","mis":"SO6-1-u3-X38"},{"t":"친구 다 — 「바티칸 시국은 도시 국가야.」","mis":"SO6-1-u3-X38"}],"explanation":["레소토는 어느 대륙일까요?","아프리카 남부예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#15','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C25',2,'error','auto','지협을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X41']::text[],false,'{"seq":15,"concept":"SO6-1-u3-C25","difficulty":2,"kind":"error","stem":"지협을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「지협은 넓고 평평해서 두 대륙을 이어.」","correct":true,"mis_target":"SO6-1-u3-X41"},{"t":"친구 나 — 「지협은 두 육지를 잇는 좁고 잘록한 땅이야.」","mis":"SO6-1-u3-X41"},{"t":"친구 다 — 「두 아메리카는 파나마 지협으로 이어져.」","mis":"SO6-1-u3-X41"}],"explanation":["지협의 뜻을 떠올려요.","좁고 잘록해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#16','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C26',2,'error','auto','일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":16,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"error","stem":"일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「돌아오는 걸음을 더하면 들른 나라도 하나 늘어.」","correct":true,"mis_target":"SO6-1-u3-X42"},{"t":"친구 가 — 「대한민국으로 돌아와야 경로가 완성돼.」","mis":"SO6-1-u3-X42"},{"t":"친구 다 — 「들르는 차례는 위치를 보고 우리가 정해.」","mis":"SO6-1-u3-X42"}],"explanation":["돌아오는 곳은 어디인가요?","이미 다녀온 출발 자리예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#17','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C1',3,'error','auto','자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X02','SO6-1-u3-X03']::text[],false,'{"seq":17,"concept":"SO6-1-u3-C1","difficulty":3,"kind":"error","stem":"자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「지구본은 들고 다니기 편하고 한눈에 다 보여.」","correct":true,"mis_target":"SO6-1-u3-X02"},{"t":"친구 나 — 「지구본은 위치와 면적이 비교적 정확해.」","mis":"SO6-1-u3-X02"},{"t":"친구 다 — 「세계지도는 한눈에 보기 편해.」","mis":"SO6-1-u3-X03"}],"explanation":["공 모양을 떠올려요.","반대쪽이 가려져요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#18','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C8',3,'error','auto','일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X17','SO6-1-u3-X14','SO6-1-u3-X16']::text[],false,'{"seq":18,"concept":"SO6-1-u3-C8","difficulty":3,"kind":"error","stem":"일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「기지 다는 경도가 달라서 햇볕을 받는 양이 크게 달라.」","correct":true,"mis_target":"SO6-1-u3-X17"},{"t":"친구 가 — 「기지 나는 가보다 햇볕이 비스듬하게 들어와.」","mis":"SO6-1-u3-X14"},{"t":"친구 나 — 「기지 다는 가와 시각이 달라.」","mis":"SO6-1-u3-X16"}],"explanation":["햇볕은 무엇에 따라 달라지나요?","위도예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["기지 가 — 적도 가까운 북쪽","기지 나 — 기지 가와 경도가 같고, 북극에 가까운 곳","기지 다 — 기지 가와 위도가 같고, 동쪽으로 멀리 떨어진 곳"],"title":"일지 ② — 상상 탐험 기지 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#19','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C15',3,'error','auto','대양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X26','SO6-1-u3-X25']::text[],false,'{"seq":19,"concept":"SO6-1-u3-C15","difficulty":3,"kind":"error","stem":"대양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「태평양의 둘레에는 유럽이 있어.」","correct":true,"mis_target":"SO6-1-u3-X26"},{"t":"친구 가 — 「북극해는 북극 주변의 바다야.」","mis":"SO6-1-u3-X26"},{"t":"친구 다 — 「대서양은 태평양 다음으로 넓어.」","mis":"SO6-1-u3-X25"}],"explanation":["태평양의 둘레를 세요.","유럽은 없어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#20','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C23',3,'error','auto','북아메리카를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X39']::text[],false,'{"seq":20,"concept":"SO6-1-u3-C23","difficulty":3,"kind":"error","stem":"북아메리카를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「북아메리카에는 바다에 접하지 않은 나라도 있어.」","correct":true,"mis_target":"SO6-1-u3-X39"},{"t":"친구 나 — 「세계에서 가장 큰 섬인 그린란드가 있어.」","mis":"SO6-1-u3-X39"},{"t":"친구 다 — 「세 번째로 큰 대륙이야.」","mis":"SO6-1-u3-X39"}],"explanation":["북아메리카의 나라를 떠올려요.","모두 바다와 접해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#21','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C21',3,'error','auto','아프리카 나라를 적도로 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X35']::text[],false,'{"seq":21,"concept":"SO6-1-u3-C21","difficulty":3,"kind":"error","stem":"아프리카 나라를 적도로 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「마다가스카르는 적도의 북쪽에 있어.」","correct":true,"mis_target":"SO6-1-u3-X35"},{"t":"친구 가 — 「이집트는 적도의 북쪽에 있어.」","mis":"SO6-1-u3-X35"},{"t":"친구 나 — 「나미비아는 적도의 남쪽에 있어.」","mis":"SO6-1-u3-X35"}],"explanation":["마다가스카르를 찾아요.","적도의 아래쪽이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#22','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C13',3,'error','auto','공간 정보를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X22']::text[],false,'{"seq":22,"concept":"SO6-1-u3-C13","difficulty":3,"kind":"error","stem":"공간 정보를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지도는 공간 정보가 아니야.」","correct":true,"mis_target":"SO6-1-u3-X22"},{"t":"친구 가 — 「공간 정보는 물체의 위치나 특성에 관한 정보야.」","mis":"SO6-1-u3-X22"},{"t":"친구 다 — 「도시 계획에 공간 정보를 활용해.」","mis":"SO6-1-u3-X22"}],"explanation":["지도는 무엇을 나타내나요?","위치예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#23','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C12',4,'essay','teacher','일지 ③의 깃발 세 개에 해당하는 나라를 쓰고, ㉰처럼 범위로 나라를 찾는 방법을 차례대로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C12","difficulty":4,"kind":"essay","stem":"일지 ③의 깃발 세 개에 해당하는 나라를 쓰고, ㉰처럼 범위로 나라를 찾는 방법을 차례대로 쓰세요.","answer_guide":{"answer":"예: ㉮는 케냐, ㉯는 영국, ㉰는 브라질이다. 범위로 나라를 찾을 때는 먼저 남위인지 북위인지, 동경인지 서경인지 가려 적도와 본초 자오선의 어느 쪽인지 정한 뒤, 위도 범위와 경도 범위가 겹치는 곳을 찾는다.","scoring_points":["세 나라를 바르게 썼는가","반구를 먼저 가린다고 썼는가","두 범위가 겹치는 곳을 찾는다고 썼는가"]},"explanation":["적도·본초 자오선이에요.","방향부터 가려요.","겹치는 곳을 찾아요."],"asset":{"type":"passage","lines":["㉮ 적도가 지나는, 아프리카 동부의 나라","㉯ 본초 자오선이 지나는, 유럽 서쪽의 섬나라","㉰ 남위 10°~20°, 서경 40°~50° 범위가 속한 나라"],"title":"일지 ③ — 탐험 깃발 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#24','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C25',4,'essay','teacher','일지 ⑦의 엽서 세 장을 보낸 곳을 쓰고, 엽서 7의 나라가 두 대륙에 어떤 뜻을 갖는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C25","difficulty":4,"kind":"essay","stem":"일지 ⑦의 엽서 세 장을 보낸 곳을 쓰고, 엽서 7의 나라가 두 대륙에 어떤 뜻을 갖는지 쓰세요.","answer_guide":{"answer":"예: 엽서 7은 파나마, 엽서 8은 칠레, 엽서 9는 미국의 알래스카 지역이다. 파나마는 영토 전체가 북아메리카와 남아메리카를 잇는 지협이라 두 대륙에 함께 닿아 있어 두 대륙을 하나로 이어 준다.","scoring_points":["세 곳을 바르게 썼는가","지협의 뜻을 썼는가","두 대륙을 잇는다는 뜻을 썼는가"]},"explanation":["좁고 잘록한 땅이에요.","남북으로 긴 나라예요.","본토와 떨어진 곳이에요."],"asset":{"type":"passage","lines":["엽서 7 — 두 대륙을 잇는 좁고 잘록한 땅의 나라예요.","엽서 8 — 남북으로 아주 긴 나라: 동쪽에 높은 산맥이 있어요.","엽서 9 — 이웃 나라를 사이에 두고 본토와 떨어진 북쪽 지역이에요."],"title":"일지 ⑦ — 아메리카에서 온 엽서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_c#25','soc',6,1,'u3','','g6_1_soc_u3_review_c','unit_review','SO6-1-u3-C17',4,'essay','teacher','우리나라와 다른 대륙의 나라 하나를 골라 위치와 영토의 특징을 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C17","difficulty":4,"kind":"essay","stem":"우리나라와 다른 대륙의 나라 하나를 골라 위치와 영토의 특징을 견주어 쓰세요.","answer_guide":{"answer":"예: 우리나라는 북반구 아시아 대륙의 동쪽에 있고 영토가 남북으로 길며 삼면이 바다로 둘러싸여 있다. 남아메리카의 칠레는 대부분 남반구에 있고 동서 길이에 비해 남북 길이가 매우 길며 서쪽은 태평양과 접한다. 두 나라는 영토가 남북으로 길다는 점이 비슷하지만 있는 반구와 대륙이 다르다.","scoring_points":["우리나라의 위치와 영토를 썼는가","고른 나라의 위치와 영토를 썼는가","같은 점과 다른 점을 견주었는가"]},"explanation":["우리나라부터요.","다른 대륙의 나라예요.","같은 점과 다른 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#1','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C4',1,'blank','auto','디지털 영상 지도는 항공 사진이나 (    ) 영상에 장소의 이름과 경계선 등을 표시한 지도예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X06']::text[],false,'{"seq":1,"concept":"SO6-1-u3-C4","difficulty":1,"kind":"blank","stem":"디지털 영상 지도는 항공 사진이나 (    ) 영상에 장소의 이름과 경계선 등을 표시한 지도예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"위성","correct":true},{"t":"손 그림","mis":"SO6-1-u3-X06"},{"t":"지구본","mis":"SO6-1-u3-X06"},{"t":"달력","mis":"SO6-1-u3-X06"}],"explanation":["하늘 높이에서 찍어요.","◯◯ 영상이에요.","위성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#2','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C7',1,'blank','auto','적도를 기준으로 북쪽을 (    ), 남쪽을 남위라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X13']::text[],false,'{"seq":2,"concept":"SO6-1-u3-C7","difficulty":1,"kind":"blank","stem":"적도를 기준으로 북쪽을 (    ), 남쪽을 남위라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"북위","correct":true},{"t":"동경","mis":"SO6-1-u3-X13"},{"t":"서경","mis":"SO6-1-u3-X13"},{"t":"북극","mis":"SO6-1-u3-X13"}],"explanation":["적도 북쪽이에요.","북◯예요.","북위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#3','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',1,'blank','auto','일지 ④의 ㉢에 해당하는 바다는 (    )예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X26','SO6-1-u3-X24']::text[],false,'{"seq":3,"concept":"SO6-1-u3-C15","difficulty":1,"kind":"blank","stem":"일지 ④의 ㉢에 해당하는 바다는 (    )예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"북극해","correct":true},{"t":"남극해","mis":"SO6-1-u3-X26"},{"t":"인도양","mis":"SO6-1-u3-X26"},{"t":"아시아","mis":"SO6-1-u3-X24"}],"explanation":["북극 주변이에요.","세 대륙에 둘러싸여요.","북극해예요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
