INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#8','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C26',1,'blank','auto','[생각을 펼쳐요]에서는 대륙마다 가 보고 싶은 나라를 (    ) 정해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"blank","stem":"[생각을 펼쳐요]에서는 대륙마다 가 보고 싶은 나라를 (    ) 정해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하나씩","correct":true},{"t":"둘씩","mis":"SO6-1-u3-X42"},{"t":"모두","mis":"SO6-1-u3-X42"},{"t":"한 대륙에서만","mis":"SO6-1-u3-X42"}],"explanation":["표의 한 줄이에요.","대륙마다예요.","하나씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#9','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C6',2,'mc','auto','모둠 다가 그 거리가 세계의 어느 쪽에 있는지 먼저 알아보려 할 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X07','SO6-1-u3-X09']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"mc","stem":"모둠 다가 그 거리가 세계의 어느 쪽에 있는지 먼저 알아보려 할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"화면을 줄여 넓게 본다","correct":true},{"t":"화면을 크게 늘린다","mis":"SO6-1-u3-X08"},{"t":"거리 측정만 누른다","mis":"SO6-1-u3-X07"},{"t":"화면을 끄고 기억에 맡긴다","mis":"SO6-1-u3-X09"}],"explanation":["어느 쪽인지 알려면요?","넓게 봐야 해요.","줄여요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#10','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C9',2,'match','auto','두 기준선과 방향을 나타내는 낱말을 뜻과 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C9","difficulty":2,"kind":"match","stem":"두 기준선과 방향을 나타내는 낱말을 뜻과 알맞게 이으세요.","pairs":[{"l":"적도","r":"위도 0° 선"},{"l":"본초 자오선","r":"경도 0° 선"},{"l":"남위","r":"적도를 기준으로 남쪽"},{"l":"서경","r":"본초 자오선을 기준으로 서쪽"}],"mis":"SO6-1-u3-X13","explanation":["두 기준선이에요.","남쪽이에요.","서쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#11','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C11',2,'error','auto','탐험 깃발을 꽂으며 위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X18','SO6-1-u3-X19']::text[],false,'{"seq":11,"concept":"SO6-1-u3-C11","difficulty":2,"kind":"error","stem":"탐험 깃발을 꽂으며 위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「경선 하나만 말해도 자리는 하나로 정해져.」","correct":true,"mis_target":"SO6-1-u3-X18"},{"t":"친구 나 — 「위선과 경선이 만나는 지점으로 나타내.」","mis":"SO6-1-u3-X18"},{"t":"친구 다 — 「어느 선을 먼저 그어도 만나는 지점은 같아.」","mis":"SO6-1-u3-X19"}],"explanation":["경선 위의 자리를 세어요.","여럿이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#12','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',2,'ox','auto','모든 대륙을 합쳐도 태평양보다 면적이 작아요.',ARRAY['SO6-1-u3-X25']::text[],false,'{"seq":12,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"ox","stem":"모든 대륙을 합쳐도 태평양보다 면적이 작아요.","answer":"O","reason_options":[{"t":"태평양은 그만큼 넓은 대양이기 때문에","correct":true},{"t":"태평양은 가장 작은 대양이기 때문에","mis":"SO6-1-u3-X25"}],"mis":"SO6-1-u3-X25","explanation":["태평양을 떠올려요.","가장 넓어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#13','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C19',2,'error','auto','외교관이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X32']::text[],false,'{"seq":13,"concept":"SO6-1-u3-C19","difficulty":2,"kind":"error","stem":"외교관이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「외교관은 다른 나라와 의견을 주고받지 않아.」","correct":true,"mis_target":"SO6-1-u3-X32"},{"t":"친구 가 — 「우리나라를 대표해 여러 나라와 협력해.」","mis":"SO6-1-u3-X32"},{"t":"친구 나 — 「외교 문제를 해결하는 일을 해.」","mis":"SO6-1-u3-X32"}],"explanation":["외교관은 무엇을 할까요?","의견을 주고받아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#14','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C20',2,'ox','auto','스위스는 바다에 접하지 않은 나라예요.',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":14,"concept":"SO6-1-u3-C20","difficulty":2,"kind":"ox","stem":"스위스는 바다에 접하지 않은 나라예요.","answer":"O","reason_options":[{"t":"스위스는 여러 나라에 둘러싸여 있기 때문에","correct":true},{"t":"스위스는 바다로 둘러싸인 섬나라이기 때문에","mis":"SO6-1-u3-X34"}],"mis":"SO6-1-u3-X34","explanation":["지도에서 찾아요.","바다가 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#15','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C24',2,'ox','auto','남아메리카는 북아메리카의 남쪽에 있어요.',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":15,"concept":"SO6-1-u3-C24","difficulty":2,"kind":"ox","stem":"남아메리카는 북아메리카의 남쪽에 있어요.","answer":"O","reason_options":[{"t":"두 대륙은 파나마 지협으로 위아래로 이어져 있기 때문에","correct":true},{"t":"남아메리카는 북아메리카의 북쪽에 있기 때문에","mis":"SO6-1-u3-X27"}],"mis":"SO6-1-u3-X27","explanation":["이름을 떠올려요.","남쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#16','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C26',2,'ox','auto','일지 ⑧의 경로는 여섯 대륙 가운데 다섯 대륙의 나라를 들러요.',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":16,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"ox","stem":"일지 ⑧의 경로는 여섯 대륙 가운데 다섯 대륙의 나라를 들러요.","answer":"O","reason_options":[{"t":"아시아·아프리카·유럽·남아메리카·오세아니아의 나라를 들르기 때문에","correct":true},{"t":"여섯 대륙의 나라를 모두 들르기 때문에","mis":"SO6-1-u3-X27"}],"mis":"SO6-1-u3-X27","explanation":["대륙을 세어요.","북아메리카가 빠졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#17','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C6',3,'mc','auto','디지털 영상 지도로 탐험할 나라를 살펴본 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X09']::text[],false,'{"seq":17,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"mc","stem":"디지털 영상 지도로 탐험할 나라를 살펴본 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"알게 된 것을 일지에 적어 두고 다른 자료와도 견준다","correct":true},{"t":"화면에 다 있으니 적지 않는다","mis":"SO6-1-u3-X09"},{"t":"디지털 영상 지도만 믿고 다른 자료는 버린다","mis":"SO6-1-u3-X09"},{"t":"본 것은 바로 잊어도 된다","mis":"SO6-1-u3-X09"}],"explanation":["화면은 지금 것만 보여 줘요.","적어야 남아요.","다른 자료와도 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#18','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C12',3,'mc','auto','「북위 30°~40°, 서경 90°~100°」 범위를 찾을 때 맞는 방향은 어느 것인가요?',ARRAY['SO6-1-u3-X13']::text[],false,'{"seq":18,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「북위 30°~40°, 서경 90°~100°」 범위를 찾을 때 맞는 방향은 어느 것인가요?","options":[{"t":"적도의 북쪽, 본초 자오선의 서쪽","correct":true},{"t":"적도의 남쪽, 본초 자오선의 서쪽","mis":"SO6-1-u3-X13"},{"t":"적도의 북쪽, 본초 자오선의 동쪽","mis":"SO6-1-u3-X13"},{"t":"적도의 남쪽, 본초 자오선의 동쪽","mis":"SO6-1-u3-X13"}],"explanation":["북위예요.","서경이에요.","북쪽과 서쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#19','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C14',3,'mc','auto','세계의 대륙을 나누는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":19,"concept":"SO6-1-u3-C14","difficulty":3,"kind":"mc","stem":"세계의 대륙을 나누는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"주로 대양을 기준으로 나누고, 높은 산맥 등을 경계로 나누기도 한다","correct":true},{"t":"나라의 수로 나눈다","mis":"SO6-1-u3-X23"},{"t":"사람이 사는지로만 나눈다","mis":"SO6-1-u3-X23"},{"t":"위도와 경도의 크기로만 나눈다","mis":"SO6-1-u3-X23"}],"explanation":["바다를 떠올려요.","산맥도 있어요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#20','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C18',3,'mc','auto','오세아니아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27','SO6-1-u3-X28','SO6-1-u3-X26']::text[],false,'{"seq":20,"concept":"SO6-1-u3-C18","difficulty":3,"kind":"mc","stem":"오세아니아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"오스트레일리아 대륙 하나만으로 이루어져 있다","correct":true},{"t":"대부분 남반구에 있다","mis":"SO6-1-u3-X27"},{"t":"세계에서 가장 작은 대륙이다","mis":"SO6-1-u3-X28"},{"t":"동쪽에 태평양, 서쪽에 인도양이 있다","mis":"SO6-1-u3-X26"}],"explanation":["「알맞지 않은」 것을 골라요.","섬도 많아요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#21','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C24',3,'mc','auto','남아메리카에서 바다에 접하지 않은 나라끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":21,"concept":"SO6-1-u3-C24","difficulty":3,"kind":"mc","stem":"남아메리카에서 바다에 접하지 않은 나라끼리 짝지은 것은 어느 것인가요?","options":[{"t":"볼리비아, 파라과이","correct":true},{"t":"칠레, 아르헨티나","mis":"SO6-1-u3-X40"},{"t":"브라질, 에콰도르","mis":"SO6-1-u3-X40"},{"t":"페루, 칠레","mis":"SO6-1-u3-X40"}],"explanation":["바다에 닿지 않아요.","두 나라예요.","볼리비아와 파라과이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#22','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C12',3,'mc','auto','「남위 20°~30°, 동경 120°~130°」 범위가 속한 나라는 어디인가요?',ARRAY['SO6-1-u3-X21','SO6-1-u3-X20']::text[],false,'{"seq":22,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「남위 20°~30°, 동경 120°~130°」 범위가 속한 나라는 어디인가요?","options":[{"t":"오스트레일리아","correct":true},{"t":"브라질","mis":"SO6-1-u3-X21"},{"t":"미국","mis":"SO6-1-u3-X21"},{"t":"케냐","mis":"SO6-1-u3-X20"}],"explanation":["남위예요.","동경이에요.","오스트레일리아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#23','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',4,'essay','teacher','일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C15","difficulty":4,"kind":"essay","stem":"일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.","answer_guide":{"answer":"예: ㉠은 태평양, ㉡은 남극해, ㉢은 북극해, ㉣은 남극 대륙이다. 태평양은 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있고, 남극해는 남극 대륙을 둘러싼 바다로 둘레의 대륙이 남극 대륙 하나뿐이다.","scoring_points":["네 답을 바르게 썼는가","고른 둘의 위치를 썼는가","고른 둘의 특징을 썼는가"]},"explanation":["가장 넓은 바다예요.","두 극의 바다예요.","얼음 대륙이에요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#24','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C21',4,'essay','teacher','아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"essay","stem":"아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.","answer_guide":{"answer":"예: 아프리카는 유럽의 남쪽에 있으며 적도를 기준으로 북반구와 남반구에 걸쳐 있어, 북반구에 있는 나라도 남반구에 있는 나라도 있다. 그래서 적도를 선으로 그어 그것을 기준으로 북쪽에 있는 나라와 남쪽에 있는 나라로 나눌 수 있다.","scoring_points":["아프리카의 위치를 썼는가","두 반구에 걸쳐 있음을 썼는가","적도를 기준으로 나눈다고 썼는가"]},"explanation":["유럽의 남쪽이에요.","적도가 지나요.","적도로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#25','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C14',4,'essay','teacher','이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C14","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 대륙은 아시아, 오세아니아, 유럽, 아프리카, 북아메리카, 남아메리카, 남극 대륙이고, 대양은 태평양, 대서양, 인도양, 북극해, 남극해이다. 아시아는 동쪽의 태평양, 남쪽의 인도양, 북쪽의 북극해와 맞닿아 있고, 남극 대륙은 남극해에 둘러싸여 있다.","scoring_points":["대륙 일곱을 썼는가","대양 다섯을 썼는가","맞닿은 예를 들었는가"]},"explanation":["육지 일곱이에요.","바다 다섯이에요.","아시아를 예로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
